// ── Modalità ADD-ON (ingress) ────────────────────────────────────────────────
// Quando la dashboard è aperta dal pannello Frarik (ingress dell'add-on), il
// percorso contiene /api/hassio_ingress/<token>. In questa modalità NON usiamo
// né URL Nabu né token: si parla solo col backend dell'add-on, che fa da proxy
// verso Home Assistant ed è gated dalla licenza. La chiave viaggia in un cookie
// (così la portano automaticamente fetch, WebSocket e immagini).
const _IG_MATCH   = location.pathname.match(/^(.*\/api\/hassio_ingress\/[^/]+)/);
const INGRESS_BASE = _IG_MATCH ? _IG_MATCH[1] : '';
const ADDON_MODE   = !!INGRESS_BASE;
const ADDON_BASE   = location.origin + INGRESS_BASE; // origine + prefisso ingress
function _setLicCookie(k){
  if(!k) return;
  document.cookie = 'frarik_lic='+encodeURIComponent(k)+'; path='+(INGRESS_BASE||'/')+'; max-age=31536000; SameSite=Lax';
}
function _clearLicCookie(){
  document.cookie = 'frarik_lic=; path='+(INGRESS_BASE||'/')+'; max-age=0; SameSite=Lax';
}

// ── License key check ────────────────────────────────────────────────────────
const LICENSE_API = 'https://frarik-license.frarik.workers.dev/api/validate';
const LIC_KEY     = 'frarik_license';
const LIC_TS_KEY  = 'frarik_license_ts';
const LIC_CHECK_INTERVAL = 24 * 60 * 60 * 1000; // 24h

(function _initLicenseCheck(){
  const overlay = document.getElementById('lic-overlay');
  const input   = document.getElementById('lic-input');
  const btn     = document.getElementById('lic-btn');
  const err     = document.getElementById('lic-err');
  if(!overlay) return;

  function showOverlay(){ overlay.style.cssText+=';display:flex!important'; if(input) setTimeout(()=>input.focus(),50); }
  function hideOverlay(){ overlay.style.display='none'; }

  async function validate(key){
    err.style.display='none';
    btn.textContent='Verifica…'; btn.disabled=true;
    try{
      const K0 = key.toUpperCase().trim();
      const r = ADDON_MODE
        ? await fetch(ADDON_BASE+'/api/frarik/license', { headers:{'X-Frarik-Key': K0} })
        : await fetch(LICENSE_API, { method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({key: K0}) });
      const d = await r.json();
      if(d.valid){
        const K = key.toUpperCase().trim();
        localStorage.setItem(LIC_KEY, K);
        localStorage.setItem(LIC_TS_KEY, Date.now().toString());
        localStorage.setItem('frarik_lic_name', d.name||'');
        localStorage.setItem('frarik_lic_note', d.note||'');
        localStorage.setItem('frarik_lic_expires', d.expires||'');
        _setLicCookie(K);
        hideOverlay();
        // in modalità add-on la connessione parte solo dopo l'attivazione licenza
        if(ADDON_MODE && typeof connect==='function'){ try{ _connTargets=[]; _connIdx=0; connect(); }catch(e){} }
      } else {
        err.textContent = d.error || 'Chiave non valida.';
        err.style.display = 'block';
      }
    } catch(e){
      err.textContent = 'Errore di connessione. Riprova.';
      err.style.display = 'block';
    }
    btn.textContent='Attiva'; btn.disabled=false;
  }

  btn.addEventListener('click', ()=> validate(input.value));
  input.addEventListener('keydown', e=>{ if(e.key==='Enter') validate(input.value); });
  input.addEventListener('input', ()=>{ input.value=input.value.toUpperCase().replace(/[^A-Z0-9-]/g,''); });

  // Tolleranza quando il server licenze è IRRAGGIUNGIBILE (così un'interruzione
  // temporanea di Cloudflare non blocca chi ha una licenza valida). Oltre questa
  // finestra senza una verifica andata a buon fine → si blocca.
  const LIC_OFFLINE_GRACE = 3 * 24 * 60 * 60 * 1000; // 3 giorni

  // Ri-valida SEMPRE la chiave salvata contro il server. Una chiave revocata/scaduta
  // viene bloccata subito (al prossimo avvio/refresh, o entro 1h se l'app resta aperta).
  async function revalidate(){
    const key = localStorage.getItem(LIC_KEY);
    if(!key){ showOverlay(); return; }
    try{
      const r = ADDON_MODE
        ? await fetch(ADDON_BASE+'/api/frarik/license', { headers:{'X-Frarik-Key': key} })
        : await fetch(LICENSE_API, {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({key})});
      const d = await r.json();
      if(d.valid){
        localStorage.setItem(LIC_TS_KEY, Date.now().toString());
        localStorage.setItem('frarik_lic_name', d.name||'');
        localStorage.setItem('frarik_lic_note', d.note||'');
        localStorage.setItem('frarik_lic_expires', d.expires||'');
        _setLicCookie(key);
        hideOverlay();
      } else {
        // revocata o scaduta → rimuovi e blocca
        localStorage.removeItem(LIC_KEY);
        localStorage.removeItem(LIC_TS_KEY);
        localStorage.removeItem('frarik_lic_name');
        localStorage.removeItem('frarik_lic_note');
        localStorage.removeItem('frarik_lic_expires');
        _clearLicCookie();
        showOverlay();
      }
    } catch(e){
      // server non raggiungibile: tollera solo entro la finestra di grazia
      const ts = parseInt(localStorage.getItem(LIC_TS_KEY)||'0');
      if(!ts || (Date.now()-ts > LIC_OFFLINE_GRACE)) showOverlay();
      // altrimenti lascia passare (offline temporaneo)
    }
  }

  const saved = localStorage.getItem(LIC_KEY);
  if(!saved) showOverlay();
  else { _setLicCookie(saved); revalidate(); }   // cookie subito + verifica ad OGNI avvio

  // controllo periodico mentre l'app resta aperta → cattura la revoca senza reload
  setInterval(()=>{ if(localStorage.getItem(LIC_KEY)) revalidate(); }, 30*60*1000);

  // ── Ri-controllo al ritorno in PRIMO PIANO ───────────────────────────────────
  // Fondamentale per l'app mobile di Home Assistant: il WebView tiene la pagina in
  // memoria (non la ricarica) e sospende i timer in background. Quando l'utente
  // riapre la dashboard, questi eventi rilanciano la validazione → una licenza
  // revocata viene bloccata subito, anche senza ricaricare la pagina.
  let _lastRevalidate = Date.now();
  function _maybeRevalidate(){
    if(!localStorage.getItem(LIC_KEY)) return;
    // evita raffiche: al massimo una verifica ogni 30s
    if(Date.now()-_lastRevalidate < 30*1000) return;
    _lastRevalidate = Date.now();
    revalidate();
  }
  document.addEventListener('visibilitychange', ()=>{ if(document.visibilityState==='visible') _maybeRevalidate(); });
  window.addEventListener('pageshow', _maybeRevalidate);   // ritorno da bfcache
  window.addEventListener('focus', _maybeRevalidate);
})();

// ── Nasconde la barra HA ingress (ha-panel-app) ──────────────────────────────
(function(){
  if(window.parent===window) return;

  function shadowQuery(root, sel){
    try{
      const d=root.querySelector(sel); if(d) return d;
      for(const el of root.querySelectorAll('*')){
        if(el.shadowRoot){ const f=shadowQuery(el.shadowRoot,sel); if(f) return f; }
      }
    }catch(e){}
    return null;
  }

  function hideInShadow(sr){
    if(!sr) return false;
    // Inietta CSS nella shadow root (penetra l'encapsulation)
    try{
      const sheet=new window.parent.CSSStyleSheet();
      sheet.replaceSync(`
        app-header,app-toolbar,ha-top-app-bar-fixed,
        [slot="header"],.header,header{display:none!important;height:0!important}
        app-header-layout,app-drawer-layout,:host{padding-top:0!important;--header-height:0px}
        iframe{top:0!important;height:100%!important}
      `);
      sr.adoptedStyleSheets=[...sr.adoptedStyleSheets, sheet];
    }catch(e){}
    // Rimozione diretta come backup
    for(const s of ['app-header','ha-top-app-bar-fixed','[slot="header"]','header']){
      const el=sr.querySelector(s); if(el){ el.remove(); break; }
    }
    return true;
  }

  function tryHide(){
    try{
      const pd=window.parent.document;
      // HA 2024+: ha-panel-app è il wrapper ingress
      // HA precedente: hassio-addon-ingress-view o ha-panel-hassio
      for(const tag of ['ha-panel-app','hassio-addon-ingress-view','hassio-ingress-view','ha-panel-hassio']){
        const el=shadowQuery(pd, tag);
        if(el?.shadowRoot){ hideInShadow(el.shadowRoot); return true; }
      }
      return false;
    }catch(e){ return false; }
  }

  let done=false;
  [0,50,150,400,900,2000].forEach(d=>setTimeout(()=>{ if(!done) done=tryHide(); },d));
})();

// ── Splash screen (ex script inline in index.html) ────────────────────────
(function(){
  const s = document.getElementById('frk-splash'); if(!s) return;
  setTimeout(function(){
    s.classList.add('hide');
    setTimeout(function(){ if(s && s.parentNode) s.parentNode.removeChild(s); }, 650);
  }, 3500);
})();

