/* ── helpers griglia store ── */
function _iconHtml(icon){
  if(!icon) return '📦';
  if(/^mdi:/.test(icon)){
    const n=icon.slice(4).replace(/_/g,'-');
    return `<i class="mdi mdi-${eh(n)}" style="font-size:17px;line-height:1"></i>`;
  }
  return eh(icon);
}
function _pkgWizardConfigExists(cardId){
  try{
    const s=JSON.parse(localStorage.getItem('frarik_pkg_wizard_'+(cardId||'').toLowerCase())||'null');
    if(!s) return false;
    return Object.values(s).some(v=>v&&(typeof v==='string'?v.trim():Array.isArray(v)?v.length>0:true));
  }catch(e){ return false; }
}
const _pkgSilentUpdPending=new Set();
function _schedulePkgSilentUpd(cardId){
  if(_pkgSilentUpdPending.has(cardId)) return;
  _pkgSilentUpdPending.add(cardId);
  setTimeout(async()=>{
    try{ await _pkgUpdateCard(cardId,true); }
    catch(e){ console.warn('[frarik] silent PKG update failed',e); }
    finally{ _pkgSilentUpdPending.delete(cardId); }
  }, 800);
}
function _ghcPrevPh(icon, name){
  const PALS=[['#1e1b4b','#312e81'],['#064e3b','#065f46'],['#422006','#78350f'],['#1e3a5f','#1e40af'],['#4a044e','#701a75'],['#0c1a2e','#0c4a6e'],['#1f1235','#4c1d95'],['#0f2027','#203a43']];
  let h=0; for(let c=0;c<name.length;c++) h=(h*31+name.charCodeAt(c))&0xffffffff;
  const [c1,c2]=PALS[Math.abs(h)%PALS.length];
  return `<div class="ghc-prev-ph"><div class="ghc-prev-ph-bg" style="background:linear-gradient(135deg,${c1} 0%,${c2} 100%)"></div><div class="ghc-prev-ph-ico">${icon||'📦'}</div><div class="ghc-prev-ph-nm">${eh(name)}</div></div>`;
}
/* Genera badge PKG per card tile: null se nessun pkg richiesto */
function _pkgBadgeHtml(pkgInfo){
  if(!pkgInfo) return '';
  const on=pkgInfo.file?_pkgIsOnHA(pkgInfo.file):false;
  if(on) return '<span class="ghc-bdg pkg-ok ghc-bdgl"><i class="mdi mdi-package-variant-closed-check"></i> PKG ✓</span>';
  return '<span class="ghc-bdg pkg-req ghc-bdgl"><i class="mdi mdi-package-variant"></i> PKG richiesto</span>';
}

function _ghcDesc(cardId, sha){
  const FALLBACK='Card Lovelace';
  const reg=cardId?window.FratechCardRegistry?.[cardId]:null;
  const rd=reg?.desc||''; if(rd.length>4&&!rd.includes(FALLBACK)) return rd;
  if(sha&&_ghDescCache[sha]) return _ghDescCache[sha];
  if(cardId){
    try{
      const it=_jsStoreList().find(i=>(i.meta||{}).id===cardId);
      const md=it?.meta?.desc||''; if(md.length>4&&!md.includes(FALLBACK)) return md;
      if(it?.code){
        const d=_parseCardDesc(it.code); if(d) return d;
        return _ghcSmartDesc((it.meta&&it.meta.name)||cardId, it.code);
      }
    }catch(e){}
  }
  return _ghcSmartDesc(cardId||'', '');
}
function _ghcLivePrev(host, cardId){
  const reg=window.FratechCardRegistry?.[cardId];
  if(!reg){ host.innerHTML=_ghcPrevPh('📦', cardId); return; }
  host.innerHTML='';
  const hass=_haHassObj();
  const PW=300, hw=host.clientWidth||190, PH=200;
  const scale=(hw/PW).toFixed(3);
  const vH=Math.round(PH*PW/(hw||190));
  try{
    if(reg._lovelace===true){
      // Card lovelace (custom element con setConfig + hass)
      const tag=reg._tag||cardId;
      const wrap=document.createElement('div');
      wrap.style.cssText=`width:${PW}px;transform:scale(${scale});transform-origin:0 0;position:absolute;top:0;left:0`;
      const cel=document.createElement(tag);
      cel.style.cssText='display:block;width:100%;';
      wrap.appendChild(cel);
      host.appendChild(wrap);
      requestAnimationFrame(()=>{
        try{ if(typeof cel.setConfig==='function') cel.setConfig({type:'custom:'+tag}); }catch(e){}
        requestAnimationFrame(()=>{
          try{ cel.hass=hass; }catch(e){}
          // Dopo il render, riscala per far entrare tutta la card nel riquadro
          requestAnimationFrame(()=>{
            const wh=cel.scrollHeight||cel.offsetHeight||wrap.scrollHeight||0;
            if(wh>10){
              const fit=Math.min(hw/PW, PH/wh);
              wrap.style.transform=`scale(${fit.toFixed(3)})`;
            }
          });
        });
      });
    } else {
      // Card JS frarik con render() + mount() (pattern legacy — NON usa customElements)
      const existingCard=(cfg.pages||[]).flatMap(p=>(p.cards||[])).find(c=>c.type==='js-custom'&&c.jsCardId===cardId&&c.id);
      const existingBadge=(cfg.pages||[]).flatMap(p=>(p.headerBadges||[])).find(b=>b.jsCardId===cardId);
      const previewCard=existingCard||existingBadge||{id:'__prev__',type:'js-custom',jsCardId:reg.id||cardId,label:reg.name||cardId,icon:reg.icon||'📦',color:'#818cf8',entity:'',colSpan:reg.colSpan||2,rowSpan:reg.rowSpan||2};
      const html=reg.render?reg.render(previewCard,hass):'';
      if(!html){ host.innerHTML=_ghcPrevPh(reg.icon||'📦', reg.name||cardId); return; }
      const wrap=document.createElement('div');
      wrap.style.cssText=`width:${PW}px;height:${vH}px;transform:scale(${scale});transform-origin:0 0;position:absolute;top:0;left:0`;
      wrap.innerHTML=`<div style="position:relative;width:100%;height:100%;">${html}</div>`;
      host.appendChild(wrap);
      // Non chiamare mount() per camera-card (evita connessioni WebRTC/MJPEG nel preview)
      if(typeof reg.mount==='function'&&cardId!=='camera-card') try{ reg.mount(previewCard,hass,wrap.firstElementChild); }catch(e){}
    }
  }catch(e){ host.innerHTML=_ghcPrevPh(reg.icon||'📦', reg.name||cardId); }
}
function _ghcLivePrevBySha(host, sha){
  const code=_ghCodeCache[sha];
  if(!code){ host.innerHTML=_ghcPrevPh(_ghIconCache[sha]||'📦',''); return; }
  try{
    const res=_installCardCode(code);
    const cardId=(res.newCards&&res.newCards[0])||(res.tags&&res.tags[0])||null;
    if(cardId) _ghcLivePrev(host, cardId);
    else host.innerHTML=_ghcPrevPh(_ghIconCache[sha]||'📦','');
  }catch(e){ host.innerHTML=_ghcPrevPh(_ghIconCache[sha]||'📦',''); }
}
async function _ghsPreview(enc, nm, cardId){
  const modal=document.getElementById('ghs-prev-modal');
  const container=document.getElementById('ghs-prev-card');
  const note=document.getElementById('ghs-prev-note');
  document.getElementById('ghs-prev-title').textContent='👁 '+nm;
  container.innerHTML='<div style="display:flex;align-items:center;justify-content:center;min-height:160px;color:var(--muted);font-size:12px">⏳ Carico anteprima…</div>';
  note.textContent='';
  modal.classList.remove('off');
  let regCard=cardId?window.FratechCardRegistry[cardId]:null;
  let isTemp=false;
  if(!regCard){
    // Prima prova localStorage (card locali o installate ma non ancora nel registry)
    if(cardId){
      try{
        const stored=_jsStoreList().find(i=>(i.meta||{}).id===cardId);
        if(stored&&stored.code){
          const res=_installCardCode(stored.code);
          const rid=(res.newCards&&res.newCards[0])||(res.tags&&res.tags[0])||cardId;
          regCard=window.FratechCardRegistry[rid]||window.FratechCardRegistry[cardId];
        }
      }catch(e){}
    }
    // Poi prova GitHub (card non installate con enc valido)
    if(!regCard&&enc){
      try{
        const f=_ghsFind(enc); if(!f) throw new Error('File non trovato in cache');
        const code=await _ghDownload(f);
        const res=_installCardCode(code);
        const id=(res.newCards&&res.newCards[0])||(res.tags&&res.tags[0]);
        regCard=id?window.FratechCardRegistry[id]:null;
        isTemp=true;
      }catch(e){
        container.innerHTML=`<div style="padding:16px;color:#f87171;font-size:12px;text-align:center">⚠️ Impossibile caricare l'anteprima:<br>${eh(e.message)}</div>`;
        return;
      }
    }
  }
  if(!regCard){
    container.innerHTML='<div style="padding:16px;color:var(--muted);font-size:12px;text-align:center">Nessuna card trovata nel file</div>';
    return;
  }
  const dummyCard={id:'__preview__',type:'js-custom',jsCardId:regCard.id,label:regCard.name||nm,icon:regCard.icon||'📦',color:'#818cf8',entity:'',colSpan:2,rowSpan:2};
  container.innerHTML='';
  container.style.minHeight='160px';
  try{
    if(regCard._lovelace){
      const tag=regCard._tag||regCard.id;
      const cel=document.createElement(tag);
      try{ cel.setConfig({type:'custom:'+tag}); }catch(e){}
      cel.classList.add('frarik-lovel');
      try{ cel.hass=_haHassObj(); }catch(e){}
      cel.style.cssText='display:block;width:100%;min-height:160px';
      container.appendChild(cel);
    } else {
      const html=regCard.render?regCard.render(dummyCard,_haHassObj()):'';
      container.innerHTML=`<div style="position:relative;width:100%;min-height:160px">${html}</div>`;
      if(typeof regCard.mount==='function') try{ regCard.mount(dummyCard,_haHassObj(),container); }catch(e){}
    }
  }catch(e){
    container.innerHTML=`<div style="padding:16px;color:#f87171;font-size:12px;text-align:center">Errore render: ${eh(e.message)}</div>`;
  }
  note.textContent=isTemp?'Anteprima temporanea — non ancora installata':'';
}
const _GHS_CARDS_TABS=['cards-non-installate','cards-installate'];
const _GHS_DISTINTIVI_TABS=['distintivi-non-installate','distintivi-installate'];
const _GHS_PKG_TABS=['pkg-non-installati','pkg-installati'];
function _isPkgTab(){ return _GHS_PKG_TABS.includes(_ghsTab); }
async function _ghsLoadAllCardCaches(){
  const p=[];
  for(const k of ['js','distintivi']){
    if(!_ghsCache[k]){ const f=_GHS_FOLDERS[k]; p.push(_ghListFolder(f.path).then(files=>{ _ghsCache[k]=files.filter(x=>f.ext.test(x.name)&&!(f.exclude&&f.exclude.test(x.name))); }).catch(()=>{ if(!_ghsCache[k]) _ghsCache[k]=[]; })); }
  }
  if(p.length) await Promise.all(p);
}
function _ghsLoadFolderCache(key){
  if(_ghsCache[key]) return Promise.resolve();
  const f=_GHS_FOLDERS[key]; if(!f) return Promise.resolve();
  return _ghListFolder(f.path).then(files=>{ _ghsCache[key]=files.filter(x=>f.ext.test(x.name)&&!(f.exclude&&f.exclude.test(x.name))); }).catch(()=>{ if(!_ghsCache[key]) _ghsCache[key]=[]; });
}
function ghStoreTab(tab){
  _ghsTab=tab;
  const isCards=_GHS_CARDS_TABS.includes(tab);
  const isDistintivi=_GHS_DISTINTIVI_TABS.includes(tab);
  const isPkg=_GHS_PKG_TABS.includes(tab);
  [..._GHS_CARDS_TABS,..._GHS_DISTINTIVI_TABS,..._GHS_PKG_TABS,'updates','premium','local','saved'].forEach(t=>{ const b=document.getElementById('ghs-tab-'+t); if(b) b.classList.toggle('on',t===tab); });
  const cardsGrp=document.getElementById('ghs-tab-cards-grp'); if(cardsGrp) cardsGrp.classList.toggle('on',isCards);
  const distintiviGrp=document.getElementById('ghs-tab-distintivi-grp'); if(distintiviGrp) distintiviGrp.classList.toggle('on',isDistintivi);
  const pkgGrp=document.getElementById('ghs-tab-pkg-grp'); if(pkgGrp) pkgGrp.classList.toggle('on',isPkg);
  const cardsSubBar=document.getElementById('ghs-subtabs-cards'); if(cardsSubBar) cardsSubBar.style.display=isCards?'flex':'none';
  const distintiviSubBar=document.getElementById('ghs-subtabs-distintivi'); if(distintiviSubBar) distintiviSubBar.style.display=isDistintivi?'flex':'none';
  const pkgSubBar=document.getElementById('ghs-subtabs-pkg'); if(pkgSubBar) pkgSubBar.style.display=isPkg?'flex':'none';
  const s=document.getElementById('ghs-search'); if(s) s.value='';
  const sw=document.getElementById('ghs-search-wrap'); if(sw) sw.style.display=(tab==='saved'||tab==='updates')?'none':'';
  const loadEl=document.getElementById('ghs-load'); if(loadEl) loadEl.style.display=(tab==='local')?'':'none';
  if(isCards){
    _ghStoreRender();
    _ghsLoadFolderCache('js').then(()=>{ if(_GHS_CARDS_TABS.includes(_ghsTab)){ _ghFetchVerLabels('js'); _ghStoreRender(); } });
    return;
  }
  if(isDistintivi){
    _ghStoreRender();
    _ghsLoadFolderCache('distintivi').then(()=>{ if(_GHS_DISTINTIVI_TABS.includes(_ghsTab)){ _ghFetchVerLabels('distintivi'); _ghStoreRender(); } });
    return;
  }
  if(isPkg){
    _loadHaInstalledPkgs().then(()=>{ if(_isPkgTab()) _ghStoreRender(); });
    _ghStoreRender();
    if(!_ghsCache.pkg){ const fPkg=_GHS_FOLDERS['pkg']; _ghListFolder(fPkg.path).then(files=>{ _ghsCache.pkg=files.filter(x=>fPkg.ext.test(x.name)); if(_isPkgTab()) _ghStoreRender(); }).catch(()=>{}); }
    return;
  }
  if(tab==='updates'){
    _ghStoreRender();
    _ghsLoadAllCardCaches().then(()=>{ if(_ghsTab==='updates') _ghStoreRender(); });
    return;
  }
  if(tab==='premium'){
    if(_ghsCache['premium']!==undefined){ _ghStoreRender(); return; }
    document.getElementById('ghs-status').textContent='⏳ Carico da GitHub…';
    document.getElementById('ghs-list').innerHTML='';
    const f=_GHS_FOLDERS['premium']; if(!f) return;
    _ghListFolder(f.path).then(files=>{ _ghsCache['premium']=files.filter(x=>f.ext.test(x.name)&&!(f.exclude&&f.exclude.test(x.name))); if(_ghsTab==='premium') _ghStoreRender(); _ghFetchVerLabels('premium'); }).catch(()=>{ _ghsCache['premium']=[]; if(_ghsTab==='premium') _ghStoreRender(); });
    return;
  }
  if(tab==='local'){ _ghStoreRender(); _ghStoreInitDropzone(); return; }
  if(tab==='saved'){ _ghStoreRender(); return; }
}
/* Scarica e legge la versione (campo version:) dai file della cartella, con cache per
   sha (un solo fetch per versione di file). Aggiorna le etichette nello store. */
async function _ghFetchVerLabels(tab){
  const files=(_ghsCache[tab]||[]).filter(x=>x&&x.sha&&x.download_url&&!(x.sha in _ghVerCache));
  if(!files.length) return;
  let i=0; const CONC=5;
  async function worker(){
    while(i<files.length){
      const x=files[i++];
      try{
        const r=await fetch(x.download_url,{cache:'no-store'});
        if(r.ok){ const code=await r.text(); _ghCodeCache[x.sha]=code; _ghVerCache[x.sha]=_parseCardVersion(code)||''; const pd=_parseCardDesc(code); _ghDescCache[x.sha]=pd||_ghcSmartDesc(x.name.replace(/\.js$/i,''),code)||''; _ghIconCache[x.sha]=_parseCardIcon(code)||''; _ghPkgCache[x.sha]=_parsePkgInfo(code); }
        else { _ghVerCache[x.sha]=''; _ghDescCache[x.sha]=''; _ghPkgCache[x.sha]=null; }
      }
      catch(e){ _ghVerCache[x.sha]=''; _ghDescCache[x.sha]=''; }
    }
  }
  await Promise.all(Array.from({length:Math.min(CONC,files.length)}, worker));
  if(_ghsTab===tab) _ghStoreRender();
}
/* ═══ STORE PREVIEW CARD ═══ */
