function _ghStoreRender(){
  const tab=_ghsTab, list=document.getElementById('ghs-list'), status=document.getElementById('ghs-status');
  const q=(document.getElementById('ghs-search').value||'').toLowerCase().trim();
  if(tab==='cards-non-installate'){ _ghStoreRenderCardsNonInstallate(q); return; }
  if(tab==='cards-installate'){ _ghStoreRenderCardsInstallate(q); return; }
  if(tab==='distintivi-non-installate'){ _ghStoreRenderFolderNonInstallate(q,'distintivi','Tutti i distintivi sono installati — vai su "Installati"'); return; }
  if(tab==='distintivi-installate'){ _ghStoreRenderFolderInstallate(q,'distintivi'); return; }
  if(tab==='pkg-non-installati'){ _ghStoreRenderPkgNonInstallati(q); return; }
  if(tab==='pkg-installati'){ _ghStoreRenderPkgInstallati(q); return; }
  if(tab==='local'){ _ghStoreRenderInstalled(q,'local'); return; }
  if(tab==='premium'){ _ghStoreRenderPremium(q); return; }
  if(tab==='saved'){ _ghStoreRenderSaved(); return; }
  if(tab==='updates'){ _ghStoreRenderUpdates(); return; }
  const folder=_GHS_FOLDERS[tab]; const g=_ghCfg();
  let files=(_ghsCache[tab]||[]).slice();
  if(q) files=files.filter(f=>f.name.toLowerCase().includes(q));
  status.textContent=(_ghsCache[tab]||[]).length+' file'+(q?(' · '+files.length+' trovati'):'');
  if(!files.length){ list.innerHTML=`<div class="ghs-empty">${q?'Nessun risultato per "'+eh(q)+'"':'Nessun file in questa cartella su GitHub'}</div>`; return; }

  // ── Cartelle non-card (YAML): lista semplice a righe ──
  if(folder.kind!=='install'){
    const ico=folder.ico;
    const sorted=files.filter(f=>f&&f.name).sort((a,b)=>a.name.localeCompare(b.name));
    list.innerHTML=sorted.map(f=>{
      const nm=f.name.replace(/\.(js|ya?ml)$/i,''); const enc=encodeURIComponent(f.name);
      const addYaml=(tab==='yaml')?`<button class="ghs-btn ghs-btn-inst" data-action="_ghsYamlAdd" data-action-arg="${enc}"><i class="mdi mdi-plus"></i> Aggiungi</button>`:'';
      const acts=`${addYaml}<button class="ghs-btn ghs-btn-cp" data-action="_ghsCopy" data-action-arg="${enc}"><i class="mdi mdi-content-copy"></i> Copia</button><button class="ghs-btn ghs-btn-cp" data-action="_ghsDownload" data-action-arg="${enc}"><i class="mdi mdi-download"></i></button>`;
      return `<div class="ghs-row"><div class="ghs-ico">${ico}</div><div class="ghs-info"><div class="ghs-name">${eh(nm)}</div><div class="ghs-sub">${eh(f.name)}</div></div><div class="ghs-acts">${acts}</div></div>`;
    }).join('');
    return;
  }

  // ── Cartelle card (JS / Distintivi): griglia moderna ──
  const idFile=g.idFile||{};
  // Card JS: mostra solo card non installate (installate → tab Installate) e non-appliance (appliance → tab Elettrodomestici)
  if(tab==='js') files=files.filter(f=>!g.shas[f.name]&&_cardEffectiveTab(f,idFile)==='js');
  const _cpCards=(curPage()||{cards:[]}).cards||[];
  const usedInCurPage=new Set();
  _cpCards.forEach(c=>{ if(c.type==='js-custom'&&c.jsCardId==='sos-card'&&!(window.FratechCardRegistry?.[c.jsCardId]?.isDistintivo)) usedInCurPage.add(c.jsCardId); });
  ((curPage()||{}).headerBadges||[]).forEach(b=>{ if(b.type==='jsd'&&b.jsCardId) usedInCurPage.add(b.jsCardId); });
  const sorted=files.filter(f=>f&&f.name).sort((a,b)=>a.name.localeCompare(b.name));
  const installed=[], toInstall=[];
  sorted.forEach(f=>{
    if(g.shas[f.name]){
      if(g.shas[f.name]===f.sha) installed.push(f); // aggiornate → qui; con update → solo in tab "da aggiornare"
    } else { toInstall.push(f); }
  });

  const tileInstalled=(f)=>{
    const nm=f.name.replace(/\.(js|ya?ml)$/i,''); const enc=encodeURIComponent(f.name);
    const cardId=Object.keys(idFile).find(k=>idFile[k]===f.name)||null;
    const verGH=_ghVerCache[f.sha]||g.fileVersions[f.name]||(cardId&&_curStoreVersion(cardId))||'';
    const verLocal=cardId?(_curStoreVersion(cardId)||''):'';
    const hasUpdate=!!(g.shas[f.name]&&g.shas[f.name]!==f.sha);
    const inCurPage=!!(cardId&&usedInCurPage.has(cardId));
    const reg=cardId?window.FratechCardRegistry?.[cardId]:null;
    const icon=(reg?.icon)||(_jsStoreList().find(i=>(i.meta||{}).id===cardId)?.meta?.icon)||folder.ico||'📦';
    const desc=_ghcDesc(cardId,f.sha);
    const verLbl=hasUpdate&&verGH&&verLocal?`v${verLocal} → v${verGH}`:verGH?`v${verGH}`:verLocal?`v${verLocal}`:'';
    const st=hasUpdate?'upd':'ok';
    const prevHtml=cardId&&reg
      ?`<div class="ghc-prev-inner" data-prev-id="${eh(cardId)}"></div>`
      :`<div class="ghc-prev-inner" data-prev-sha="${eh(f.sha)}"></div>`;
    const pkgInfoInst=cardId?_pkgInfoForInstalledCard(cardId):(_ghPkgCache[f.sha]||null);
    const pkgVerLatest=_ghPkgCache[f.sha]?.ver||'';
    const pkgVerSaved=Object.entries(g.pkgVersions||{}).find(([k])=>k.toLowerCase()===(cardId||'').toLowerCase())?.[1]||'';
    const pkgIsOnHANow=pkgInfoInst?.file?_pkgIsOnHA(pkgInfoInst.file):false;
    const pkgVerChanged=!!(pkgVerLatest&&pkgIsOnHANow&&pkgVerLatest!==pkgVerSaved);
    const pkgFileName=(pkgInfoInst?.file||'').split('/').pop();
    const hasPkgUpdPending=!!(pkgFileName&&_pkgPending[pkgFileName]);
    const wizConfigOk=cardId?_pkgWizardConfigExists(cardId):false;
    const hasPkgUpd=(pkgVerChanged&&pkgIsOnHANow)||hasPkgUpdPending;
    if(hasPkgUpd&&wizConfigOk&&cardId) _schedulePkgSilentUpd(cardId);
    const pkgBdgInst=hasPkgUpd
      ?`<span class="ghc-bdg pkg-upd ghc-bdgl"><i class="mdi mdi-package-up"></i> PKG update</span>`
      :_pkgBadgeHtml(pkgInfoInst);
    const _inLabel=reg?.isDistintivo?'In intestazione':'In vista';
    const bdg=hasUpdate?`<span class="ghc-bdg upd">↑ Aggiornamento</span>`
      :inCurPage?`<span class="ghc-bdg cur">✓ ${_inLabel}</span>`
      :`<span class="ghc-bdg ok">● Installata</span>`;
    const updBtn=hasUpdate?`<button class="ghc-btn ghc-btn-upd" data-action="_ghsInstall" data-action-arg="${enc}"><i class="mdi mdi-update"></i> Aggiorna</button>`:'';
    const pkgUpdBtn=hasPkgUpd&&cardId?`<button class="ghc-btn ghc-btn-upd" data-action="_pkgUpdateCard" data-action-arg="${cardId}" style="background:rgba(251,146,60,.15);border-color:rgba(251,146,60,.4);color:#fb923c"><i class="mdi mdi-package-up"></i> Aggiorna PKG</button>`:'';
    const addBtn=cardId?(inCurPage
      ?`<span class="ghc-indash"><i class="mdi mdi-check-circle-outline"></i> ${_inLabel}</span>`
      :`<button class="ghc-btn ghc-btn-add" data-action="_jsStoreAddAndRefresh" data-action-args='["${cardId}"]'><i class="mdi mdi-plus"></i> Aggiungi</button>`)
      :`<button class="ghc-btn ghc-btn-inst" data-action="_ghsInstall" data-action-arg="${enc}"><i class="mdi mdi-download"></i> Installa</button>`;
    const delBtn=cardId?`<button class="ghc-btn-del" data-action="_ghsDeleteInstalled" data-action-arg="${cardId}" title="Disinstalla"><i class="mdi mdi-delete-outline"></i></button>`:'';
    const prevBtn=`<button class="ghc-btn-del" style="color:rgba(139,92,246,.8);background:rgba(139,92,246,.08);border-color:rgba(139,92,246,.22)" data-action="_ghsPreviewCard" data-action-arg="${enc}" title="Anteprima"><i class="mdi mdi-eye-outline"></i></button>`;
    return `<div class="ghc-tile st-${st}"><div class="ghc-strip ${st}"></div>
      <div class="ghc-prev">${prevHtml}<div class="ghc-prev-fade"></div>${bdg}${pkgBdgInst}</div>
      <div class="ghc-body"><div class="ghc-head"><div class="ghc-ico">${_iconHtml(icon)}</div><div class="ghc-meta"><div class="ghc-name">${eh(nm)}</div>${verLbl?`<div class="ghc-ver">${eh(verLbl)}</div>`:''}</div></div>
      ${desc?`<div class="ghc-desc">${eh(desc)}</div>`:''}
      <div class="ghc-acts">${pkgUpdBtn}${updBtn}${addBtn}${prevBtn}${delBtn}</div></div></div>`;
  };

  const tileToInstall=(f)=>{
    const nm=f.name.replace(/\.(js|ya?ml)$/i,''); const enc=encodeURIComponent(f.name);
    const verLbl=_ghVerCache[f.sha]||g.fileVersions[f.name]||'';
    const rawDesc=_ghDescCache[f.sha]||'';
    const desc=rawDesc||_ghcSmartDesc(nm,'');
    const icon=_ghIconCache[f.sha]||_ghcSmartIcon(nm)||folder.ico||'📦';
    const pkgInfoNew=_ghPkgCache[f.sha]||null;
    const pkgBdgNew=_pkgBadgeHtml(pkgInfoNew);
    const ghDel=`<button class="ghc-btn-del" data-action="_ghsDeleteFromGithub" data-action-arg="${enc}" title="Elimina da GitHub"><i class="mdi mdi-delete-forever-outline"></i></button>`;
    const mvBtn=`<button class="ghc-btn-del" data-action="_ghsMoveCard" data-action-arg="${enc}" title="Sposta in altro tab" style="color:rgba(255,255,255,.5)"><i class="mdi mdi-swap-horizontal"></i></button>`;
    const prevBtn=`<button class="ghc-btn-del" style="color:rgba(139,92,246,.8);background:rgba(139,92,246,.08);border-color:rgba(139,92,246,.22)" data-action="_ghsPreviewCard" data-action-arg="${enc}" title="Anteprima"><i class="mdi mdi-eye-outline"></i></button>`;
    return `<div class="ghc-tile st-new"><div class="ghc-strip new"></div>
      <div class="ghc-prev"><div class="ghc-prev-inner" data-prev-sha="${eh(f.sha)}"></div><div class="ghc-prev-fade"></div><span class="ghc-bdg new">⬇ Disponibile</span>${pkgBdgNew}</div>
      <div class="ghc-body"><div class="ghc-head"><div class="ghc-ico">${_iconHtml(icon)}</div><div class="ghc-meta"><div class="ghc-name">${eh(nm)}</div>${verLbl?`<div class="ghc-ver">v${eh(verLbl)}</div>`:''}</div></div>
      ${desc?`<div class="ghc-desc">${eh(desc)}</div>`:''}
      <div class="ghc-acts"><button class="ghc-btn ghc-btn-inst" data-action="_ghsInstall" data-action-arg="${enc}"><i class="mdi mdi-download"></i> Installa</button>${prevBtn}${mvBtn}${ghDel}</div></div></div>`;
  };

  list.innerHTML='<div class="ghc-grid">'
    +(installed.length?`<div class="ghc-sec"><span class="ghc-sec-dot ok"></span>Installate<span class="ghc-sec-cnt">${installed.length}</span></div>`+installed.map(tileInstalled).join(''):'')
    +`<div class="ghc-sec"><span class="ghc-sec-dot new"></span>Da installare<span class="ghc-sec-cnt">${toInstall.length}</span></div>`
    +(toInstall.length?toInstall.map(tileToInstall).join(''):`<div style="grid-column:1/-1"><div class="ghs-empty">${tab==='js'?'Tutte le card sono installate — vai su <b style="color:#7dd3fc">🗂 Installate</b>':'Tutte le card di questa cartella sono installate'}</div></div>`)
    +'</div>';

  requestAnimationFrame(()=>{
    list.querySelectorAll('[data-prev-id]').forEach(el=>{ _ghcLivePrev(el, el.dataset.prevId); });
    list.querySelectorAll('[data-prev-sha]').forEach(el=>{ _ghcLivePrevBySha(el, el.dataset.prevSha); });
  });
}
/* Schede "Installate" (origine github) e "Card locali" (origine local): gestisci le card installate */
function _ghStoreRenderInstalled(q, originFilter){
  const list=document.getElementById('ghs-list'), status=document.getElementById('ghs-status');
  // Includi sempre le card di sistema (builtin) nella tab 'local'
  let items=_jsStoreList().filter(i=>!i._builtin&&(i.origin||'github')===originFilter);
  const all=items.length;
  if(q) items=items.filter(i=>((i.meta||{}).name||(i.meta||{}).id||'').toLowerCase().includes(q));
  const lbl=originFilter==='local'?'card locali':'card da GitHub';
  status.textContent=all+' '+lbl+(q?(' · '+items.length+' trovate'):'');
  if(!items.length){
    const msg=originFilter==='local'
      ?(q?'Nessun risultato':'Nessuna card locale.<br>Usa la zona qui sotto per caricare un file <code>.js</code> dal PC.')
      :(q?'Nessun risultato':'Nessuna card installata da GitHub.<br>Installale dalle schede ⚡ Card JS · 🏷️ Distintivi.');
    list.innerHTML=`<div class="ghs-empty">${msg}</div>`; return;
  }
  const _lcCards=(curPage()||{cards:[]}).cards||[];
  const _usedLocal=new Set(); _lcCards.forEach(c=>{ if(c.type==='js-custom'&&c.jsCardId==='sos-card') _usedLocal.add(c.jsCardId); });
  // Card di sistema in cima, poi ordine alfabetico
  const sorted=[...items.filter(i=>i._builtin),...items.filter(i=>!i._builtin).sort((a,b)=>((a.meta||{}).name||'').localeCompare((b.meta||{}).name||''))];
  list.innerHTML='<div class="ghc-grid">'+sorted.map(i=>{
    const m=i.meta||{}; const inPage=_usedLocal.has(m.id); const id=m.id||'';
    const reg=id?window.FratechCardRegistry?.[id]:null;
    const icon=m.icon||reg?.icon||'📦';
    const desc=i._builtin?(m.desc||''):((_ghcDesc(id,null))||'');
    const st=inPage?'ok':'new';
    const prevHtml=reg
      ?`<div class="ghc-prev-inner" data-prev-id="${eh(id)}"></div>`
      :`<div class="ghc-prev-inner">${_ghcPrevPh(icon,m.name||id)}</div>`;
    const bdg=i._builtin
      ?`<span class="ghc-bdg" style="background:rgba(139,92,246,.2);color:#c4b5fd;border-color:rgba(139,92,246,.4)">🔐 Sistema</span>`
      :(inPage?`<span class="ghc-bdg cur">✓ In vista</span>`:`<span class="ghc-bdg ok">● Installata</span>`);
    const act=inPage
      ?`<span class="ghc-indash"><i class="mdi mdi-check-circle-outline"></i> In vista</span>`
      :`<button class="ghc-btn ghc-btn-add" data-action="_jsStoreAddAndRefresh" data-action-args='["${id}"]'><i class="mdi mdi-plus"></i> Aggiungi</button>`;
    const pub=(!i._builtin&&originFilter==='local')?`<button class="ghc-btn ghc-btn-pub" data-action="_ghsPublish" data-action-arg="${id}" title="Pubblica su GitHub"><i class="mdi mdi-upload"></i> Pubblica</button>`:'';
    const del=i._builtin
      ?`<button class="ghc-btn-del" data-action="_ghsDeleteInstalled" data-action-arg="${id}" title="Protetta da licenza" style="opacity:.4;cursor:default"><i class="mdi mdi-lock-outline"></i></button>`
      :`<button class="ghc-btn-del" data-action="_ghsDeleteInstalled" data-action-arg="${id}" title="Disinstalla"><i class="mdi mdi-delete-outline"></i></button>`;
    return `<div class="ghc-tile st-${st}"><div class="ghc-strip ${st}"></div>
      <div class="ghc-prev">${prevHtml}<div class="ghc-prev-fade"></div>${bdg}</div>
      <div class="ghc-body"><div class="ghc-head"><div class="ghc-ico">${icon}</div><div class="ghc-meta"><div class="ghc-name">${eh(m.name||id||'Card')}</div><div class="ghc-ver">v${eh(m.version||'?')}</div></div></div>
      ${desc?`<div class="ghc-desc">${eh(desc)}</div>`:''}
      <div class="ghc-acts">${pub}${act}${del}</div></div></div>`;
  }).join('')+'</div>';
  requestAnimationFrame(()=>{
    list.querySelectorAll('[data-prev-id]').forEach(el=>{ _ghcLivePrev(el, el.dataset.prevId); });
  });
}
function _ghStoreRenderPredefinite(q){
  const list=document.getElementById('ghs-list'), status=document.getElementById('ghs-status');
  let items=_jsStoreList().filter(i=>i._builtin);
  const all=items.length;
  if(q) items=items.filter(i=>((i.meta||{}).name||(i.meta||{}).id||'').toLowerCase().includes(q));
  status.textContent=all+' card predefinite'+(q?(' · '+items.length+' trovate'):'');
  const hdr=`<div style="margin-bottom:14px;padding:12px 14px;border-radius:12px;background:rgba(139,92,246,.08);border:1px solid rgba(139,92,246,.22);font-size:11px;color:rgba(255,255,255,.7);line-height:1.6"><b style="color:#c4b5fd">🛡️ Card Predefinite</b> — card integrate nel sistema Frarik, sempre disponibili e protette da licenza.<br><span style="opacity:.7">Non possono essere eliminate senza la chiave amministratore.</span></div>`;
  if(!items.length){ list.innerHTML=hdr+`<div class="ghs-empty">${q?`Nessun risultato per "${eh(q)}"`: 'Nessuna card predefinita disponibile.'}</div>`; return; }
  const _cpCards=(curPage()||{cards:[]}).cards||[];
  const usedInPillRow=new Set();
  ((curPage()||{}).headerBadges||[]).forEach(b=>{ if(b.type==='jsd'&&b.jsCardId) usedInPillRow.add(b.jsCardId); });
  const usedInClockBar=new Set();
  const _hbP=cfg.hdrBar||{};
  [...(_hbP.left||[]),...(_hbP.center||[]),...(_hbP.right||[])].forEach(it=>{ if(it&&it.type==='jsd'&&it.jsCardId) usedInClockBar.add(it.jsCardId); });
  const usedInCurPage=new Set();
  _cpCards.forEach(c=>{ if(c.type==='js-custom'&&c.jsCardId==='sos-card'&&!(window.FratechCardRegistry?.[c.jsCardId]?.isDistintivo)) usedInCurPage.add(c.jsCardId); });
  list.innerHTML=hdr+'<div class="ghc-grid">'+items.map(i=>{
    const m=i.meta||{}; const id=m.id||'';
    const reg=id?window.FratechCardRegistry?.[id]:null;
    const isDist=!!reg?.isDistintivo;
    const icon=m.icon||reg?.icon||'📦';
    const desc=m.desc||'';
    const inPillRow=usedInPillRow.has(id);
    const inClockBar=usedInClockBar.has(id);
    const inPage=isDist?(inPillRow||inClockBar):usedInCurPage.has(id);
    const st=inPage?'ok':'new';
    const prevHtml=reg
      ?`<div class="ghc-prev-inner" data-prev-id="${eh(id)}"></div>`
      :`<div class="ghc-prev-inner">${_ghcPrevPh(icon,m.name||id)}</div>`;
    const bdg=`<span class="ghc-bdg" style="background:rgba(139,92,246,.2);color:#c4b5fd;border-color:rgba(139,92,246,.4)">🔐 Sistema</span>`;
    let act;
    if(isDist){
      const dashPart=inPillRow
        ?`<span class="ghc-indash" style="flex:1"><i class="mdi mdi-check-circle-outline"></i> Dashboard</span>`
        :`<button class="ghc-btn ghc-btn-add" style="flex:1" data-action="_jsStoreAddToHeaderAndRefresh" data-action-args='["${id}"]'><i class="mdi mdi-view-dashboard-outline"></i> Dashboard</button>`;
      const headerPart=inClockBar
        ?`<span class="ghc-indash" style="flex:1"><i class="mdi mdi-check-circle-outline"></i> Header</span>`
        :`<button class="ghc-btn ghc-btn-add" style="flex:1" data-action="_jsStoreAddToClockBarAndRefresh" data-action-args='["${id}"]'><i class="mdi mdi-flag-outline"></i> Header</button>`;
      act=`<div style="display:flex;gap:6px;flex:1">${dashPart}${headerPart}</div>`;
    } else {
      act=inPage
        ?`<span class="ghc-indash"><i class="mdi mdi-check-circle-outline"></i> In vista</span>`
        :`<button class="ghc-btn ghc-btn-add" data-action="_jsStoreAddAndRefresh" data-action-args='["${id}"]'><i class="mdi mdi-plus"></i> Aggiungi</button>`;
    }
    const del=id==='sos-card'
      ?`<button class="ghc-btn-del" title="Rimuovi dallo Store (richiede chiave admin)" data-action="_sosStoreRemove"><i class="mdi mdi-delete-outline"></i></button>`
      :`<button class="ghc-btn-del" title="Protetta da licenza" style="opacity:.35;cursor:default"><i class="mdi mdi-lock-outline"></i></button>`;
    return `<div class="ghc-tile st-${st}"><div class="ghc-strip ${st}"></div>
      <div class="ghc-prev">${prevHtml}<div class="ghc-prev-fade"></div>${bdg}</div>
      <div class="ghc-body"><div class="ghc-head"><div class="ghc-ico">${icon}</div><div class="ghc-meta"><div class="ghc-name">${eh(m.name||id||'Card')}</div><div class="ghc-ver">v${eh(m.version||'?')}</div></div></div>
      ${desc?`<div class="ghc-desc">${eh(desc)}</div>`:''}
      <div class="ghc-acts">${act}${del}</div></div></div>`;
  }).join('')+'</div>';
  requestAnimationFrame(()=>{ list.querySelectorAll('[data-prev-id]').forEach(el=>{ _ghcLivePrev(el, el.dataset.prevId); }); });
}
/* ── STORE: tab overrides manuali ── */
const _TAB_OV_KEY='frarik_store_tab_ov';
function _getTabOverrides(){ try{ return JSON.parse(localStorage.getItem(_TAB_OV_KEY)||'{}')||{}; }catch(e){ return {}; } }
function _setTabOverride(filename, tab){ const ov=_getTabOverrides(); if(!tab){ delete ov[filename]; } else { ov[filename]=tab; } try{ localStorage.setItem(_TAB_OV_KEY, JSON.stringify(ov)); }catch(e){} }
function _cardEffectiveTab(f, idFile){
  const ov=_getTabOverrides(); if(ov[f.name]) return ov[f.name];
  if(_isElettrCard(f,idFile)) return 'elettrodomestici';
  return 'js';
}
function _ghsMoveCard(encodedName){
  const name=decodeURIComponent(encodedName);
  const ov=_getTabOverrides();
  const g=_ghCfg(); const idFile=g.idFile||{};
  const f={name,sha:(_ghsCache['js']||[]).find(x=>x.name===name)?.sha||''};
  const auto=_isElettrCard(f,idFile)?'elettrodomestici':'js';
  const current=ov[name]||'auto';
  const TABS=[{id:'js',lbl:'⚡ Card JS'},{id:'elettrodomestici',lbl:'🔌 Elettrodomestici'},{id:'auto',lbl:'🔄 Auto ('+auto+')'}];
  const pop=document.createElement('div');
  pop.style.cssText='position:fixed;inset:0;z-index:210000;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.55);backdrop-filter:blur(6px)';
  pop.innerHTML='<div style="background:#0b1525;border:1px solid rgba(255,255,255,.18);border-radius:16px;padding:18px 20px;min-width:240px;box-shadow:0 24px 80px rgba(0,0,0,.9)">'
    +'<div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;color:rgba(255,255,255,.4);margin-bottom:6px">Sposta in tab</div>'
    +'<div style="font-size:12px;font-weight:700;color:#38bdf8;margin-bottom:14px;word-break:break-all">'+eh(name.replace(/\.js$/i,''))+'</div>'
    +TABS.map(t=>'<button data-newtab="'+t.id+'" style="display:block;width:100%;padding:9px 14px;margin-bottom:6px;border-radius:10px;border:1px solid rgba(255,255,255,'+(current===t.id?'.3':'.1')+');background:rgba(255,255,255,'+(current===t.id?'.1':'.04')+');color:'+(current===t.id?'#38bdf8':'rgba(255,255,255,.7)')+';font-size:12px;font-weight:'+(current===t.id?'700':'500')+';cursor:pointer;text-align:left">'+t.lbl+(current===t.id?' <span style="float:right;font-size:10px;opacity:.6">✓</span>':'')+'</button>').join('')
    +'<button id="mv-cl" style="display:block;width:100%;padding:7px;margin-top:4px;border-radius:9px;border:none;background:rgba(255,255,255,.05);color:rgba(255,255,255,.4);font-size:11px;cursor:pointer">Annulla</button>'
    +'</div>';
  document.body.appendChild(pop);
  const close=()=>{ try{document.body.removeChild(pop);}catch(e){} };
  pop.querySelector('#mv-cl').addEventListener('click',close);
  pop.addEventListener('click',e=>{
    if(e.target===pop){ close(); return; }
    const btn=e.target.closest('[data-newtab]'); if(!btn) return;
    const nt=btn.dataset.newtab;
    _setTabOverride(name, nt==='auto'?null:nt);
    close();
    _ghStoreRender();
  });
}
/* ── TAB AGGIORNAMENTI: card + PKG con aggiornamento disponibile ── */
function _ghsUpdBadge(){
  const btn=document.getElementById('ghs-tab-updates'); if(!btn) return;
  const g=_ghCfg();
  const nc=_ghPending.filter(f=>g.shas[f.name]&&g.shas[f.name]!==f.sha).length;
  const np=Object.keys(_pkgPending).length;
  const n=nc+np;
  const lbl=btn.querySelector('.ghc-tab-lbl');
  if(lbl) lbl.textContent=n?'Aggiorna ('+n+')':'Aggiorna';
  btn.style.background=n?'rgba(251,146,60,.1)':'';
  btn.style.borderColor=n?'rgba(251,146,60,.45)':'';
}
function _ghStoreRenderUpdates(){
  try{ _ghsUpdBadge(); }catch(e){}
  const list=document.getElementById('ghs-list'), status=document.getElementById('ghs-status');
  const g=_ghCfg();
  const cardUpd=_ghPending.filter(f=>g.shas[f.name]&&g.shas[f.name]!==f.sha);
  const pkgKeys=Object.keys(_pkgPending);
  const total=cardUpd.length+pkgKeys.length;
  status.textContent=total
    ?total+' aggiornament'+(total===1?'o':'i')+' disponibil'+(total===1?'e':'i')
    :'✅ Tutto aggiornato';
  if(!total){
    list.innerHTML='<div style="text-align:center;padding:36px 0"><div style="font-size:38px;margin-bottom:10px">✅</div>'
      +'<div style="font-size:13px;font-weight:700;color:#f1f5f9;margin-bottom:5px">Tutto aggiornato</div>'
      +'<div style="font-size:11px;color:#64748b">Nessun aggiornamento disponibile<br>Usa ↻ Sync per verificare</div></div>';
    return;
  }
  let html='';
  if(cardUpd.length){
    html+='<div class="ghc-sec"><span class="ghc-sec-dot upd"></span>Card JS<span class="ghc-sec-cnt">'+cardUpd.length+'</span></div>';
    html+=cardUpd.map(f=>{
      const nm=f.name.replace(/\.js$/i,'');
      const verNew=_ghVerCache[f.sha]||'';
      const verOld=g.fileVersions[f.name]||'';
      const verLbl=verNew&&verOld?'v'+verOld+' → v'+verNew:verNew?'→ v'+verNew:verOld?'v'+verOld:'';
      return '<div class="ghs-row">'
        +'<div class="ghs-ico" style="font-size:18px">⚡</div>'
        +'<div class="ghs-info"><div class="ghs-name" style="display:flex;align-items:center;gap:6px">'+eh(nm)
        +(verLbl?'<span style="font-size:10px;font-weight:700;color:#60a5fa">'+eh(verLbl)+'</span>':'')
        +'</div></div>'
        +'<div class="ghs-acts"><button class="ghs-btn ghs-btn-upd" data-action="_ghsInstall" data-action-arg="'+encodeURIComponent(f.name)+'">'
        +'<i class="mdi mdi-update"></i> Aggiorna</button></div></div>';
    }).join('');
  }
  if(pkgKeys.length){
    html+='<div class="ghc-sec" style="margin-top:'+(cardUpd.length?'16':'0')+'px">'
      +'<span class="ghc-sec-dot" style="background:#fb923c"></span>PKG Home Assistant<span class="ghc-sec-cnt">'+pkgKeys.length+'</span></div>';
    html+=pkgKeys.map(fn=>{
      const nm=fn.replace(/\.ya?ml$/i,'');
      return '<div class="ghs-row">'
        +'<div class="ghs-ico" style="font-size:18px">📦</div>'
        +'<div class="ghs-info"><div class="ghs-name">'+eh(nm)+'</div></div>'
        +'<div class="ghs-acts"><button class="ghs-btn ghs-btn-upd" data-action="_ghsPkgUpdFromPending" data-action-arg="'+encodeURIComponent(fn)+'" '
        +'style="background:rgba(251,146,60,.15);border-color:rgba(251,146,60,.4);color:#fb923c">'
        +'<i class="mdi mdi-package-up"></i> Aggiorna PKG</button>'
        +'<button class="ghs-btn" data-action="_ghsPkgMarkUpdated" data-action-arg="'+encodeURIComponent(fn)+'" '
        +'style="background:rgba(74,222,128,.1);border-color:rgba(74,222,128,.3);color:#4ade80">✓ Già aggiornato</button></div></div>';
    }).join('');
  }
  list.innerHTML=html;
}
/* ── TAB INSTALLATE: tutte le card-js installate ── */
function _ghStoreRenderInstallate(q){
  const list=document.getElementById('ghs-list'), status=document.getElementById('ghs-status');
  const g=_ghCfg(); const idFile=g.idFile||{};
  const _cpCards=(curPage()||{cards:[]}).cards||[];
  const usedInCurPage=new Set();
  _cpCards.forEach(c=>{ if(c.type==='js-custom'&&c.jsCardId==='sos-card'&&!(window.FratechCardRegistry?.[c.jsCardId]?.isDistintivo)) usedInCurPage.add(c.jsCardId); });
  ((curPage()||{}).headerBadges||[]).forEach(b=>{ if(b.type==='jsd'&&b.jsCardId) usedInCurPage.add(b.jsCardId); });
  let files=(_ghsCache['js']||[]).filter(f=>g.shas[f.name]&&g.shas[f.name]===f.sha);
  if(q) files=files.filter(f=>f.name.toLowerCase().includes(q));
  const available=(_ghsCache['js']||[]).filter(f=>!g.shas[f.name]&&(!q||f.name.toLowerCase().includes(q)));
  status.textContent=files.length+' installate · '+available.length+' disponibili';
  const TAB_LBL={'js':'⚡ Card JS','elettrodomestici':'🔌 Elettrodomestici'};
  const sorted=files.slice().sort((a,b)=>a.name.localeCompare(b.name));
  const tile=(f)=>{
    const nm=f.name.replace(/\.(js|ya?ml)$/i,''); const enc=encodeURIComponent(f.name);
    const cardId=Object.keys(idFile).find(k=>idFile[k]===f.name)||null;
    const verGH=_ghVerCache[f.sha]||g.fileVersions[f.name]||(cardId&&_curStoreVersion(cardId))||'';
    const verLocal=cardId?(_curStoreVersion(cardId)||''):'';
    const hasUpdate=!!(g.shas[f.name]&&g.shas[f.name]!==f.sha);
    const inCurPage=!!(cardId&&usedInCurPage.has(cardId));
    const reg=cardId?window.FratechCardRegistry?.[cardId]:null;
    const icon=(reg?.icon)||(_jsStoreList().find(i=>(i.meta||{}).id===cardId)?.meta?.icon)||'📦';
    const desc=_ghcDesc(cardId,f.sha);
    const verLbl=hasUpdate&&verGH&&verLocal?`v${verLocal} → v${verGH}`:verGH?`v${verGH}`:verLocal?`v${verLocal}`:'';
    const st=hasUpdate?'upd':'ok';
    const prevHtml=cardId&&reg?`<div class="ghc-prev-inner" data-prev-id="${eh(cardId)}"></div>`:`<div class="ghc-prev-inner" data-prev-sha="${eh(f.sha)}"></div>`;
    const pkgInfoInst=cardId?_pkgInfoForInstalledCard(cardId):(_ghPkgCache[f.sha]||null);
    const pkgBdgInst=_pkgBadgeHtml(pkgInfoInst);
    const _inLabel=reg?.isDistintivo?'In intestazione':'In vista';
    const bdg=hasUpdate?`<span class="ghc-bdg upd">↑ Aggiornamento</span>`:inCurPage?`<span class="ghc-bdg cur">✓ ${_inLabel}</span>`:`<span class="ghc-bdg ok">● Installata</span>`;
    const effTab=_cardEffectiveTab(f,idFile);
    const tabBdg=TAB_LBL[effTab]?`<span class="ghc-bdg" style="background:rgba(255,255,255,.07);border-color:rgba(255,255,255,.15);color:rgba(255,255,255,.55);font-size:9px">${TAB_LBL[effTab]}</span>`:'';
    const updBtn=hasUpdate?`<button class="ghc-btn ghc-btn-upd" data-action="_ghsInstall" data-action-arg="${enc}"><i class="mdi mdi-update"></i> Aggiorna</button>`:'';
    const addBtn=!hasUpdate&&cardId?(inCurPage?`<span class="ghc-indash"><i class="mdi mdi-check-circle-outline"></i> ${_inLabel}</span>`:`<button class="ghc-btn ghc-btn-add" data-action="_jsStoreAddAndRefresh" data-action-args='["${cardId}"]'><i class="mdi mdi-plus"></i> Aggiungi</button>`):'';
    const mvBtn=`<button class="ghc-btn-del" data-action="_ghsMoveCard" data-action-arg="${enc}" title="Sposta in altro tab" style="color:rgba(255,255,255,.5)"><i class="mdi mdi-swap-horizontal"></i></button>`;
    const delBtn=cardId?`<button class="ghc-btn-del" data-action="_ghsDeleteInstalled" data-action-arg="${cardId}" title="Disinstalla"><i class="mdi mdi-delete-outline"></i></button>`:'';
    return `<div class="ghc-tile st-${st}"><div class="ghc-strip ${st}"></div>
      <div class="ghc-prev">${prevHtml}<div class="ghc-prev-fade"></div>${bdg}${pkgBdgInst}</div>
      <div class="ghc-body"><div class="ghc-head"><div class="ghc-ico">${_iconHtml(icon)}</div><div class="ghc-meta"><div class="ghc-name">${eh(nm)}</div>${verLbl?`<div class="ghc-ver">${eh(verLbl)}</div>`:''}</div></div>
      ${tabBdg?`<div style="margin:2px 0 4px">${tabBdg}</div>`:''}
      ${desc?`<div class="ghc-desc">${eh(desc)}</div>`:''}
      <div class="ghc-acts">${updBtn}${addBtn}${mvBtn}${delBtn}</div></div></div>`;
  };
  const tileAvail=(f)=>{
    const nm=f.name.replace(/\.(js|ya?ml)$/i,''); const enc=encodeURIComponent(f.name);
    const verLbl=_ghVerCache[f.sha]||g.fileVersions[f.name]||'';
    const icon=_ghIconCache[f.sha]||_ghcSmartIcon(nm)||'📦';
    const desc=_ghDescCache[f.sha]||_ghcSmartDesc(nm,'');
    const pkgBdg=_pkgBadgeHtml(_ghPkgCache[f.sha]||null);
    return `<div class="ghc-tile st-new"><div class="ghc-strip new"></div>
      <div class="ghc-prev"><div class="ghc-prev-inner" data-prev-sha="${eh(f.sha)}"></div><div class="ghc-prev-fade"></div><span class="ghc-bdg new">⬇ Disponibile</span>${pkgBdg}</div>
      <div class="ghc-body"><div class="ghc-head"><div class="ghc-ico">${_iconHtml(icon)}</div><div class="ghc-meta"><div class="ghc-name">${eh(nm)}</div>${verLbl?`<div class="ghc-ver">v${eh(verLbl)}</div>`:''}</div></div>
      ${desc?`<div class="ghc-desc">${eh(desc)}</div>`:''}
      <div class="ghc-acts"><button class="ghc-btn ghc-btn-inst" data-action="_ghsInstall" data-action-arg="${enc}"><i class="mdi mdi-download"></i> Installa</button></div></div></div>`;
  };
  let _html='';
  if(sorted.length){
    _html+=`<div class="ghc-sec"><span class="ghc-sec-dot ok"></span>Installate<span class="ghc-sec-cnt">${sorted.length}</span></div>`;
    _html+=sorted.map(tile).join('');
  } else {
    _html+=`<div style="grid-column:1/-1"><div class="ghs-empty">${q?`Nessun risultato per "${eh(q)}"`: 'Nessuna card JS installata da GitHub.'}</div></div>`;
  }
  if(available.length){
    _html+=`<div class="ghc-sec"><span class="ghc-sec-dot new"></span>Da installare<span class="ghc-sec-cnt">${available.length}</span></div>`;
    _html+=available.map(tileAvail).join('');
  }
  list.innerHTML='<div class="ghc-grid">'+_html+'</div>';
  requestAnimationFrame(()=>{
    list.querySelectorAll('[data-prev-id]').forEach(el=>{ _ghcLivePrev(el, el.dataset.prevId); });
    list.querySelectorAll('[data-prev-sha]').forEach(el=>{ _ghcLivePrevBySha(el, el.dataset.prevSha); });
  });
}
/* ── Funzione generica: folder non installate (js / distintivi) ── */
function _ghStoreRenderFolderNonInstallate(q, cacheKey, emptyMsg){
  const list=document.getElementById('ghs-list'), status=document.getElementById('ghs-status');
  const g=_ghCfg();
  let files=(_ghsCache[cacheKey]||[]).filter(f=>!g.shas[f.name]);
  if(q) files=files.filter(f=>f.name.toLowerCase().includes(q));
  const sorted=files.slice().sort((a,b)=>a.name.localeCompare(b.name));
  status.textContent=sorted.length+' da installare'+(q?' trovati':'');
  if(!sorted.length){
    const msg=q?`Nessun risultato per "${eh(q)}"`:_ghsCache[cacheKey]?emptyMsg:'⏳ Caricamento da GitHub…';
    list.innerHTML=`<div class="ghs-empty">${msg}</div>`; return;
  }
  const tileAvail=(f)=>{
    const nm=f.name.replace(/\.(js|ya?ml)$/i,''); const enc=encodeURIComponent(f.name);
    const verLbl=_ghVerCache[f.sha]||g.fileVersions[f.name]||'';
    const icon=_ghIconCache[f.sha]||_ghcSmartIcon(nm)||'📦';
    const desc=_ghDescCache[f.sha]||_ghcSmartDesc(nm,'');
    const pkgBdg=_pkgBadgeHtml(_ghPkgCache[f.sha]||null);
    const prevBtn=`<button class="ghc-btn-del" style="color:rgba(139,92,246,.8);background:rgba(139,92,246,.08);border-color:rgba(139,92,246,.22)" data-action="_ghsPreviewCard" data-action-arg="${enc}" title="Anteprima"><i class="mdi mdi-eye-outline"></i></button>`;
    return `<div class="ghc-tile st-new"><div class="ghc-strip new"></div>
      <div class="ghc-prev"><div class="ghc-prev-inner" data-prev-sha="${eh(f.sha)}"></div><div class="ghc-prev-fade"></div><span class="ghc-bdg new">⬇ Disponibile</span>${pkgBdg}</div>
      <div class="ghc-body"><div class="ghc-head"><div class="ghc-ico">${_iconHtml(icon)}</div><div class="ghc-meta"><div class="ghc-name">${eh(nm)}</div>${verLbl?`<div class="ghc-ver">v${eh(verLbl)}</div>`:''}</div></div>
      ${desc?`<div class="ghc-desc">${eh(desc)}</div>`:''}
      <div class="ghc-acts"><button class="ghc-btn ghc-btn-inst" data-action="_ghsInstall" data-action-arg="${enc}"><i class="mdi mdi-download"></i> Installa</button>${prevBtn}</div></div></div>`;
  };
  list.innerHTML='<div class="ghc-grid">'+sorted.map(tileAvail).join('')+'</div>';
  requestAnimationFrame(()=>{
    list.querySelectorAll('[data-prev-sha]').forEach(el=>{ _ghcLivePrevBySha(el, el.dataset.prevSha); });
  });
}
/* ── Funzione generica: folder installate (distintivi, e in passato chips) senza raggruppamento ── */
function _ghStoreRenderFolderInstallate(q, cacheKey){
  const list=document.getElementById('ghs-list'), status=document.getElementById('ghs-status');
  const g=_ghCfg(); const idFile=g.idFile||{};
  const _cpCards=(curPage()||{cards:[]}).cards||[];
  const usedInPillRow=new Set();
  ((curPage()||{}).headerBadges||[]).forEach(b=>{ if(b.type==='jsd'&&b.jsCardId) usedInPillRow.add(b.jsCardId); });
  const usedInClockBar=new Set();
  const _hb=cfg.hdrBar||{};
  [...(_hb.left||[]),...(_hb.center||[]),...(_hb.right||[])].forEach(it=>{ if(it&&it.type==='jsd'&&it.jsCardId) usedInClockBar.add(it.jsCardId); });
  const usedInDash=new Set();
  _cpCards.forEach(c=>{ if(c.type==='js-custom'&&c.jsCardId==='sos-card') usedInDash.add(c.jsCardId); });
  let files=(_ghsCache[cacheKey]||[]).filter(f=>g.shas[f.name]&&g.shas[f.name]===f.sha);
  if(q) files=files.filter(f=>f.name.toLowerCase().includes(q));
  const sorted=files.slice().sort((a,b)=>a.name.localeCompare(b.name));

  // ── SOS: distintivo di sistema protetto da licenza, iniettato solo nella tab Distintivi ──
  let sosTileHtml='';
  if(cacheKey==='distintivi'){
    const sosReg=window.FratechCardRegistry?.['sos-card'];
    const sosMatches=!q||'sos'.includes(q)||(sosReg?.name||'').toLowerCase().includes(q);
    if(sosReg&&sosMatches){
      const inPillRowSos=usedInPillRow.has('sos-card');
      const inClockBarSos=usedInClockBar.has('sos-card');
      const inCurPageSos=inPillRowSos||inClockBarSos;
      const bdgLabelSos=inPillRowSos&&inClockBarSos?'In dashboard + header':inPillRowSos?'In dashboard':inClockBarSos?'In header':'';
      const bdgSos=inCurPageSos
        ?`<span class="ghc-bdg cur">✓ ${bdgLabelSos}</span>`
        :`<span class="ghc-bdg" style="background:rgba(139,92,246,.2);color:#c4b5fd;border-color:rgba(139,92,246,.4)">🔐 Sistema</span>`;
      const dashPartSos=inPillRowSos
        ?`<span class="ghc-indash" style="flex:1"><i class="mdi mdi-check-circle-outline"></i> Dashboard</span>`
        :`<button class="ghc-btn ghc-btn-add" style="flex:1" data-action="_jsStoreAddToHeaderAndRefresh" data-action-args='["sos-card"]'><i class="mdi mdi-view-dashboard-outline"></i> Dashboard</button>`;
      const headerPartSos=inClockBarSos
        ?`<span class="ghc-indash" style="flex:1"><i class="mdi mdi-check-circle-outline"></i> Header</span>`
        :`<button class="ghc-btn ghc-btn-add" style="flex:1" data-action="_jsStoreAddToClockBarAndRefresh" data-action-args='["sos-card"]'><i class="mdi mdi-flag-outline"></i> Header</button>`;
      const addBtnSos=`<div style="display:flex;gap:6px;flex:1">${dashPartSos}${headerPartSos}</div>`;
      const lockBtnSos=`<button class="ghc-btn-del" title="Protetta da licenza" style="opacity:.35;cursor:default"><i class="mdi mdi-lock-outline"></i></button>`;
      sosTileHtml=`<div class="ghc-tile st-ok"><div class="ghc-strip ok"></div>
        <div class="ghc-prev"><div class="ghc-prev-inner" data-prev-id="sos-card"></div><div class="ghc-prev-fade"></div>${bdgSos}</div>
        <div class="ghc-body"><div class="ghc-head"><div class="ghc-ico">${_iconHtml(sosReg.icon||'🆘')}</div><div class="ghc-meta"><div class="ghc-name">${eh(sosReg.name||'SOS Emergenza')}</div><div class="ghc-ver">v${eh(sosReg.version||'1.0')}</div></div></div>
        <div class="ghc-desc">${eh(sosReg.desc||'')}</div>
        <div class="ghc-acts">${addBtnSos}${lockBtnSos}</div></div></div>`;
    }
  }

  status.textContent=(sorted.length+(sosTileHtml?1:0))+' installate'+(q?' trovate':'');
  if(!sorted.length&&!sosTileHtml){
    list.innerHTML=`<div style="grid-column:1/-1"><div class="ghs-empty">${q?`Nessun risultato per "${eh(q)}"`: 'Nessuna card installata. Vai su "Non installate" per installarne.'}</div></div>`;
    return;
  }
  const tile=(f)=>{
    const nm=f.name.replace(/\.(js|ya?ml)$/i,''); const enc=encodeURIComponent(f.name);
    const cardId=Object.keys(idFile).find(k=>idFile[k]===f.name)||null;
    const verGH=_ghVerCache[f.sha]||g.fileVersions[f.name]||(cardId&&_curStoreVersion(cardId))||'';
    const reg=cardId?window.FratechCardRegistry?.[cardId]:null;
    const isDist=!!reg?.isDistintivo;
    const inPillRow=!!(cardId&&usedInPillRow.has(cardId));
    const inClockBar=!!(cardId&&usedInClockBar.has(cardId));
    const inDash=!!(cardId&&usedInDash.has(cardId));
    const inCurPage=isDist?(inPillRow||inClockBar):inDash;
    const icon=(reg?.icon)||(_jsStoreList().find(i=>(i.meta||{}).id===cardId)?.meta?.icon)||'📦';
    const desc=_ghcDesc(cardId,f.sha);
    const bdgLabel=isDist
      ?(inPillRow&&inClockBar?'In dashboard + header':inPillRow?'In dashboard':inClockBar?'In header':'')
      :(inDash?'In vista':'');
    const bdg=inCurPage?`<span class="ghc-bdg cur">✓ ${bdgLabel}</span>`:`<span class="ghc-bdg ok">● Installata</span>`;
    const prevHtml=cardId&&reg?`<div class="ghc-prev-inner" data-prev-id="${eh(cardId)}"></div>`:`<div class="ghc-prev-inner" data-prev-sha="${eh(f.sha)}"></div>`;
    const pkgBdgInst=_pkgBadgeHtml(cardId?_pkgInfoForInstalledCard(cardId):(_ghPkgCache[f.sha]||null));
    let addBtn='';
    if(cardId&&isDist){
      const dashPart=inPillRow
        ?`<span class="ghc-indash" style="flex:1"><i class="mdi mdi-check-circle-outline"></i> Dashboard</span>`
        :`<button class="ghc-btn ghc-btn-add" style="flex:1" data-action="_jsStoreAddToHeaderAndRefresh" data-action-args='["${cardId}"]'><i class="mdi mdi-view-dashboard-outline"></i> Dashboard</button>`;
      const headerPart=inClockBar
        ?`<span class="ghc-indash" style="flex:1"><i class="mdi mdi-check-circle-outline"></i> Header</span>`
        :`<button class="ghc-btn ghc-btn-add" style="flex:1" data-action="_jsStoreAddToClockBarAndRefresh" data-action-args='["${cardId}"]'><i class="mdi mdi-flag-outline"></i> Header</button>`;
      addBtn=`<div style="display:flex;gap:6px;flex:1">${dashPart}${headerPart}</div>`;
    } else if(cardId){
      addBtn=inDash?`<span class="ghc-indash"><i class="mdi mdi-check-circle-outline"></i> In vista</span>`:`<button class="ghc-btn ghc-btn-add" data-action="_jsStoreAddAndRefresh" data-action-args='["${cardId}"]'><i class="mdi mdi-plus"></i> Aggiungi</button>`;
    }
    const delBtn=cardId?`<button class="ghc-btn-del" data-action="_ghsDeleteInstalled" data-action-arg="${cardId}" title="Disinstalla"><i class="mdi mdi-delete-outline"></i></button>`:'';
    return `<div class="ghc-tile st-ok"><div class="ghc-strip ok"></div>
      <div class="ghc-prev">${prevHtml}<div class="ghc-prev-fade"></div>${bdg}${pkgBdgInst}</div>
      <div class="ghc-body"><div class="ghc-head"><div class="ghc-ico">${_iconHtml(icon)}</div><div class="ghc-meta"><div class="ghc-name">${eh(nm)}</div>${verGH?`<div class="ghc-ver">v${eh(verGH)}</div>`:''}</div></div>
      ${desc?`<div class="ghc-desc">${eh(desc)}</div>`:''}
      <div class="ghc-acts">${addBtn}${delBtn}</div></div></div>`;
  };
  list.innerHTML='<div class="ghc-grid">'+sosTileHtml+sorted.map(tile).join('')+'</div>';
  requestAnimationFrame(()=>{
    list.querySelectorAll('[data-prev-id]').forEach(el=>{ _ghcLivePrev(el, el.dataset.prevId); });
    list.querySelectorAll('[data-prev-sha]').forEach(el=>{ _ghcLivePrevBySha(el, el.dataset.prevSha); });
  });
}
/* ── NON INSTALLATE cards JS ── */
function _ghStoreRenderCardsNonInstallate(q){
  _ghStoreRenderFolderNonInstallate(q,'js','Tutte le card JS sono installate — vai su "Installate"');
}
/* ── INSTALLATE: card JS installate e aggiornate, raggruppate per categoria ── */
function _ghStoreRenderCardsInstallate(q){
  const list=document.getElementById('ghs-list'), status=document.getElementById('ghs-status');
  const g=_ghCfg(); const idFile=g.idFile||{};
  const _cpCards=(curPage()||{cards:[]}).cards||[];
  const usedInCurPage=new Set();
  _cpCards.forEach(c=>{ if(c.type==='js-custom'&&c.jsCardId==='sos-card'&&!(window.FratechCardRegistry?.[c.jsCardId]?.isDistintivo)) usedInCurPage.add(c.jsCardId); });
  ((curPage()||{}).headerBadges||[]).forEach(b=>{ if(b.type==='jsd'&&b.jsCardId) usedInCurPage.add(b.jsCardId); });
  let files=(_ghsCache['js']||[]).filter(f=>g.shas[f.name]&&g.shas[f.name]===f.sha);
  if(q) files=files.filter(f=>f.name.toLowerCase().includes(q));
  const sorted=files.slice().sort((a,b)=>a.name.localeCompare(b.name));
  status.textContent=sorted.length+' card installate'+(q?' trovate':'');
  const tile=(f)=>{
    const nm=f.name.replace(/\.(js|ya?ml)$/i,''); const enc=encodeURIComponent(f.name);
    let cardId=Object.keys(idFile).find(k=>idFile[k]===f.name)||null;
    if(!cardId){
      const _fnId=f.name.replace(/\.js$/i,'');
      let _regE=window.FratechCardRegistry?.[_fnId];
      // fallback 2: eval dal code cache GitHub (card installata prima che idFile venisse settato)
      if(!_regE && _ghCodeCache[f.sha]){
        try{
          const _bef=Object.assign({},window.FratechCardRegistry||{});
          (0,eval)(_ghCodeCache[f.sha]);
          const _td=Object.keys(window.FratechCardRegistry||{}).filter(_k=>_bef[_k]!==window.FratechCardRegistry[_k]);
          if(_td.length) _regE=window.FratechCardRegistry[_td[0]];
        }catch(e){}
      }
      if(_regE&&!_regE._lovelace&&_regE.id===_fnId){
        cardId=_fnId;
        const _g2=_ghCfg(); _g2.idFile=_g2.idFile||{}; _g2.idFile[_fnId]=f.name;
        const _cc=_ghCodeCache[f.sha]||'';
        try{ _jsStoreSave(_fnId,{id:_fnId,name:_regE.name||_fnId,icon:_regE.icon||'📦',version:_parseCardVersion(_cc)||'1.0',desc:_regE.desc||''},_cc,'github'); }catch(e){}
        try{saveCfg();_haSaveCfg();}catch(e){}
      }
    }
    const verGH=_ghVerCache[f.sha]||g.fileVersions[f.name]||(cardId&&_curStoreVersion(cardId))||'';
    const inCurPage=!!(cardId&&usedInCurPage.has(cardId));
    const reg=cardId?window.FratechCardRegistry?.[cardId]:null;
    const icon=(reg?.icon)||(_jsStoreList().find(i=>(i.meta||{}).id===cardId)?.meta?.icon)||'📦';
    const desc=_ghcDesc(cardId,f.sha);
    const _inLabel=reg?.isDistintivo?'In intestazione':'In vista';
    const bdg=inCurPage?`<span class="ghc-bdg cur">✓ ${_inLabel}</span>`:`<span class="ghc-bdg ok">● Installata</span>`;
    const prevHtml=cardId&&reg?`<div class="ghc-prev-inner" data-prev-id="${eh(cardId)}"></div>`:`<div class="ghc-prev-inner" data-prev-sha="${eh(f.sha)}"></div>`;
    const pkgInfoInst=cardId?_pkgInfoForInstalledCard(cardId):(_ghPkgCache[f.sha]||null);
    const pkgBdgInst=_pkgBadgeHtml(pkgInfoInst);
    const addBtn=cardId?(inCurPage?`<span class="ghc-indash"><i class="mdi mdi-check-circle-outline"></i> ${_inLabel}</span>`:`<button class="ghc-btn ghc-btn-add" data-action="_jsStoreAddAndRefresh" data-action-args='["${cardId}"]'><i class="mdi mdi-plus"></i> Aggiungi</button>`):'';
    const delBtn=cardId?`<button class="ghc-btn-del" data-action="_ghsDeleteInstalled" data-action-arg="${cardId}" title="Disinstalla"><i class="mdi mdi-delete-outline"></i></button>`:'';
    return `<div class="ghc-tile st-ok"><div class="ghc-strip ok"></div>
      <div class="ghc-prev">${prevHtml}<div class="ghc-prev-fade"></div>${bdg}${pkgBdgInst}</div>
      <div class="ghc-body"><div class="ghc-head"><div class="ghc-ico">${_iconHtml(icon)}</div><div class="ghc-meta"><div class="ghc-name">${eh(nm)}</div>${verGH?`<div class="ghc-ver">v${eh(verGH)}</div>`:''}</div></div>
      ${desc?`<div class="ghc-desc">${eh(desc)}</div>`:''}
      <div class="ghc-acts">${addBtn}${delBtn}</div></div></div>`;
  };
  const elettr=sorted.filter(f=>_isElettrCard(f,idFile));
  const altre=sorted.filter(f=>!_isElettrCard(f,idFile));
  let html='';
  if(elettr.length){
    html+=`<div class="ghc-sec"><span class="ghc-sec-dot ok"></span>🔌 Elettrodomestici<span class="ghc-sec-cnt">${elettr.length}</span></div>`;
    html+=elettr.map(tile).join('');
  }
  if(altre.length){
    html+=`<div class="ghc-sec" style="margin-top:${elettr.length?'16':'0'}px"><span class="ghc-sec-dot ok"></span>⚡ Altre card<span class="ghc-sec-cnt">${altre.length}</span></div>`;
    html+=altre.map(tile).join('');
  }
  if(!sorted.length){
    html=`<div style="grid-column:1/-1"><div class="ghs-empty">${q?`Nessun risultato per "${eh(q)}"`: 'Nessuna card installata. Vai su "Non installate" per installarne.'}</div></div>`;
  }
  list.innerHTML='<div class="ghc-grid">'+html+'</div>';
  requestAnimationFrame(()=>{
    list.querySelectorAll('[data-prev-id]').forEach(el=>{ _ghcLivePrev(el, el.dataset.prevId); });
    list.querySelectorAll('[data-prev-sha]').forEach(el=>{ _ghcLivePrevBySha(el, el.dataset.prevSha); });
  });
}
/* ── PKG NON INSTALLATI: pkg su GitHub non ancora su HA ── */
function _ghStoreRenderPkgNonInstallati(q){
  const list=document.getElementById('ghs-list'), status=document.getElementById('ghs-status');
  const ghFiles=(_ghsCache.pkg||[]).slice();
  let ghNotHA=ghFiles.filter(f=>!_pkgIsOnHA('frarik/'+f.name)&&!_pkgIsOnHA(f.name));
  if(q) ghNotHA=ghNotHA.filter(f=>f.name.toLowerCase().includes(q.toLowerCase()));
  status.textContent=ghNotHA.length+' PKG da installare';
  const pkgRow=(f)=>{
    const nm=f.name.replace(/\.ya?ml$/i,''); const enc=encodeURIComponent(f.name);
    return `<div class="ghs-row" style="align-items:flex-start">
      <div class="ghs-ico" style="font-size:22px;padding-top:2px">📦</div>
      <div class="ghs-info" style="flex:1;min-width:0"><div class="ghs-name">${eh(nm)}</div><div class="ghs-sub" style="color:rgba(255,255,255,.4);font-size:10px">${eh(f.name)}</div></div>
      <div class="ghs-acts" style="flex-shrink:0">
        <button class="ghs-btn ghs-btn-inst" data-action="_ghsPkgInstallFromGH" data-action-arg="${enc}"><i class="mdi mdi-package-down"></i> Installa su HA</button>
        <button class="ghs-btn ghs-btn-cp" data-action="_ghsPkgDownloadGh" data-action-arg="${enc}"><i class="mdi mdi-download"></i></button>
      </div>
    </div>`;
  };
  if(!ghNotHA.length){
    const msg=!_ghsCache.pkg?'⏳ Caricamento da GitHub…':q?`Nessun risultato per "${eh(q)}"`:ghFiles.length?'Tutti i PKG GitHub sono già installati su HA.':'Nessun PKG disponibile su GitHub.';
    list.innerHTML=`<div class="ghs-empty">${msg}</div>`; return;
  }
  list.innerHTML=ghNotHA.map(pkgRow).join('');
}
/* ── PKG INSTALLATI: pkg su HA senza aggiornamenti pendenti ── */
async function _ghStoreRenderPkgInstallati(q){
  const list=document.getElementById('ghs-list'), status=document.getElementById('ghs-status');
  /* Ricarica sempre la lista da HA per evitare dati stale */
  await _loadHaInstalledPkgs();
  let haList=Array.from(_haInstalledPkgs).filter(f=>{ const bn=f.split('/').pop().toLowerCase(); return !_pkgPending[bn]; }).sort();
  if(q) haList=haList.filter(f=>f.toLowerCase().includes(q.toLowerCase()));
  status.textContent=haList.length+' PKG installati su HA';
  const pkgRow=(f)=>{
    const base=f.split('/').pop();
    /* nome visibile: se il file non ha nome (es. .yaml), mostra il path completo */
    const nm=base.replace(/\.ya?ml$/i,'')||f;
    const enc=encodeURIComponent(f);
    const isCorrupt=!base.replace(/\.ya?ml$/i,'');
    const corruptBadge=isCorrupt?`<span style="background:rgba(239,68,68,.15);border:1px solid rgba(239,68,68,.3);color:#f87171;font-size:9px;font-weight:700;padding:1px 6px;border-radius:10px;margin-left:4px">⚠️ File corrotto</span>`:'';
    return `<div class="ghs-row" style="align-items:flex-start">
      <div class="ghs-ico" style="font-size:22px;padding-top:2px">📦</div>
      <div class="ghs-info" style="flex:1;min-width:0"><div class="ghs-name">${eh(nm)}${corruptBadge}</div><div class="ghs-sub" style="color:#4ade80;font-size:10px;font-weight:700">✅ Su HA</div></div>
      <div class="ghs-acts" style="flex-shrink:0">
        <button class="ghs-btn" data-action="_pkgViewOnHA" data-action-arg="${enc}" title="Visualizza YAML"><i class="mdi mdi-eye-outline"></i></button>
        <button class="ghs-btn ghs-ibtn-del" data-action="_pkgUninstallFromHA" data-action-arg="${enc}" title="Rimuovi da HA" style="color:#f87171;border-color:rgba(248,113,113,.3)"><i class="mdi mdi-delete-outline"></i> Rimuovi</button>
      </div>
    </div>`;
  };
  if(!haList.length){
    list.innerHTML=`<div class="ghs-empty">${q?`Nessun risultato per "${eh(q)}"`:_haInstalledPkgs.size?'I PKG con aggiornamenti disponibili sono nel tab "Da aggiornare".':'Nessun PKG installato su Home Assistant.'}</div>`;
    return;
  }
  list.innerHTML=haList.map(pkgRow).join('');
}
/* ── Marca un PKG come già aggiornato senza scaricarlo ── */
async function _ghsPkgMarkUpdated(encodedName){
  const fileName=decodeURIComponent(encodedName);
  const f=(_ghsCache.pkg||[]).find(x=>x.name===fileName);
  const sha=f?.sha||_pkgPending[fileName];
  if(!sha){ showToast('⚠️ SHA non trovato per '+fileName); return; }
  const g=_ghCfg(); g.pkgShas=g.pkgShas||{}; g.pkgShas[fileName]=sha; saveCfg();
  delete _pkgPending[fileName];
  try{ _ntfClearPkg(fileName); }catch(e){}
  try{ _ghsUpdBadge(); }catch(e){}
  showToast('✅ PKG marcato come aggiornato');
  try{ _ghStoreRender(); }catch(e){}
}
/* ── TAB ELETTRODOMESTICI: filtro automatico su card-js ── */
function _isElettrCard(f, idFile){
  const cardId=Object.keys(idFile||{}).find(k=>(idFile||{})[k]===f.name)||null;
  // 1. Registry: CARD.category impostato dalla card
  if(cardId){ const reg=window.FratechCardRegistry?.[cardId]; if(reg&&reg.category) return reg.category==='elettrodomestici'; }
  // 2. Codice sorgente: /* frarik-category: elettrodomestici */
  const code=_ghCodeCache[f.sha]||'';
  if(code){ const m=code.match(/frarik-category:\s*(\S+)/i); if(m) return m[1].toLowerCase()==='elettrodomestici'; }
  // 3. Smart-match sul nome file (fallback per card esistenti)
  const n=(f.name||'').toLowerCase().replace(/\.js$/i,'');
  return /asciugat|lavatr|lavastov|forno|friggit|microond|scaldab|frigorif|induzion|montalatte|tostapane|elettrodomest|clima|condiz|split|hvac/.test(n);
}
function _ghStoreRenderElettr(q){
  const list=document.getElementById('ghs-list'), status=document.getElementById('ghs-status');
  const g=_ghCfg(); const idFile=g.idFile||{};
  const _cpCards=(curPage()||{cards:[]}).cards||[];
  const usedInCurPage=new Set();
  _cpCards.forEach(c=>{ if(c.type==='js-custom'&&c.jsCardId==='sos-card'&&!(window.FratechCardRegistry?.[c.jsCardId]?.isDistintivo)) usedInCurPage.add(c.jsCardId); });
  ((curPage()||{}).headerBadges||[]).forEach(b=>{ if(b.type==='jsd'&&b.jsCardId) usedInCurPage.add(b.jsCardId); });
  // Solo card non-installate (quelle installate vanno nel tab Installate)
  let files=(_ghsCache['js']||[]).filter(f=>_cardEffectiveTab(f,idFile)==='elettrodomestici'&&!g.shas[f.name]);
  if(q) files=files.filter(f=>f.name.toLowerCase().includes(q));
  const hdr=`<div style="margin-bottom:14px;padding:12px 14px;border-radius:12px;background:rgba(56,189,248,.07);border:1px solid rgba(56,189,248,.2);font-size:11px;color:rgba(255,255,255,.7);line-height:1.6"><b style="color:#7dd3fc">🔌 Elettrodomestici</b> — card da installare per monitoraggio consumi ed elettrodomestici.<br><span style="opacity:.7">Le card installate appaiono in <b>🗂 Installate</b>. Usa ⤷ per spostare una card in un altro tab.</span></div>`;
  status.textContent=files.length+' card da installare'+(q?' trovate':'');
  if(!files.length){ list.innerHTML=hdr+`<div class="ghs-empty">${q?`Nessun risultato per "${eh(q)}"`: 'Tutte le card elettrodomestici sono installate — vai su <b style="color:#7dd3fc">🗂 Installate</b>.'}</div>`; return; }
  const tileToInstall=(f)=>{
    const nm=f.name.replace(/\.(js|ya?ml)$/i,''); const enc=encodeURIComponent(f.name);
    const verLbl=_ghVerCache[f.sha]||g.fileVersions[f.name]||'';
    const rawDesc=_ghDescCache[f.sha]||'';
    const desc=rawDesc||_ghcSmartDesc(nm,'');
    const icon=_ghIconCache[f.sha]||_ghcSmartIcon(nm)||'🔌';
    const mvBtn=`<button class="ghc-btn-del" data-action="_ghsMoveCard" data-action-arg="${enc}" title="Sposta in altro tab" style="color:rgba(255,255,255,.5)"><i class="mdi mdi-swap-horizontal"></i></button>`;
    const prevBtn=`<button class="ghc-btn-del" style="color:rgba(139,92,246,.8);background:rgba(139,92,246,.08);border-color:rgba(139,92,246,.22)" data-action="_ghsPreviewCard" data-action-arg="${enc}" title="Anteprima"><i class="mdi mdi-eye-outline"></i></button>`;
    return `<div class="ghc-tile st-new"><div class="ghc-strip new"></div><div class="ghc-prev"><div class="ghc-prev-inner" data-prev-sha="${eh(f.sha)}"></div><div class="ghc-prev-fade"></div><span class="ghc-bdg new">⬇ Disponibile</span></div><div class="ghc-body"><div class="ghc-head"><div class="ghc-ico">${_iconHtml(icon)}</div><div class="ghc-meta"><div class="ghc-name">${eh(nm)}</div>${verLbl?`<div class="ghc-ver">v${eh(verLbl)}</div>`:''}</div></div>${desc?`<div class="ghc-desc">${eh(desc)}</div>`:''}<div class="ghc-acts"><button class="ghc-btn ghc-btn-inst" data-action="_ghsInstall" data-action-arg="${enc}"><i class="mdi mdi-download"></i> Installa</button>${prevBtn}${mvBtn}</div></div></div>`;
  };
  list.innerHTML=hdr+'<div class="ghc-grid">'+files.map(tileToInstall).join('')+'</div>';
  requestAnimationFrame(()=>{
    list.querySelectorAll('[data-prev-id]').forEach(el=>{ _ghcLivePrev(el, el.dataset.prevId); });
    list.querySelectorAll('[data-prev-sha]').forEach(el=>{ _ghcLivePrevBySha(el, el.dataset.prevSha); });
  });
}
function _isAdmin(){
  const note=(localStorage.getItem('frarik_lic_note')||'').toLowerCase();
  return note.includes('admin')||note.includes('amministratore');
}
function _isPremiumLic(){
  const note=(localStorage.getItem('frarik_lic_note')||'').toLowerCase();
  return note.includes('premium')||note.includes('admin')||note.includes('amministratore');
}
function openPremiumPage(){ document.getElementById('prem-page-modal')?.classList.remove('off'); }
function closePremiumPage(){ document.getElementById('prem-page-modal')?.classList.add('off'); }
function _ghStoreRenderPremium(q){
  const list=document.getElementById('ghs-list'), status=document.getElementById('ghs-status');
  const g=_ghCfg(); const idFile=g.idFile||{};
  const isPrem=_isPremiumLic();
  const allFiles=(_ghsCache['premium']||[]);
  status.textContent='💎 Premium';

  // ── Utente non premium → schermata bloccata ──
  if(!isPrem){
    list.innerHTML=`<div class="ghc-prem-hero">
      <div class="ghc-prem-hero-ico">💎</div>
      <div class="ghc-prem-hero-title">Frarik Premium</div>
      <div class="ghc-prem-hero-sub">Card esclusive con funzionalità avanzate, aggiornamenti prioritari e supporto dedicato.</div>
      <button class="ghc-prem-cta" data-action="openPremiumPage">💎 Vuoi Diventare Premium?</button>
      <button style="display:block;margin:10px auto 0;padding:9px 22px;border-radius:12px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.15);color:#fff;font-size:11px;font-weight:700;cursor:pointer" data-action="_ghsPremActivate">🔑 Ho già una licenza Premium</button>
    </div>
    <div class="ghc-grid" style="pointer-events:none;user-select:none">
      ${['Analytics Pro','Energy Dashboard','Ultra Widgets','Smart Automations'].map(nm=>`<div class="ghc-tile ghc-prem-locked" style="border-color:rgba(251,191,36,.18)">
        <div class="ghc-strip" style="background:linear-gradient(90deg,#fbbf24,rgba(251,191,36,0))"></div>
        <div class="ghc-prev"><div class="ghc-prev-inner" style="background:linear-gradient(135deg,#2a1a00,#78350f);display:flex;align-items:center;justify-content:center"><span style="font-size:28px;opacity:.25">💎</span></div><div class="ghc-prev-fade"></div><span class="ghc-bdg" style="background:rgba(251,191,36,.22);border-color:rgba(251,191,36,.5);color:#fbbf24">💎 PREMIUM</span></div>
        <div class="ghc-body"><div class="ghc-head"><div class="ghc-ico" style="background:rgba(251,191,36,.12);border-color:rgba(251,191,36,.22)">💎</div><div class="ghc-meta"><div class="ghc-name">${eh(nm)}</div><div class="ghc-ver" style="color:rgba(251,191,36,.6)">Prossimamente</div></div></div>
        <div class="ghc-desc">Funzionalità avanzate disponibili con licenza Premium.</div>
        <div class="ghc-acts"><button class="ghc-btn" style="background:rgba(251,191,36,.08);border-color:rgba(251,191,36,.25);color:rgba(251,191,36,.5)">🔒 Riservato</button></div></div></div>`).join('')}
    </div>`;
    return;
  }

  // ── Utente premium: mostra card ──
  if(!allFiles.length){
    list.innerHTML=`<div class="ghc-prem-hero">
      <div class="ghc-prem-hero-ico">✅</div>
      <div class="ghc-prem-hero-title" style="font-size:15px">Accesso Premium attivo</div>
      <div class="ghc-prem-hero-sub">Nessuna card premium disponibile al momento. Prossimamente saranno pubblicate qui le card esclusive.</div>
    </div>`;
    if(_isAdmin()) _ghsAdminPanel(list);
    return;
  }
  let files=allFiles.slice();
  if(q) files=files.filter(f=>f.name.toLowerCase().includes(q));
  const _cpCards=(curPage()||{cards:[]}).cards||[];
  const usedInCurPage=new Set();
  _cpCards.forEach(c=>{ if(c.type==='js-custom'&&c.jsCardId==='sos-card'&&!(window.FratechCardRegistry?.[c.jsCardId]?.isDistintivo)) usedInCurPage.add(c.jsCardId); });
  ((curPage()||{}).headerBadges||[]).forEach(b=>{ if(b.type==='jsd'&&b.jsCardId) usedInCurPage.add(b.jsCardId); });
  const sorted=files.filter(f=>f&&f.name).sort((a,b)=>a.name.localeCompare(b.name));
  const installed=[], toInstall=[]; sorted.forEach(f=>{ (g.shas[f.name]?installed:toInstall).push(f); });
  const tilePrem=(f,isInstalled)=>{
    const nm=f.name.replace(/\.(js|ya?ml)$/i,''); const enc=encodeURIComponent(f.name);
    const cardId=isInstalled?(Object.keys(idFile).find(k=>idFile[k]===f.name)||null):null;
    const verLbl=_ghVerCache[f.sha]||g.fileVersions[f.name]||(cardId&&_curStoreVersion(cardId))||'';
    const desc=_ghcDesc(cardId,f.sha)||_ghDescCache[f.sha]||_ghcSmartDesc(nm,'')||'Card Premium con funzionalità esclusive.';
    const hasUpdate=isInstalled&&!!(g.shas[f.name]&&g.shas[f.name]!==f.sha);
    const inCurPage=!!(cardId&&usedInCurPage.has(cardId));
    const reg=cardId?window.FratechCardRegistry?.[cardId]:null;
    const icon=_ghIconCache[f.sha]||(reg?.icon)||_ghcSmartIcon(nm)||'💎';
    const prevHtml=cardId&&reg
      ?`<div class="ghc-prev-inner" data-prev-id="${eh(cardId)}"></div>`
      :`<div class="ghc-prev-inner" data-prev-sha="${eh(f.sha)}"></div>`;
    const updBtn=hasUpdate?`<button class="ghc-btn" style="background:rgba(251,191,36,.2);border-color:rgba(251,191,36,.5);color:#fbbf24" data-action="_ghsInstall" data-action-arg="${enc}"><i class="mdi mdi-update"></i> Aggiorna</button>`:'';
    const addBtn=isInstalled?(inCurPage?`<span class="ghc-indash"><i class="mdi mdi-check-circle-outline"></i> In vista</span>`:`<button class="ghc-btn" style="background:rgba(251,191,36,.14);border-color:rgba(251,191,36,.35);color:#fbbf24" data-action="_jsStoreAddAndRefresh" data-action-args='["${cardId}"]'><i class="mdi mdi-plus"></i> Aggiungi</button>`)
      :`<button class="ghc-btn" style="background:rgba(251,191,36,.18);border-color:rgba(251,191,36,.4);color:#fbbf24" data-action="_ghsInstall" data-action-arg="${enc}"><i class="mdi mdi-download"></i> Installa</button>`;
    const delBtn=cardId?`<button class="ghc-btn-del" data-action="_ghsDeleteInstalled" data-action-arg="${cardId}"><i class="mdi mdi-delete-outline"></i></button>`:'';
    return `<div class="ghc-tile" style="border-color:rgba(251,191,36,.28)">
      <div class="ghc-strip" style="background:linear-gradient(90deg,#fbbf24,rgba(251,191,36,0))"></div>
      <div class="ghc-prev">${prevHtml}<div class="ghc-prev-fade"></div><span class="ghc-bdg" style="background:rgba(251,191,36,.22);border-color:rgba(251,191,36,.5);color:#fbbf24">💎 ${isInstalled?'Installata':'Premium'}</span></div>
      <div class="ghc-body"><div class="ghc-head"><div class="ghc-ico" style="background:rgba(251,191,36,.15);border-color:rgba(251,191,36,.28)">${icon}</div><div class="ghc-meta"><div class="ghc-name">${eh(nm)}</div>${verLbl?`<div class="ghc-ver" style="color:rgba(251,191,36,.8)">v${eh(verLbl)}</div>`:''}</div></div>
      <div class="ghc-desc">${eh(desc)}</div>
      <div class="ghc-acts">${updBtn}${addBtn}${delBtn}</div></div></div>`;
  };
  list.innerHTML='<div class="ghc-grid">'
    +`<div class="ghc-sec"><span class="ghc-sec-dot" style="background:#fbbf24"></span>Installate<span class="ghc-sec-cnt">${installed.length}</span></div>`
    +(installed.length?installed.map(f=>tilePrem(f,true)).join(''):`<div style="grid-column:1/-1"><div class="ghs-empty">Nessuna card premium installata</div></div>`)
    +`<div class="ghc-sec"><span class="ghc-sec-dot" style="background:#fbbf24"></span>Disponibili<span class="ghc-sec-cnt">${toInstall.length}</span></div>`
    +(toInstall.length?toInstall.map(f=>tilePrem(f,false)).join(''):`<div style="grid-column:1/-1"><div class="ghs-empty">Tutte le card premium sono già installate</div></div>`)
    +'</div>';
  if(_isAdmin()) _ghsAdminPanel(list);
  requestAnimationFrame(()=>{
    list.querySelectorAll('[data-prev-id]').forEach(el=>{ _ghcLivePrev(el,el.dataset.prevId); });
    list.querySelectorAll('[data-prev-sha]').forEach(el=>{ _ghcLivePrevBySha(el,el.dataset.prevSha); });
  });
}
