function _ghsPremActivate(){
  closePremiumPage();
  try{ _switchEpTab('sistema'); setTimeout(()=>{ const el=document.getElementById('lic-section'); if(el){ el.scrollIntoView({behavior:'smooth'}); el.classList.add('lic-highlight'); setTimeout(()=>el.classList.remove('lic-highlight'),2000); } },200); }catch(e){}
  showToast('💎 Inserisci la tua chiave Premium nelle impostazioni licenza');
}
function _premSendInterest(){
  const inp=document.getElementById('prem-interest-email');
  const msg=document.getElementById('prem-interest-msg');
  const email=(inp?.value||'').trim();
  if(!email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){
    if(msg){ msg.style.color='rgba(251,100,100,.8)'; msg.textContent='⚠️ Inserisci un indirizzo email valido'; }
    return;
  }
  const btn=document.getElementById('prem-interest-btn');
  if(btn){ btn.disabled=true; btn.textContent='Invio…'; }
  // salva localmente l'interesse (server-side non ancora configurato)
  const stored=JSON.parse(localStorage.getItem('frarik_prem_interest')||'[]');
  if(!stored.includes(email)){ stored.push(email); localStorage.setItem('frarik_prem_interest',JSON.stringify(stored)); }
  setTimeout(()=>{
    if(msg){ msg.style.color='rgba(100,220,130,.9)'; msg.textContent='✅ Registrato! Ti contatteremo presto.'; }
    if(btn){ btn.disabled=false; btn.textContent='Invia ✉️'; }
    if(inp) inp.value='';
  },800);
}
function _ghsDeleteInstalled(id){
  if(!id) return;
  const it=_jsStoreList().find(i=>(i.meta||{}).id===id);
  if(it&&it._builtin){ _sosRequireLicense(()=>{ showToast('🔐 Card di sistema — non disinstallabile'); }); return; }
  const nm=(it&&it.meta&&it.meta.name)||id;
  showConfirm(`Eliminare la card <b>${eh(nm)}</b> dalle installate?<br><span style="font-size:11px;opacity:.7">Le card di questo tipo già messe in dashboard mostreranno un errore.</span>`, ()=>{
    _jsStoreDelete(id);
    try{ delete window.FratechCardRegistry[id]; }catch(e){}
    // libera lo sha del file corrispondente, così ricompare come "Installa" nello store
    try{ const g=_ghCfg(); if(g.idFile&&g.idFile[id]){ delete g.shas[g.idFile[id]]; delete g.idFile[id]; } saveCfg(); _haSaveCfg(); }catch(e){}
    if(typeof _epRenderJsStore==='function') _epRenderJsStore();
    // NON svuotiamo _ghsCache: la lista GitHub è già in cache, la card riappare con "Installa"
    renderDash(); _ghStoreRender(); showToast('🗑 Card disinstallata');
  }, 'Elimina');
}
/* ════════ RINOMINA una card (nome visualizzato) ════════
   Aggiorna il nome in locale e nel codice (campo name:), e se la card è su GitHub
   (e c'è il token) aggiorna anche il file remoto, senza cambiare la versione. */
function _stampName(code, name){
  const safe=String(name||'').replace(/\\/g,'\\\\').replace(/'/g,"\\'").replace(/"/g,'\\"');
  if(/name\s*:\s*['"][^'"]*['"]/.test(code)){
    return code.replace(/name(\s*:\s*)(['"])[^'"]*['"]/, (m,sep,q)=>`name${sep}${q}${safe}${q}`);
  }
  return code;   // se non c'è un campo name nel codice, il display usa comunque la meta
}
function _jsRename(id){
  const it=_jsStoreList().find(i=>(i.meta||{}).id===id);
  if(!it){ showToast('⚠️ Card non trovata'); return; }
  const cur=(it.meta&&it.meta.name)||id;
  showConfirm(
    'Nuovo nome per la card:<br><input id="jsrename-inp" type="text" value="'+eh(cur)+'" '+
    'style="width:100%;margin-top:10px;padding:9px 11px;border-radius:9px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.18);color:#fff;font-size:13px;outline:none">',
    ()=>{ const v=(document.getElementById('jsrename-inp')||{}).value||''; _jsRenameDo(id, v); },
    'Rinomina', 'Annulla'
  );
  setTimeout(()=>{ const i=document.getElementById('jsrename-inp'); if(i){ i.focus(); i.select(); i.addEventListener('keydown',e=>{ if(e.key==='Enter') document.getElementById('confirm-ok')?.click(); }); } }, 60);
}
async function _jsRenameDo(id, newName){
  newName=(newName||'').trim();
  if(!id||!newName) return;
  const it=_jsStoreList().find(i=>(i.meta||{}).id===id); if(!it){ showToast('⚠️ Card non trovata'); return; }
  const origin=it.origin||'github';
  const code=_stampName(it.code, newName);
  _jsStoreSave(id, Object.assign({}, it.meta, {name:newName}), code, origin);
  // refresh immediato di tutte le viste + dashboard
  try{ if(typeof _epRenderJsStore==='function') _epRenderJsStore(); }catch(e){}
  try{ if(typeof _jsStoreRenderList==='function') _jsStoreRenderList(); }catch(e){}
  try{ _renderRenameStore(); }catch(e){}
  try{ _ghStoreRender(); }catch(e){}
  try{ renderDash(); }catch(e){}
  // propaga il nuovo nome su GitHub (stesso file, versione invariata)
  const g=_ghCfg(); const file=g.idFile&&g.idFile[id];
  if(file && g.token){
    showToast('☁️ Aggiorno il nome su GitHub…');
    try{
      let path=null;
      try{ const all=await _ghApiListAll(); const f=all.find(x=>x.name===file); if(f) path=f.path; }catch(e){}
      if(!path) path='card-js/'+file;   // fallback (la maggior parte sta in card-js)
      const res=await _ghPut(path, code, 'Rinomina card → '+newName);
      const newSha=res&&res.content&&res.content.sha;
      if(newSha){ g.shas[file]=newSha; g.notifiedShas[file]=newSha; _ghVerCache[newSha]=g.fileVersions[file]||_parseCardVersion(code)||'1.0'; saveCfg(); }
      _ghsCache={};
      showToast('✅ Rinominata in «'+newName+'» (anche su GitHub)');
    }catch(e){ showToast('⚠️ Rinominata in locale · GitHub: '+(e.message||e)); }
  } else {
    showToast('✅ Card rinominata in «'+newName+'»'+(file?' — pubblica per aggiornarla su GitHub':''));
  }
}
/* ════════ Pannello "Impostazioni Nomi Store" — rinomina rapida di tutte le card ════════ */
function openRenameStore(){
  const m=document.getElementById('rename-store-modal'); if(!m) return;
  m.classList.remove('off');
  _renderRenameStore();
}
function closeRenameStore(){ document.getElementById('rename-store-modal')?.classList.add('off'); }
function _renderRenameStore(){
  const el=document.getElementById('rename-store-list'); if(!el) return;
  const items=_jsStoreList();
  if(!items.length){ el.innerHTML='<div style="padding:26px;text-align:center;color:var(--muted);font-size:12px">Nessuna card installata.</div>'; return; }
  const g=_ghCfg();
  el.innerHTML=items.slice().sort((a,b)=>((a.meta||{}).name||'').localeCompare((b.meta||{}).name||'')).map(it=>{
    const mm=it.meta||{}; const id=mm.id||'';
    const onGh=!!((g.idFile||{})[id]) || (it.origin==='github');
    return `<div style="display:flex;align-items:center;gap:10px;padding:9px 4px;border-bottom:1px solid rgba(255,255,255,.05)">
      <span style="font-size:20px;flex-shrink:0">${mm.icon||'📦'}</span>
      <div style="flex:1;min-width:0">
        <input id="rns-inp-${id}" type="text" value="${eh(mm.name||id)}" placeholder="Nome card" data-rns="${id}"
          style="width:100%;padding:7px 10px;border-radius:8px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.14);color:#fff;font-size:13px;font-weight:600;outline:none">
        <div style="font-size:9px;color:var(--muted);margin-top:3px">${eh(id)} · v${eh(mm.version||'1.0')} · ${onGh?'☁️ GitHub':'📁 locale'}</div>
      </div>
      <button data-action="_jsRenameInline" data-action-arg="${id}" title="Salva nome"
        style="flex-shrink:0;width:34px;height:34px;border-radius:9px;background:rgba(74,222,128,.16);border:1px solid rgba(74,222,128,.35);color:#4ade80;font-size:15px;cursor:pointer">✓</button>
    </div>`;
  }).join('');
  // Invio nel campo = salva
  el.querySelectorAll('input[data-rns]').forEach(inp=>{
    inp.addEventListener('keydown',e=>{ if(e.key==='Enter'){ e.preventDefault(); _jsRenameInline(inp.dataset.rns); } });
  });
}
function _jsRenameInline(id){
  const inp=document.getElementById('rns-inp-'+id);
  const v=((inp&&inp.value)||'').trim();
  if(!v){ showToast('Inserisci un nome'); return; }
  const it=_jsStoreList().find(i=>(i.meta||{}).id===id);
  if(it && ((it.meta||{}).name||'')===v){ showToast('Nome invariato'); return; }
  _jsRenameDo(id, v);
}
function _ghStoreInitDropzone(){
  const dz=document.getElementById('ghs-dropzone'); if(!dz||dz._init) return; dz._init=true;
  dz.ondragover=e=>{ e.preventDefault(); dz.classList.add('drag-over'); };
  dz.ondragleave=()=>dz.classList.remove('drag-over');
  dz.ondrop=e=>{ e.preventDefault(); dz.classList.remove('drag-over'); if(e.dataTransfer.files[0]) jsStoreLoadFile(e.dataTransfer.files[0]); };
}

/* ════════ PUBBLICA una card locale su GitHub (richiede token con scrittura) ════════ */
let _ghPubId=null;
function _ghsPublish(id){
  const it=_jsStoreList().find(i=>(i.meta||{}).id===id);
  if(!it){ showToast('⚠️ Card non trovata'); return; }
  if(!_ghCfg().token){ showToast('🔑 Manca il token GitHub — aprilo con l\'⚙️ e incollalo'); openGitHubCfg(); return; }
  _ghPubId=id;
  document.getElementById('ghpub-name').value=(it.meta||{}).name||id;
  const base=(id||(it.meta||{}).name||'card').toLowerCase().replace(/[^a-z0-9._-]+/g,'-').replace(/^-+|-+$/g,'');
  // se la card era già installata da GitHub, ripubblica SULLO STESSO file (così aggiorna, non duplica)
  const g0=_ghCfg(); const knownFile=(g0.idFile&&g0.idFile[id])||'';
  document.getElementById('ghpub-file').value=knownFile||(/\.js$/i.test(base)?base:base+'.js');
  document.getElementById('ghpub-folder').value='card-js';
  document.getElementById('ghpub-status').textContent='';
  document.getElementById('ghpub').classList.remove('off');
}
function closeGhPub(){ document.getElementById('ghpub').classList.add('off'); }
/* Scrive la versione tracciata DENTRO il codice della card, così il file pubblicato
   riflette davvero la versione (e cambia contenuto → GitHub aggiorna). Aggiorna il
   primo campo "version: '...'"; se assente, aggiunge un commento header. */
function _stampVersion(code, ver){
  if(!ver) return code;
  // 1) se c'è un campo version: '...' → aggiornalo (preferito, sempre leggibile)
  if(/version\s*:\s*['"][^'"]*['"]/.test(code)){
    return code.replace(/version(\s*:\s*)(['"])[^'"]*['"]/, (m, sep, q)=>`version${sep}${q}${ver}${q}`);
  }
  // 2) se c'è già un marcatore canonico → aggiornalo
  if(/\/\*\s*frarik-version:[^*]*\*\//i.test(code)){
    return code.replace(/\/\*\s*frarik-version:[^*]*\*\//i, `/* frarik-version: ${ver} */`);
  }
  // 3) altrimenti rimuovi vecchi commenti "Frarik card · version: …" (evita accumuli) e premetti il marcatore canonico
  const cleaned=code.replace(/\/\*\s*Frarik card[^*]*version[^*]*\*\/\s*\n?/ig, '');
  return `/* frarik-version: ${ver} */\n` + cleaned;
}
async function _ghPublishDo(){
  const id=_ghPubId; if(!id) return;
  const it=_jsStoreList().find(i=>(i.meta||{}).id===id); if(!it){ showToast('⚠️ Card non trovata'); return; }
  const st=document.getElementById('ghpub-status');
  if(!_ghCfg().token){ st.innerHTML='<span style="color:#f87171">Manca il token GitHub (⚙️)</span>'; return; }
  const folder=document.getElementById('ghpub-folder').value;
  let file=(document.getElementById('ghpub-file').value||'').trim();
  if(!file){ st.innerHTML='<span style="color:#f87171">Inserisci il nome del file</span>'; return; }
  if(!/\.js$/i.test(file)) file+='.js';
  file=file.replace(/\s+/g,'-');
  const path=folder+'/'+file;
  const g0=_ghCfg();
  st.innerHTML='<span style="color:#fbbf24">⏳ Leggo la versione su GitHub…</span>';
  // Legge la versione ATTUALE su GitHub e incrementa il minore (1.0 → 1.1 → 1.2 …).
  // Prima pubblicazione (file non presente su GitHub) → 1.0.
  const remoteVer=await _ghReadRemoteVersion(path);
  const localTracked=g0.fileVersions[file];
  let base=remoteVer;
  if(!base) base=localTracked||null;                                   // niente su GitHub → usa il tracciato locale
  else if(localTracked && _verGt(localTracked, base)) base=localTracked; // GitHub "stantio" → usa il più alto
  const ver = base ? _bumpMinor(base) : '1.0';
  const code=_stampVersion(it.code, ver);   // imprime la versione nel codice prima di pubblicare
  st.innerHTML='<span style="color:#fbbf24">⏳ Pubblico su GitHub…</span>';
  try{
    const res=await _ghPut(path, code, 'Pubblica '+file+(ver?(' v'+ver):'')+' da Frarik');
    const newSha=res&&res.content&&res.content.sha;
    // ora è su GitHub → diventa una card "github"; salva il codice STAMPATO e allinea sha/versione
    try{
      _jsStoreSave(id, Object.assign({}, it.meta, {version:ver}), code, 'github');
      const g=_ghCfg(); g.idFile=g.idFile||{}; g.idFile[id]=file;
      g.fileVersions[file]=ver;
      // allinea sha + "già notificata" + cache versione: così lo store mostra subito la
      // versione pubblicata e NON arriva la notifica «nuova card» per il proprio publish
      if(newSha){ g.shas[file]=newSha; g.notifiedShas[file]=newSha; _ghVerCache[newSha]=ver; }
      saveCfg(); _haSaveCfg();
    }catch(e){}
    _ghsCache={};
    st.innerHTML='<span style="color:#4ade80">✅ Pubblicata in '+folder+'/'+file+(ver?(' (v'+ver+')'):'')+'</span>';
    showToast('📤 Card pubblicata su GitHub'+(ver?(' v'+ver):'')+'!');
    setTimeout(()=>{ closeGhPub(); if(!document.getElementById('gh-store-modal').classList.contains('off')) ghStoreTab('local'); }, 1000);
  }catch(e){ st.innerHTML='<span style="color:#f87171">⚠️ '+e.message+'</span>'; }
}
/* Crea o aggiorna un file nel repo via GitHub API (PUT). Serve il token in g.token. */
async function _ghPut(path, content, message){
  const g=_ghCfg();
  if(!g.owner||!g.repo) throw new Error('Configura proprietario/repository');
  if(!g.token) throw new Error('Manca il token GitHub');
  const branch=g.branch||'main';
  const base=`https://api.github.com/repos/${g.owner}/${g.repo}/contents/${path.split('/').map(encodeURIComponent).join('/')}`;
  const H={'Authorization':'token '+g.token,'Accept':'application/vnd.github.v3+json'};
  // legge lo sha CORRENTE del file (cache-busting: l'API contents di GitHub può servire
  // uno sha stantio subito dopo un commit → causa del 409 "does not match")
  const getSha=async()=>{
    try{
      const gr=await fetch(base+'?ref='+encodeURIComponent(branch)+'&_t='+Date.now(),{headers:H,cache:'no-store'});
      if(gr.ok){ const gj=await gr.json(); return gj.sha||null; }
    }catch(e){}
    return null;
  };
  let sha=await getSha();
  let lastErr='';
  for(let i=0;i<3;i++){
    const body={ message:message||('Aggiorna '+path), content:_b64utf8(content), branch };
    if(sha) body.sha=sha;
    const r=await fetch(base,{method:'PUT',headers:Object.assign({'Content-Type':'application/json'},H),body:JSON.stringify(body)});
    if(r.ok) return await r.json();
    if(r.status===401||r.status===403) throw new Error('GitHub 403 — token senza permessi di scrittura. Vai su GitHub → Settings → Developer settings → Personal access tokens (classic) → crea token con scope "repo" → incollalo nell\'⚙️ impostazioni GitHub dello store.');
    if(r.status===404) throw new Error('Repo non raggiungibile (404): probabilmente l\'invito come collaboratore non è stato accettato, o il token non ha accesso al repo.');
    let m=''; try{ m=(await r.json()).message; }catch(e){}
    lastErr='GitHub HTTP '+r.status+(m?' — '+m:'');
    // 409/422 = sha non aggiornato (conflitto): aspetta, rileggi lo sha fresco e riprova
    if(r.status===409||r.status===422){ await new Promise(res=>setTimeout(res,600*(i+1))); sha=await getSha(); continue; }
    throw new Error(lastErr);
  }
  throw new Error(lastErr||'GitHub: conflitto sha persistente (409). Riprova tra qualche secondo.');
}
function _b64utf8(str){ return btoa(unescape(encodeURIComponent(str))); }   // base64 UTF-8 per l'API GitHub

/* Elimina un file dal repo via GitHub API (DELETE). Serve il token in g.token. */
async function _ghDelete(path, message){
  const g=_ghCfg();
  if(!g.owner||!g.repo) throw new Error('Configura proprietario/repository');
  if(!g.token) throw new Error('Manca il token GitHub');
  const branch=g.branch||'main';
  const base=`https://api.github.com/repos/${g.owner}/${g.repo}/contents/${path.split('/').map(encodeURIComponent).join('/')}`;
  const H={'Authorization':'token '+g.token,'Accept':'application/vnd.github.v3+json'};
  const gr=await fetch(base+'?ref='+encodeURIComponent(branch)+'&_t='+Date.now(),{headers:H,cache:'no-store'});
  if(gr.status===404) throw new Error('File già assente su GitHub');
  if(!gr.ok) throw new Error('GitHub HTTP '+gr.status+' (lettura sha)');
  const sha=(await gr.json()).sha;
  const r=await fetch(base,{method:'DELETE',headers:Object.assign({'Content-Type':'application/json'},H),body:JSON.stringify({message:message||('Elimina '+path),sha,branch})});
  if(r.status===401||r.status===403) throw new Error('GitHub ha rifiutato (token senza permesso "repo"?)');
  if(!r.ok){ let m=''; try{ m=(await r.json()).message; }catch(e){} throw new Error('GitHub HTTP '+r.status+(m?' — '+m:'')); }
  return await r.json();
}

/* Cestino "Elimina da GitHub" (nello stato Da installare): conferma + CHIAVE di accesso. */
const _GHDEL_KEY='FRKD-HVEM-JJR7-5DAN';
async function _ghsDeleteFromGithub(enc){
  const name=decodeURIComponent(enc);
  const nm=name.replace(/\.(js|ya?ml)$/i,'');
  const f=(await _ghsEnsureFile(enc).catch(()=>null)) || _ghsFind(enc);
  const folder=_GHS_FOLDERS[_ghsTab];
  const path=(f&&f.path) || (folder?folder.path+'/'+name:name);
  showConfirm(
    `Eliminare <b>DEFINITIVAMENTE</b> «${eh(nm)}» da GitHub?<br>`+
    `<span style="font-size:11px;opacity:.7;display:block;margin:6px 0 4px">Operazione irreversibile. Inserisci la chiave di accesso:</span>`+
    `<input id="ghdel-key" type="text" autocomplete="off" placeholder="Chiave di accesso" style="width:100%;padding:9px 11px;border-radius:9px;border:1px solid rgba(255,255,255,.18);background:rgba(255,255,255,.06);color:#fff;font-size:13px;font-family:inherit;letter-spacing:.5px">`,
    async ()=>{
      const key=((document.getElementById('ghdel-key')||{}).value||'').trim();
      if(key!==_GHDEL_KEY){ showToast('🔑 Chiave errata — eliminazione annullata'); return; }
      try{
        showToast('🗑 Elimino «'+nm+'» da GitHub…');
        await _ghDelete(path, 'Elimina '+name+' dallo store (chiave verificata)');
        try{ const g=_ghCfg(); if(g.shas) delete g.shas[name]; if(g.fileVersions) delete g.fileVersions[name];
             if(g.idFile){ for(const id in g.idFile){ if(g.idFile[id]===name) delete g.idFile[id]; } } saveCfg(); _haSaveCfg&&_haSaveCfg(); }catch(e){}
        const _dft=_ghsFolderTab(_ghsTab); if(_ghsCache[_dft]) _ghsCache[_dft]=_ghsCache[_dft].filter(x=>x.name!==name);
        _ghStoreRender();
        showToast('✅ «'+nm+'» eliminata definitivamente da GitHub');
      }catch(e){ showToast('⚠️ Errore eliminazione GitHub: '+(e.message||e)); }
    },
    'Elimina da GitHub', 'Annulla'
  );
}
/* tab virtuali condividono la cache e la cartella di 'js' */
function _ghsFolderTab(tab){
  if(['cards-non-installate','cards-installate','elettrodomestici','installate','updates'].includes(tab)) return 'js';
  if(['distintivi-non-installate','distintivi-installate'].includes(tab)) return 'distintivi';
  if(['pkg-non-installati','pkg-installati','pkg'].includes(tab)) return 'pkg';
  return tab;
}
function _ghsFind(name){
  name=decodeURIComponent(name);
  /* nel tab "updates" o in qualsiasi tab card si cerca in tutte le cache */
  if(_ghsTab==='updates'||_GHS_CARDS_TABS.includes(_ghsTab)||_GHS_DISTINTIVI_TABS.includes(_ghsTab)){
    for(const k of Object.keys(_GHS_FOLDERS)){ const found=(_ghsCache[k]||[]).find(f=>f.name===name); if(found) return found; }
    return null;
  }
  return (_ghsCache[_ghsFolderTab(_ghsTab)]||[]).find(f=>f.name===name);
}
/* ricarica (se serve) la lista file della cartella corrente e ritrova il file:
   evita il caso "dopo l'eliminazione il tasto Installa non fa nulla" (cache vuota/stale) */
async function _ghsEnsureFile(name){
  let f=_ghsFind(name);
  if(f) return f;
  /* nel tab "updates" prova tutte le cartelle install fino a trovare il file */
  if(_ghsTab==='updates'){
    for(const [key,fol] of Object.entries(_GHS_FOLDERS)){
      if(fol.kind!=='install') continue;
      try{
        const files=await _ghListFolder(fol.path);
        _ghsCache[key]=files.filter(x=>fol.ext.test(x.name)&&!(fol.exclude&&fol.exclude.test(x.name)));
      }catch(e){ continue; }
      const found=(_ghsCache[key]||[]).find(x=>x.name===decodeURIComponent(name));
      if(found) return found;
    }
    return null;
  }
  const ft=_ghsFolderTab(_ghsTab); const fol=_GHS_FOLDERS[ft]; if(!fol) return null;
  try{
    const files=await _ghListFolder(fol.path);
    _ghsCache[ft]=files.filter(x=>fol.ext.test(x.name)&&!(fol.exclude&&fol.exclude.test(x.name)));
  }catch(e){ return null; }
  return _ghsFind(name);
}
async function _ghsInstall(name){
  let f=await _ghsEnsureFile(name);
  if(!f){ showToast('⚠️ File non trovato su GitHub — premi ↻ per ricaricare'); return; }
  let code;
  try{ code=await _ghDownload(f); }catch(e){ showToast('⚠️ Download fallito: '+e.message); return; }
  const res=_installCardCode(code);
  if(res.err){ showToast('⚠️ Errore caricamento: '+res.err.message); return; }
  const _instId=f.name.replace(/\.js$/i,'');
  /* controlla tramite regex se il codice richiede un pkg HA */
  const _pkgMatch=code.match(/frarik_pkg_check\s*:\s*['"]([^'"]+)['"]/);
  const _pkgVerMatch=code.match(/frarik_pkg_version\s*:\s*['"]([^'"]+)['"]/);
  const _pkgVerNew=_pkgVerMatch?_pkgVerMatch[1]:null;
  /* pkg: per nuove installazioni verifica che sia già su HA — non mostrare più il dialog */
  const _isUpdate=!!(_ghCfg().shas[f.name]);
  if(_pkgMatch&&!_isUpdate){
    await _loadHaInstalledPkgs();
    const _pkgInfoChk=_parsePkgInfo(code)||{};
    const _pkgFileChk=_pkgInfoChk.file||'';
    if(_pkgFileChk&&!_pkgIsOnHA(_pkgFileChk)){
      const _pkgNm=_pkgFileChk.split('/').pop().replace(/\.ya?ml$/i,'').replace(/^frarik_/,'');
      showToast('⚠️ Installa prima il PKG "'+_pkgNm+'" dal tab PKG dello store');
      return;
    }
    _savePkgVer(_instId,_pkgVerNew);
    _ghsDoInstall(f,code,res);
    return;
  }
  _ghsDoInstall(f,code,res);
  /* card JS aggiornata — il PKG è una cosa separata: usa il bottone "Aggiorna PKG" nello store */
  showToast('✅ '+f.name+(_isUpdate?' aggiornata':' installata — usa ➕ Aggiungi per metterla in dashboard'));
}

/* salva il codice JS nello store locale + aggiorna sha/versione + refresh UI */
function _ghsDoInstall(f,code,res){
  const id=(res.newCards&&res.newCards[0])||(res.tags&&res.tags[0]);
  const card=id?window.FratechCardRegistry[id]:null;
  if(card&&card.id){
    const g=_ghCfg(); const version=_parseCardVersion(code)||'1.0';
    g.fileVersions[f.name]=version;
    g.idFile=g.idFile||{}; g.idFile[card.id]=f.name;
    _ghVerCache[f.sha]=version;
    _jsStoreSave(card.id,{id:card.id,name:card.name||card.id,icon:card.icon||'📦',version,desc:card.desc||''},code,'github');
  }
  _ghCfg().shas[f.name]=f.sha;
  _ghCfg().notifiedShas[f.name]=f.sha;
  try{_ntfClearGh(f.path||f.name);}catch(e){}
  saveCfg(); _haSaveCfg();
  if(typeof _jsStoreRenderList==='function') _jsStoreRenderList();
  if(typeof _epRenderJsStore==='function') _epRenderJsStore();
  renderDash(); _ghStoreRender();
}

/* helper — salva la versione del pkg installato in cfg */
function _savePkgVer(cardId,ver){
  if(!ver) return;
  const key=(cardId||'').toLowerCase()||cardId;
  const g=_ghCfg(); g.pkgVersions=g.pkgVersions||{};
  if(key!==cardId&&g.pkgVersions[cardId]!==undefined) delete g.pkgVersions[cardId];
  g.pkgVersions[key]=ver;
  saveCfg(); _haSaveCfg();
}

