/* Scarica il template YAML grezzo (con IL_TUO_*) dalla cartella pkg/ su GitHub */
async function _downloadPkgRaw(pkgInfo){
  try{
    const file=(pkgInfo?.file||'').split('/').pop();
    if(!file) return null;
    const g=_ghCfg();
    const url=`https://raw.githubusercontent.com/${g.owner||'Frarik'}/${g.repo||'cards'}/${g.branch||'main'}/pkg/${file}?_t=${Date.now()}`;
    const r=await fetch(url,{cache:'no-store'});
    if(!r.ok) return null;
    return await r.text();
  }catch(e){ return null; }
}

/* Installazione generica per card senza openWizard(): scarica il pkg da GitHub e lo installa */
async function _pkgGenericInstall(cardId,pkgVer,pkgInfo,f,code,res){
  const file=pkgInfo?.file||'';
  if(!file){ showToast('⚠️ Wizard non disponibile e nessun file pkg specificato'); return; }
  const pkgName=file.split('/').pop();
  showToast('⏳ Installo package…');
  try{
    const g=_ghCfg();
    const rawUrl=`https://raw.githubusercontent.com/${g.owner||'Frarik'}/${g.repo||'cards'}/${g.branch||'main'}/pkg/${pkgName}`;
    const ghR=await fetch(rawUrl);
    if(!ghR.ok){ showToast('⚠️ Package "'+pkgName+'" non trovato nel repo — caricarlo manualmente nel tab Packages'); return; }
    let content=await ghR.text();
    const _pkgInputs=_pkgParseInputs(content);
    if(_pkgInputs.length){
      let _pkgSaved={};try{_pkgSaved=JSON.parse(localStorage.getItem('_frarik_pkg_inputs_'+pkgName.replace(/\.ya?ml$/i,''))||'{}');}catch(_){}
      content=await _pkgShowWizard(pkgName,content,_pkgInputs,_pkgSaved);
      if(content===null){ showToast('⚠️ Installazione annullata'); return; }
    }
    const r=await fetch(ADDON_BASE+'/api/frarik/pkg/install',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:file,content})});
    const d=await r.json();
    if(!d.ok){ showToast('⚠️ Errore installazione: '+(d.error||'?')); return; }
    _savePkgVer(cardId,pkgVer);
    if(f&&res) _ghsDoInstall(f,code,res);
    else{ if(typeof _ghStoreRender==='function') _ghStoreRender(); }
    await _pkgPostInstall(cardId,pkgVer);
  }catch(e){ showToast('⚠️ '+e.message); }
}

