/* aggiorna il PKG di una card installata.
   Scarica sempre il template aggiornato da GitHub e applica la config wizard salvata.
   silent=true → no wizard, no toast interattivi (chiamato dall'auto-update in background) */
async function _pkgUpdateCard(cardId, silent=false){
  const it=_jsStoreList().find(i=>(i.meta||{}).id?.toLowerCase()===(cardId||'').toLowerCase());
  if(!it){ if(!silent) showToast('⚠️ Card non trovata nello store locale'); return; }
  const pkgInfo=_parsePkgInfo(it.code||'');
  if(!pkgInfo){ if(!silent) showToast('⚠️ Nessun package associato a questa card'); return; }

  const wizKey='frarik_pkg_wizard_'+(cardId||'').toLowerCase();
  const savedCfg=JSON.parse(localStorage.getItem(wizKey)||'null');  // sempre letta

  const _ctor2=customElements.get(cardId);
  const _reg2=window.FratechCardRegistry?.[cardId]??window.FratechCardRegistry?.[cardId.toLowerCase()];
  const CardClass=typeof _ctor2?._buildPkgFromConfig==='function'?_ctor2:(_reg2??_ctor2);

  /* Aggiornamento manuale (silent=false) con wizard disponibile → apri sempre il wizard.
     I valori precedenti vengono riletti da localStorage e pre-compilati automaticamente. */
  if(!silent && typeof CardClass?.openWizard==='function'){
    const ghTpl=await _downloadPkgRaw(pkgInfo);
    const pkgVer=pkgInfo.ver;
    const f=_ghsFind(encodeURIComponent((pkgInfo.file||'').split('/').pop()));
    CardClass.openWizard(_haHassObj(),async ()=>{
      _savePkgVer(cardId,pkgVer);
      if(f) _ghsDoInstall(f,it.code,null);
      await _pkgPostInstall(cardId,pkgVer);
      await _loadHaInstalledPkgs();
      if(typeof _ghStoreRender==='function') _ghStoreRender();
    }, ghTpl||undefined, {isUpdate:true});
    return;
  }

  /* Aggiornamento silenzioso (auto-update in background) → applica config salvata senza wizard */
  if(savedCfg && typeof CardClass?._buildPkgFromConfig==='function'){
    const ghTpl=await _downloadPkgRaw(pkgInfo);
    const yaml=CardClass._buildPkgFromConfig(savedCfg, ghTpl||undefined);
    if(!yaml){ return; }
    try{
      const m=location.pathname.match(/^(.*\/api\/hassio_ingress\/[^/]+)/);
      const base=location.origin+(m?m[1]:'');
      const fname=pkgInfo.file||(pkgInfo.id?'frarik/'+pkgInfo.id+'.yaml':'');
      const r=await fetch(base+'/api/frarik/pkg/install',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:fname,content:yaml})});
      const j=await r.json().catch(()=>({}));
      if(r.ok&&j.ok){
        _savePkgVer(cardId,pkgInfo.ver);
        await _loadHaInstalledPkgs();
        if(typeof _ghStoreRender==='function') _ghStoreRender();
      }
    }catch(e){}
    return;
  }
  /* Card senza wizard (o aggiornamento silenzioso senza config) → raw GitHub */
  await _pkgGenericInstall(cardId,pkgInfo.ver,pkgInfo,null,it.code,null);
  _loadHaInstalledPkgs().then(()=>{ if(typeof _ghStoreRender==='function') _ghStoreRender(); });
}

async function _ghsCopy(name){
  const f=_ghsFind(name); if(!f) return;
  let txt; try{ txt=await _ghDownload(f); }catch(e){ showToast('⚠️ '+e.message); return; }
  if(navigator.clipboard && window.isSecureContext){
    try{ await navigator.clipboard.writeText(txt); showToast('📋 "'+f.name+'" copiata negli appunti'); return; }catch(e){}
  }
  // fallback per HTTP locale (contesto non sicuro): textarea + execCommand
  try{
    const ta=document.createElement('textarea'); ta.value=txt; ta.style.position='fixed'; ta.style.top='-1000px'; ta.style.opacity='0';
    document.body.appendChild(ta); ta.focus(); ta.select(); document.execCommand('copy'); document.body.removeChild(ta);
    showToast('📋 "'+f.name+'" copiata negli appunti');
  }catch(e){ showToast('⚠️ Copia non riuscita — usa ⬇️ per scaricare il file'); }
}
async function _ghsDownload(name){
  const f=_ghsFind(name); if(!f) return;
  try{ const txt=await _ghDownload(f); const b=new Blob([txt],{type:'text/plain'}); const u=URL.createObjectURL(b);
    const a=document.createElement('a'); a.href=u; a.download=f.name; a.click(); setTimeout(()=>URL.revokeObjectURL(u),1000);
    showToast('⬇️ Scarico '+f.name);
  }catch(e){ showToast('⚠️ Download non riuscito: '+e.message); }
}
/* Scheda YAML dello store → "Aggiungi alla dashboard": scarica il file YAML dal repo, apre l'import
   precompilato e genera l'anteprima. L'utente conferma con "Aggiungi" (riusa il flusso yaml-card). */
async function _ghsYamlAdd(name){
  const f=_ghsFind(name); if(!f){ showToast('⚠️ File non trovato'); return; }
  showToast('⬇️ Carico '+f.name+'…');
  let txt; try{ txt=await _ghDownload(f); }catch(e){ showToast('⚠️ '+(e.message||e)); return; }
  try{ closeGhStore(); }catch(e){}
  openYamlImport();
  const inp=document.getElementById('ymd-inp'); if(inp){ inp.value=txt; _ymdSyncLines(); }
  try{ await _ymdLivePreview(); }catch(e){}   // genera l'anteprima; poi l'utente preme "Aggiungi"
}

/* ════════ PKG — infrastruttura: parsing, stato HA, mapping card↔file ════════ */

/* Estrae info PKG dal codice JS di una card */
function _parsePkgInfo(code){
  const check=(code.match(/frarik_pkg_check\s*:\s*['"]([^'"]+)['"]/)||[])[1]||'';
  const id   =(code.match(/frarik_pkg_id\s*:\s*['"]([^'"]+)['"]/)||[])[1]||'';
  const file =(code.match(/frarik_pkg_file\s*:\s*['"]([^'"]+)['"]/)||[])[1]||'';
  const ver  =(code.match(/frarik_pkg_version\s*:\s*['"]([^'"]+)['"]/)||[])[1]||'';
  if(!check&&!id&&!file) return null;
  const resolvedFile=file||(id?'frarik/'+id+'.yaml':'');
  return {check, id, ver, file:resolvedFile};
}

/* Set dei file yaml installati su HA (nomi come 'frarik/frarik_posta.yaml' o 'frarik_posta.yaml') */
let _haInstalledPkgs=new Set();

async function _loadHaInstalledPkgs(){
  try{
    const r=await fetch(ADDON_BASE+'/api/frarik/pkg/list');
    if(!r.ok) return;
    const d=await r.json();
    /* Conserva il case esatto restituito dal filesystem — Linux è case-sensitive */
    _haInstalledPkgs=new Set(d.files||[]);
  }catch(e){}
}

/* Verifica se un pkg è installato su HA, accettando nomi con o senza sottocartella */
function _pkgIsOnHA(file){
  if(!file) return false;
  const f=file.toLowerCase();
  for(const k of _haInstalledPkgs){ if(k.toLowerCase()===f) return true; }
  const base=f.split('/').pop();
  for(const k of _haInstalledPkgs){ if(k.toLowerCase().split('/').pop()===base) return true; }
  return false;
}

/* Recupera PKG info per una card installata (dalla sua code in store) */
function _pkgInfoForInstalledCard(cardId){
  const s=_jsStoreList().find(i=>(i.meta||{}).id===cardId);
  return s?.code?_parsePkgInfo(s.code):null;
}

/* Dopo installazione PKG: aggiorna stato e offre restart */
async function _pkgPostInstall(cardId,pkgVer){
  await _loadHaInstalledPkgs();
  if(_isPkgTab()) _ghStoreRender();
  showConfirm(
    '📦 Package installato!<br><br>'+
    'Per attivare le nuove entità è necessario <b>riavviare Home Assistant</b>.<br>'+
    '<span style="font-size:11px;opacity:.7">La dashboard si riconnetterà da sola dopo il riavvio.</span>',
    ()=>{ try{send({type:'call_service',domain:'homeassistant',service:'restart'});}catch(e){} showToast('🔄 Riavvio HA in corso…'); try{setC('wait');}catch(e){} },
    '🔄 Riavvia HA ora','Lo faccio dopo'
  );
}

/* Disinstalla un pkg da HA (/config/packages/) */
async function _pkgUninstallFromHA(filename){
  const decoded=decodeURIComponent(filename);
  const nm=decoded.split('/').pop().replace(/\.ya?ml$/i,'');
  showConfirm(
    `🗑️ Rimuovere il package <b>${eh(nm)}</b> da Home Assistant?<br><br>`+
    `<span style="font-size:11px;opacity:.7">Il file verrà eliminato dal file editor di HA.<br>Potrai reinstallarlo in qualsiasi momento dallo store.</span>`,
    async ()=>{
      try{
        const r=await fetch(ADDON_BASE+'/api/frarik/pkg/uninstall',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:decoded})});
        const d=await r.json();
        if(!d.ok){ showToast('⚠️ '+d.error); return; }
        await _loadHaInstalledPkgs();
        if(_isPkgTab()) _ghStoreRender();
        showConfirm(
          `🗑️ Package <b>${eh(nm)}</b> rimosso da HA.<br><br>`+
          `Per applicare le modifiche è consigliato <b>riavviare Home Assistant</b>.<br>`+
          `<span style="font-size:11px;opacity:.7">La dashboard si riconnetterà da sola dopo il riavvio.</span>`,
          ()=>{ try{send({type:'call_service',domain:'homeassistant',service:'restart'});}catch(e){} showToast('🔄 Riavvio HA in corso…'); try{setC('wait');}catch(e){} },
          '🔄 Riavvia HA ora','Lo faccio dopo'
        );
      }catch(e){ showToast('⚠️ Errore: '+e.message); }
    },
    '🗑️ Rimuovi','Annulla'
  );
}

/* Visualizza YAML di un pkg installato su HA */
async function _pkgViewOnHA(filename){
  const decoded=decodeURIComponent(filename);
  const nm=decoded.split('/').pop();
  try{
    const _pkgUrl=ADDON_BASE+'/api/frarik/pkg/read?name='+encodeURIComponent(decoded);
    const r=await fetch(_pkgUrl);
    if(!r.ok){ console.error('[Frarik] pkg/read fallito',{url:_pkgUrl,status:r.status,decoded}); showToast('⚠️ File non trovato: /config/packages/'+decoded+' (HTTP '+r.status+')'); return; }
    const txt=await r.text();
    const mo=document.createElement('div');
    mo.style.cssText='position:fixed;inset:0;z-index:9700;display:flex;align-items:flex-end;justify-content:center;background:rgba(0,0,0,.75);backdrop-filter:blur(6px)';
    mo.innerHTML=`<style>@keyframes _pv_su{from{transform:translateY(100%)}to{transform:translateY(0)}}</style>
    <div style="background:#0d1020;border:1px solid rgba(255,255,255,.12);border-radius:20px 20px 0 0;border-bottom:none;width:100%;max-height:85vh;display:flex;flex-direction:column;overflow:hidden;animation:_pv_su .24s cubic-bezier(.32,1.12,.56,1)">
      <div style="display:flex;align-items:center;gap:12px;padding:16px 18px;border-bottom:1px solid rgba(255,255,255,.07);flex-shrink:0">
        <div style="width:38px;height:38px;border-radius:12px;background:rgba(99,102,241,.15);border:1px solid rgba(99,102,241,.3);display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0">📦</div>
        <span style="flex:1;font-weight:700;color:#fff;font-size:14px">${eh(nm)}</span>
        <button id="_pv_close" style="background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16);border-radius:8px;padding:6px 12px;color:#fff;font-size:13px;cursor:pointer">✕</button>
      </div>
      <pre style="flex:1;overflow:auto;padding:16px 18px;font-size:11px;line-height:1.6;color:#c4d8f5;font-family:monospace;margin:0;white-space:pre-wrap;word-break:break-all">${eh(txt)}</pre>
    </div>`;
    mo.querySelector('#_pv_close').onclick=()=>mo.remove();
    mo.addEventListener('click',e=>{if(e.target===mo)mo.remove();});
    document.body.appendChild(mo);
  }catch(e){ showToast('⚠️ '+e.message); }
}

/* Estrae i placeholder IL_TUO_* dal YAML con label dal contesto */
function _pkgParseInputs(yaml){
  const inputs=[],seen=new Set(),lines=yaml.split('\n');
  lines.forEach((line,i)=>{
    (line.match(/IL_TUO_\w+/g)||[]).forEach(ph=>{
      if(seen.has(ph)) return; seen.add(ph);
      let label='';
      /* inline: la chiave YAML è sulla stessa riga del placeholder */
      if(!line.trim().startsWith('-')){
        const m=line.match(/^\s*([A-Za-z][^:#&\n]+?):\s*/);
        if(m) label=m[1].trim();
      }
      /* list item: cerca la chiave padre nelle righe precedenti */
      if(!label){
        for(let j=i-1;j>=0;j--){
          if(!lines[j].trim()) continue;
          const m=lines[j].match(/^\s*([A-Za-z][^:#\n]+?):\s*(?:&\w+)?\s*$/);
          if(m){ label=m[1].trim(); break; }
          if(!lines[j].trim().startsWith('-')) break;
        }
      }
      /* fallback: genera dal nome del placeholder */
      if(!label) label=ph.replace('IL_TUO_','').split('_').map(w=>w.charAt(0)+w.slice(1).toLowerCase()).join(' ');
      inputs.push({placeholder:ph,label});
    });
  });
  return inputs;
}

/* Autocomplete entità HA su un campo input — usa window.hs come sorgente */
function _frarikEntityAutocomplete(inp){
  const all=Object.keys(window.hs||{}).sort();
  const showDrop=()=>{
    document.getElementById('_fac_drop')?.remove();
    const q=inp.value.toLowerCase();
    const filtered=(q?all.filter(e=>e.includes(q)):all).slice(0,80);
    if(!filtered.length) return;
    const rect=inp.getBoundingClientRect();
    const d=document.createElement('div');
    d.id='_fac_drop';
    d.style.cssText=`position:fixed;left:${rect.left}px;top:${rect.bottom+2}px;width:${rect.width}px;z-index:99999;background:#1a1f35;border:1px solid rgba(255,255,255,.2);border-radius:10px;max-height:200px;overflow-y:auto;box-shadow:0 8px 24px rgba(0,0,0,.6)`;
    d.innerHTML=filtered.map(e=>`<div data-v="${e}" style="padding:8px 12px;font-size:11px;font-family:monospace;color:#fff;cursor:pointer;border-bottom:1px solid rgba(255,255,255,.04)">${e}</div>`).join('');
    d.querySelectorAll('[data-v]').forEach(item=>{
      item.onmousedown=ev=>{ev.preventDefault();inp.value=item.dataset.v;d.remove();};
      item.onmouseover=()=>item.style.background='rgba(255,255,255,.08)';
      item.onmouseout=()=>item.style.background='';
    });
    document.body.appendChild(d);
  };
  inp.addEventListener('focus',showDrop);
  inp.addEventListener('input',showDrop);
  inp.addEventListener('blur',()=>setTimeout(()=>document.getElementById('_fac_drop')?.remove(),150));
}

/* Wizard bottom-sheet: chiede i valori per i placeholder, restituisce YAML sostituito o null se annullato */
function _pkgShowWizard(pkgName,yaml,inputs,savedValues){
  savedValues=savedValues||{};
  return new Promise(resolve=>{
    const nm=pkgName.replace(/\.ya?ml$/i,'').replace(/^frarik_/,'');
    const pkgKey=pkgName.replace(/\.ya?ml$/i,'');
    const hasSaved=Object.keys(savedValues).length>0;
    const fields=inputs.map((inp,idx)=>`
      <div style="margin-bottom:14px">
        <div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:rgba(255,255,255,.45);margin-bottom:6px">${eh(inp.label)}</div>
        <input data-key="${eh(inp.placeholder)}" id="_pwz_f${idx}" autocomplete="off" spellcheck="false"
          type="text" placeholder="${eh(inp.placeholder)}"
          value="${eh(savedValues[inp.placeholder]||'')}"
          style="width:100%;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.12);border-radius:10px;padding:10px 12px;color:#fff;font-size:12px;font-family:monospace;outline:none;box-sizing:border-box">
      </div>`).join('');
    const mo=document.createElement('div');
    mo.style.cssText='position:fixed;inset:0;z-index:9800;display:flex;align-items:flex-end;justify-content:center;background:rgba(0,0,0,.75);backdrop-filter:blur(6px)';
    mo.innerHTML=`<style>@keyframes _pwz_su{from{transform:translateY(100%)}to{transform:translateY(0)}}</style>
    <div style="background:#0d1020;border:1px solid rgba(255,255,255,.12);border-top:1px solid rgba(255,255,255,.12);border-radius:20px 20px 0 0;width:100%;max-height:88vh;display:flex;flex-direction:column;overflow:hidden;animation:_pwz_su .24s cubic-bezier(.32,1.12,.56,1)">
      <div style="display:flex;align-items:center;gap:12px;padding:16px 18px;border-bottom:1px solid rgba(255,255,255,.07);flex-shrink:0">
        <div style="width:38px;height:38px;border-radius:12px;background:rgba(99,102,241,.15);border:1px solid rgba(99,102,241,.3);display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0">📦</div>
        <div style="flex:1;min-width:0">
          <div style="font-size:15px;font-weight:700;color:#fff">Configura Package</div>
          <div style="font-size:11px;color:rgba(255,255,255,.4);margin-top:1px">${eh(nm)}</div>
        </div>
        <button id="_pwz_x" style="background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16);border-radius:8px;padding:6px 12px;color:#fff;font-size:13px;cursor:pointer">✕</button>
      </div>
      <div style="flex:1;overflow-y:auto;padding:16px 18px">
        <div style="font-size:12px;color:rgba(255,255,255,.5);margin-bottom:16px;line-height:1.7">
          Inserisci le entità di Home Assistant da usare in questo package.<br>
          <span style="color:rgba(255,255,255,.3)">Tocca un campo per vedere la lista delle entità disponibili.</span>
        </div>
        ${hasSaved?`<div style="margin-bottom:14px;padding:8px 12px;background:rgba(99,102,241,.12);border:1px solid rgba(99,102,241,.3);border-radius:10px;font-size:11px;color:rgba(99,102,241,.9)">✏️ Valori precompilati dall'installazione precedente — verifica e conferma.</div>`:''}
        ${fields}
      </div>
      <div style="padding:14px 18px 28px;border-top:1px solid rgba(255,255,255,.07);display:flex;gap:10px;flex-shrink:0">
        <button id="_pwz_cancel" style="padding:12px 16px;border-radius:12px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.1);color:rgba(255,255,255,.6);font-size:13px;font-weight:600;cursor:pointer">Annulla</button>
        <button id="_pwz_ok" style="flex:1;padding:12px;border-radius:12px;background:linear-gradient(135deg,#6366f1,#4f46e5);border:none;color:#fff;font-size:14px;font-weight:700;cursor:pointer;box-shadow:0 4px 16px rgba(99,102,241,.35)">📦 Installa Package</button>
      </div>
    </div>`;
    const close=r=>{document.getElementById('_fac_drop')?.remove();mo.remove();resolve(r);};
    mo.querySelector('#_pwz_x').onclick=()=>close(null);
    mo.querySelector('#_pwz_cancel').onclick=()=>close(null);
    mo.addEventListener('click',e=>{if(e.target===mo)close(null);});
    mo.querySelector('#_pwz_ok').onclick=()=>{
      let out=yaml;
      const toSave={};
      mo.querySelectorAll('[data-key]').forEach(inp=>{
        let val=inp.value.trim();
        if(val){
          toSave[inp.dataset.key]=val;
          /* Se il YAML ha già "domain.PLACEHOLDER" e l'utente scrive "domain.entity",
             rimuovi il prefisso dominio dal valore per evitare "domain.domain.entity" */
          const domPfx=(val.match(/^([a-z_]+)\./)||[])[1];
          if(domPfx && out.includes(domPfx+'.'+inp.dataset.key)) val=val.slice(domPfx.length+1);
          const re=new RegExp(inp.dataset.key.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'g');
          out=out.replace(re,val);
        }
      });
      try{localStorage.setItem('_frarik_pkg_inputs_'+pkgKey,JSON.stringify(toSave));}catch(_){}
      close(out);
    };
    document.body.appendChild(mo);
    /* attiva autocomplete entità su ogni campo */
    setTimeout(()=>{
      mo.querySelectorAll('[data-key]').forEach(inp=>_frarikEntityAutocomplete(inp));
      mo.querySelector('[data-key]')?.focus();
    },80);
  });
}

/* Installa un pkg da GitHub direttamente su HA */
async function _ghsPkgInstallFromGH(filename){
  const decoded=decodeURIComponent(filename);
  showToast('⬇️ Download pkg da GitHub...');
  try{
    const g=_ghCfg();
    const url=`https://raw.githubusercontent.com/${g.owner||'Frarik'}/${g.repo||'cards'}/${g.branch||'main'}/pkg/${decoded}`;
    const r=await fetch(url); if(!r.ok) throw new Error('Download fallito');
    let yaml=await r.text();
    /* Wizard configurazione se il YAML contiene placeholder IL_TUO_* */
    const inputs=_pkgParseInputs(yaml);
    if(inputs.length){
      let _ghSaved={};try{_ghSaved=JSON.parse(localStorage.getItem('_frarik_pkg_inputs_'+decoded.replace(/\.ya?ml$/i,''))||'{}');}catch(_){}
      yaml=await _pkgShowWizard(decoded,yaml,inputs,_ghSaved);
      if(yaml===null){ showToast('⚠️ Installazione annullata'); return; }
    }
    const res=await fetch(ADDON_BASE+'/api/frarik/pkg/install',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'frarik/'+decoded,content:yaml})});
    if(!res.ok) throw new Error((await res.json()).error||'Errore installazione');
    await _pkgPostInstall(null,null);
    const _pkgFile=(_ghsCache.pkg||[]).find(x=>x.name===decoded);
    if(_pkgFile){ const _g=_ghCfg(); _g.pkgShas=_g.pkgShas||{}; _g.pkgShas[decoded]=_pkgFile.sha; saveCfg(); }
    delete _pkgPending[decoded];
    showToast('✅ Package installato su HA');
    ghStoreTab('pkg-installati');
  }catch(e){ showToast('⚠️ '+e.message); }
}

/* Installa un pkg locale (store locale) su HA */
async function _pkgInstallLocalToHA(filename){
  const decoded=decodeURIComponent(filename);
  const all=_pkgStoreList();
  const item=all.find(f=>f.name===decoded); if(!item){ showToast('⚠️ File non trovato'); return; }
  try{
    const res=await fetch(ADDON_BASE+'/api/frarik/pkg/install',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:decoded,content:item.content})});
    if(!res.ok) throw new Error((await res.json()).error||'Errore installazione');
    await _pkgPostInstall(null,null);
    showToast('✅ Package installato su HA');
    ghStoreTab('pkg-installati');
  }catch(e){ showToast('⚠️ '+e.message); }
}

/* ════════ PKG — Store locale pacchetti YAML (come card JS, ma per file .yaml) ════════ */
function _pkgStoreKey(name){ return 'fratech_pkg_'+name; }
function _pkgStoreSave(name, content, origin){
  try{ localStorage.setItem(_pkgStoreKey(name), JSON.stringify({name, content, ts:Date.now(), origin:origin||'local'})); }catch(e){}
}
function _pkgStoreDelete(name){ try{ localStorage.removeItem(_pkgStoreKey(name)); }catch(e){} }
function _pkgStoreList(){
  const out=[];
  for(let i=0;i<localStorage.length;i++){
    const k=localStorage.key(i); if(!k||!k.startsWith('fratech_pkg_')) continue;
    let v=null; try{ v=JSON.parse(localStorage.getItem(k)); }catch(e){}
    if(v&&v.name&&v.content) out.push(v);
  }
  return out;
}

function _ghStoreRenderPkg(q){
  const list=document.getElementById('ghs-list'), status=document.getElementById('ghs-status');

  /* Mappa cardId → card name (per mostrare quale card usa il pkg) */
  const cardPkgMap={};
  _jsStoreList().forEach(({meta,code})=>{
    const id=(meta||{}).id, name=(meta||{}).name||id;
    const info=code?_parsePkgInfo(code):null;
    if(id&&info?.file) cardPkgMap[info.file.toLowerCase()]=name;
  });

  const ghFiles=(_ghsCache.pkg||[]).slice();
  const ghNames=new Set(ghFiles.map(f=>f.name.toLowerCase()));

  /* Pkg installati su HA (escludi quelli con aggiornamento → vanno nel tab "da aggiornare") */
  const haList=Array.from(_haInstalledPkgs).filter(f=>{
    const bn=f.split('/').pop().toLowerCase();
    return (!q||f.toLowerCase().includes(q.toLowerCase()))&&!_pkgPending[bn];
  }).sort();
  /* Pkg su GitHub non ancora su HA */
  const ghNotHA=ghFiles.filter(f=>!_pkgIsOnHA('frarik/'+f.name)&&!_pkgIsOnHA(f.name)&&(!q||f.name.toLowerCase().includes(q.toLowerCase())));

  status.textContent=`${haList.length} installati su HA  ·  ${ghFiles.length} su GitHub`;

  const pkgRow=(filename,origin,acts,badge='')=>{
    const nm=filename.split('/').pop().replace(/\.ya?ml$/i,'');
    const cardName=cardPkgMap[filename.toLowerCase()]||cardPkgMap[filename.split('/').pop().toLowerCase()]||'';
    const originLbl=origin==='ha'
      ?`<span style="color:#4ade80;font-size:10px;font-weight:700">✅ Su HA</span>`
      :`<span style="color:#818cf8;font-size:10px;font-weight:700"><i class="mdi mdi-github"></i> GitHub</span>`;
    return `<div class="ghs-row" style="align-items:flex-start">
      <div class="ghs-ico" style="font-size:22px;padding-top:2px">📦</div>
      <div class="ghs-info" style="flex:1;min-width:0">
        <div class="ghs-name" style="display:flex;align-items:center;gap:6px;flex-wrap:wrap">${eh(nm)}${badge}</div>
        <div class="ghs-sub" style="display:flex;flex-wrap:wrap;gap:6px;align-items:center;margin-top:2px">
          ${originLbl}
          ${cardName?`<span style="color:rgba(255,255,255,.45);font-size:10px">Card: ${eh(cardName)}</span>`:''}
          <span style="color:rgba(255,255,255,.25);font-size:10px">${eh(filename)}</span>
        </div>
      </div>
      <div class="ghs-acts" style="flex-shrink:0">${acts}</div>
    </div>`;
  };

  let html='';

  /* ── Installati su HA ── */
  html+=`<div class="ghs-subhdr" style="display:flex;align-items:center;gap:8px"><i class="mdi mdi-check-circle" style="color:#4ade80"></i> Installati su Home Assistant <span style="margin-left:auto;background:rgba(74,222,128,.15);border:1px solid rgba(74,222,128,.3);border-radius:8px;padding:2px 8px;font-size:10px;color:#4ade80">${haList.length}</span></div>`;
  if(haList.length){
    html+=haList.map(f=>{
      const enc=encodeURIComponent(f);
      const baseName=f.split('/').pop();
      const hasPkgUpd=!!_pkgPending[baseName];
      const badge=hasPkgUpd
        ?`<span style="background:rgba(251,146,60,.2);border:1px solid rgba(251,146,60,.5);color:#fb923c;font-size:9px;font-weight:700;padding:1px 6px;border-radius:10px">📦 Aggiornamento</span>`
        :'';
      const updBtn=hasPkgUpd
        ?`<button class="ghs-btn ghs-btn-upd" data-action="_ghsPkgUpdFromPending" data-action-arg="${encodeURIComponent(baseName)}" style="background:rgba(251,146,60,.15);border-color:rgba(251,146,60,.4);color:#fb923c"><i class="mdi mdi-package-up"></i> Aggiorna</button>`
        :'';
      return pkgRow(f,'ha',
        updBtn+
        `<button class="ghs-btn" data-action="_pkgViewOnHA" data-action-arg="${enc}" title="Visualizza YAML"><i class="mdi mdi-eye-outline"></i></button>`+
        `<button class="ghs-btn ghs-ibtn-del" data-action="_pkgUninstallFromHA" data-action-arg="${enc}" title="Rimuovi da HA" style="color:#f87171;border-color:rgba(248,113,113,.3)"><i class="mdi mdi-delete-outline"></i> Rimuovi</button>`,
        badge
      );
    }).join('');
  } else {
    html+=`<div class="ghs-empty" style="padding:18px 0 10px">Nessun package installato su Home Assistant.<br><span style="font-size:10px;opacity:.5">I package vengono installati automaticamente quando installi una card che ne richiede uno.</span></div>`;
  }

  /* ── Disponibili su GitHub ── */
  if(ghFiles.length||ghNotHA.length){
    html+=`<div class="ghs-subhdr" style="display:flex;align-items:center;gap:8px;margin-top:10px"><i class="mdi mdi-github"></i> Disponibili su GitHub <span style="margin-left:auto;background:rgba(129,140,248,.12);border:1px solid rgba(129,140,248,.25);border-radius:8px;padding:2px 8px;font-size:10px;color:#818cf8">${ghFiles.length}</span></div>`;
    if(ghNotHA.length){
      html+=ghNotHA.map(f=>{
        const enc=encodeURIComponent(f.name);
        return pkgRow('frarik/'+f.name,'github',
          `<button class="ghs-btn ghs-btn-cp" data-action="_ghsCopy" data-action-arg="${enc}"><i class="mdi mdi-content-copy"></i> Copia</button>`+
          `<button class="ghs-btn ghs-btn-cp" data-action="_ghsPkgDownloadGh" data-action-arg="${enc}"><i class="mdi mdi-download"></i></button>`+
          `<button class="ghs-btn ghs-btn-inst" data-action="_ghsPkgInstallFromGH" data-action-arg="${enc}"><i class="mdi mdi-package-down"></i> Installa su HA</button>`
        );
      }).join('');
    } else if(ghFiles.length){
      html+=`<div class="ghs-empty" style="padding:10px 0">Tutti i package GitHub sono già installati su HA.</div>`;
    }
  }

  /* ── Upload ── */
  html+=`<div class="ghs-subhdr" style="margin-top:10px"><i class="mdi mdi-upload"></i> Carica package</div>`;
  html+=`<div style="display:flex;align-items:center;gap:10px;background:rgba(99,102,241,.07);border:1px dashed rgba(99,102,241,.3);border-radius:10px;cursor:pointer;padding:10px 16px" onclick="document.getElementById('ghs-pkg-file-inp').click()"><i class="mdi mdi-file-upload-outline" style="color:#818cf8;font-size:20px"></i><div><div style="color:#818cf8;font-size:12px;font-weight:600">Carica file .yaml da PC</div><div style="color:rgba(255,255,255,.35);font-size:10px;margin-top:2px">Poi installalo su HA o pubblicalo su GitHub</div></div><input type="file" id="ghs-pkg-file-inp" accept=".yaml,.yml" style="display:none"></div>`;
  html+=_pkgStoreList().filter(f=>!q||f.name.toLowerCase().includes(q.toLowerCase())).map(f=>{
    const nm=f.name.replace(/\.ya?ml$/i,''); const enc=encodeURIComponent(f.name);
    const isOnHA=_pkgIsOnHA('frarik/'+f.name)||_pkgIsOnHA(f.name);
    const pubBtn=f.origin==='github'?'':`<button class="ghs-btn ghs-btn-upd" data-action="_ghsPkgPublish" data-action-arg="${enc}"><i class="mdi mdi-upload"></i> Pubblica</button>`;
    const installBtn=isOnHA?'':`<button class="ghs-btn ghs-btn-inst" data-action="_pkgInstallLocalToHA" data-action-arg="${enc}"><i class="mdi mdi-package-down"></i> Installa su HA</button>`;
    const delBtn=`<button class="ghs-ibtn ghs-ibtn-del" data-action="_ghsPkgDeleteLocal" data-action-arg="${f.name}" title="Rimuovi dalla lista"><i class="mdi mdi-delete-outline"></i></button>`;
    return pkgRow(f.name,'local',`${installBtn}${pubBtn}<button class="ghs-btn ghs-btn-cp" data-action="_ghsPkgCopyLocal" data-action-arg="${f.name}"><i class="mdi mdi-content-copy"></i></button><button class="ghs-btn ghs-btn-cp" data-action="_ghsPkgDownloadLocal" data-action-arg="${f.name}"><i class="mdi mdi-download"></i></button>${delBtn}`);
  }).join('');

  list.innerHTML=html;
  const pkgInp=document.getElementById('ghs-pkg-file-inp');
  if(pkgInp&&!pkgInp._init){ pkgInp._init=true;
    pkgInp.addEventListener('change',function(){ const f=this.files[0]; this.value=''; if(!f) return; const r=new FileReader(); r.onload=ev=>_ghsPkgLoadFile(f.name,ev.target.result); r.readAsText(f); }); }
}

function _ghsPkgLoadFile(name, content){
  if(!/\.ya?ml$/i.test(name)){ showToast('⚠️ Il file deve essere .yaml o .yml'); return; }
  _pkgStoreSave(name, content, 'local');
  showToast('✅ "'+name+'" aggiunto allo store locale PKG');
  if(_isPkgTab()) _ghStoreRender();
}

async function _ghsPkgSaveLocal(encodedName){
  const name=decodeURIComponent(encodedName);
  const f=(_ghsCache.pkg||[]).find(x=>x.name===name); if(!f){ showToast('⚠️ File non trovato'); return; }
  showToast('⬇️ Scarico '+name+'…');
  let content; try{ content=await _ghDownload(f); }catch(e){ showToast('⚠️ '+e.message); return; }
  _pkgStoreSave(name, content, 'github');
  showToast('✅ "'+name+'" salvato in locale');
  if(_isPkgTab()) _ghStoreRender();
}

function _ghsPkgDeleteLocal(name){
  if(!confirm('Rimuovere "'+name+'" dallo store locale?')) return;
  _pkgStoreDelete(name);
  showToast('🗑️ "'+name+'" rimosso dallo store locale');
  if(_isPkgTab()) _ghStoreRender();
}

async function _ghsPkgUpdFromPending(encodedName){
  const fileName=decodeURIComponent(encodedName);
  /* 1. Trova il file PKG su GitHub — se il cache è vuoto/stale, ricarica prima di arrendersi */
  let f=(_ghsCache.pkg||[]).find(x=>x.name===fileName);
  if(!f){
    try{
      const fPkg=_GHS_FOLDERS['pkg'];
      const files=await _ghListFolder(fPkg.path);
      _ghsCache.pkg=files.filter(x=>fPkg.ext.test(x.name));
      f=_ghsCache.pkg.find(x=>x.name===fileName);
    }catch(e){}
  }
  if(!f){ showToast('⚠️ PKG «'+fileName+'» non trovato su GitHub'); return; }

  /* 2. Cerca la card associata e, se ha il wizard, aprilo con i valori pre-compilati */
  const cardId=_pkgFindCardForFile('frarik/'+fileName)||_pkgFindCardForFile(fileName);
  if(cardId){
    const _ctor=customElements.get(cardId);
    const _reg=window.FratechCardRegistry?.[cardId]??window.FratechCardRegistry?.[cardId.toLowerCase()];
    const CardClass=typeof _ctor?._buildPkgFromConfig==='function'?_ctor:(_reg??_ctor);
    if(typeof CardClass?.openWizard==='function'){
      showToast('⬇️ Scarico PKG da GitHub…');
      let yaml; try{ yaml=await _ghDownload(f); }catch(e){ showToast('⚠️ '+e.message); return; }
      if(!yaml){ showToast('⚠️ PKG vuoto'); return; }
      /* Apri wizard con template aggiornato — i valori precedenti vengono pre-compilati da localStorage */
      CardClass.openWizard(_haHassObj(),async()=>{
        /* onDone: l'installazione avviene dentro il wizard, qui aggiorniamo SHA/pending e chiediamo riavvio */
        try{
          const sha=_pkgPending[fileName]||_ghCfg().pkgNotifiedShas?.[fileName];
          if(sha){ const g=_ghCfg(); g.pkgShas=g.pkgShas||{}; g.pkgShas[fileName]=sha; saveCfg(); }
          delete _pkgPending[fileName];
        }catch(e){}
        try{ _ntfClearPkg(fileName); }catch(e){}
        try{ _ghsUpdBadge(); }catch(e){}
        try{ await _pkgPostInstall(cardId,null); }catch(e){}
        try{ await _loadHaInstalledPkgs(); if(typeof _ghStoreRender==='function') _ghStoreRender(); }catch(e){}
      }, yaml, {isUpdate:true});
      return;
    }
  }

  /* Fallback: card senza wizard → applica config salvata silenziosamente e installa */
  showToast('⬇️ Aggiorno PKG da GitHub…');
  let yaml; try{ yaml=await _ghDownload(f); }catch(e){ showToast('⚠️ '+e.message); return; }
  if(!yaml){ showToast('⚠️ PKG vuoto'); return; }
  try{
    if(cardId){
      const wizKey='frarik_pkg_wizard_'+cardId.toLowerCase();
      const savedCfg=JSON.parse(localStorage.getItem(wizKey)||'null');
      const _ctor=customElements.get(cardId);
      const _reg=window.FratechCardRegistry?.[cardId]??window.FratechCardRegistry?.[cardId.toLowerCase()];
      const CardClass=typeof _ctor?._buildPkgFromConfig==='function'?_ctor:(_reg??_ctor);
      if(savedCfg&&typeof CardClass?._buildPkgFromConfig==='function'){
        yaml=CardClass._buildPkgFromConfig(savedCfg,yaml)||yaml;
      }
    }
  }catch(e){}
  try{
    const m=location.pathname.match(/^(.*\/api\/hassio_ingress\/[^/]+)/);
    const base=location.origin+(m?m[1]:'');
    const r=await fetch(base+'/api/frarik/pkg/install',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:'frarik/'+fileName,content:yaml})});
    const j=await r.json().catch(()=>({}));
    if(r.ok&&j.ok){ showToast('✅ PKG aggiornato!'); }
    else{ showToast('⚠️ Errore PKG: '+(j.error||r.status)); return; }
  }catch(e){ showToast('⚠️ '+e.message); return; }
  try{
    const sha=_pkgPending[fileName]||_ghCfg().pkgNotifiedShas?.[fileName];
    if(sha){ const g=_ghCfg(); g.pkgShas=g.pkgShas||{}; g.pkgShas[fileName]=sha; saveCfg(); }
    delete _pkgPending[fileName];
  }catch(e){}
  try{ _ntfClearPkg(fileName); }catch(e){}
  try{ _ghsUpdBadge(); }catch(e){}
  try{ const el=document.getElementById('ghs-list'); if(el) _ghStoreRender(); }catch(e){}
}

function _ghsPkgCopyLocal(name){
  const it=_pkgStoreList().find(f=>f.name===name); if(!it){ showToast('⚠️ File non trovato'); return; }
  const txt=it.content;
  if(navigator.clipboard&&window.isSecureContext){
    navigator.clipboard.writeText(txt).then(()=>showToast('📋 "'+name+'" copiato negli appunti')).catch(()=>_ghsPkgCopyFallback(name,txt)); return;
  }
  _ghsPkgCopyFallback(name,txt);
}
function _ghsPkgCopyFallback(name,txt){
  const ta=document.createElement('textarea'); ta.value=txt; ta.style.cssText='position:fixed;top:-1000px;opacity:0';
  document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta);
  showToast('📋 "'+name+'" copiato negli appunti');
}

function _ghsPkgDownloadLocal(name){
  const it=_pkgStoreList().find(f=>f.name===name); if(!it){ showToast('⚠️ File non trovato'); return; }
  const b=new Blob([it.content],{type:'text/plain'}); const u=URL.createObjectURL(b);
  const a=document.createElement('a'); a.href=u; a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(u),1000);
  showToast('⬇️ Scarico '+name);
}

async function _ghsPkgDownloadGh(encodedName){
  const name=decodeURIComponent(encodedName);
  const f=(_ghsCache.pkg||[]).find(x=>x.name===name); if(!f){ showToast('⚠️ File non trovato'); return; }
  try{
    const txt=await _ghDownload(f);
    const b=new Blob([txt],{type:'text/plain'}); const u=URL.createObjectURL(b);
    const a=document.createElement('a'); a.href=u; a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(u),1000);
    showToast('⬇️ Scarico '+name);
  }catch(e){ showToast('⚠️ '+e.message); }
}

async function _ghsPkgPublish(encodedName){
  const name=decodeURIComponent(encodedName);
  const it=_pkgStoreList().find(f=>f.name===name); if(!it){ showToast('⚠️ File non trovato nello store locale'); return; }
  if(!_ghCfg().token){ showToast('🔑 Manca il token GitHub — configuralo con ⚙️'); openGitHubCfg(); return; }
  showToast('⏳ Pubblico su GitHub…');
  try{
    await _ghPut('pkg/'+name, it.content, 'Pubblica PKG '+name+' da Frarik');
    _pkgStoreSave(name, it.content, 'github');
    showToast('📤 "'+name+'" pubblicato in pkg/ su GitHub!');
    delete _ghsCache.pkg;
    if(_isPkgTab()) ghStoreTab(_ghsTab);
  }catch(e){ showToast('⚠️ '+e.message); }
}

async function _ghsPkgDeleteFromGithub(encodedName){
  const name=decodeURIComponent(encodedName);
  const nm=name.replace(/\.ya?ml$/i,'');
  if(!_ghCfg().token){ showToast('🔑 Manca il token GitHub'); openGitHubCfg(); return; }
  showConfirm(
    `Eliminare <b>DEFINITIVAMENTE</b> «${eh(nm)}» da GitHub?<br>`+
    `<span style="font-size:11px;opacity:.7;display:block;margin:6px 0 4px">Operazione irreversibile. Inserisci la chiave di accesso:</span>`+
    `<input id="ghdel-pkg-key" type="text" autocomplete="off" placeholder="Chiave di accesso" style="width:100%;padding:9px 11px;border-radius:9px;border:1px solid rgba(255,255,255,.18);background:rgba(255,255,255,.06);color:#fff;font-size:13px;font-family:inherit;letter-spacing:.5px">`,
    async ()=>{
      const key=((document.getElementById('ghdel-pkg-key')||{}).value||'').trim();
      if(key!==_GHDEL_KEY){ showToast('🔑 Chiave errata — eliminazione annullata'); return; }
      try{
        showToast('🗑 Elimino «'+nm+'» da GitHub…');
        await _ghDelete('pkg/'+name, 'Elimina PKG '+name+' dallo store (chiave verificata)');
        if(_ghsCache.pkg) _ghsCache.pkg=_ghsCache.pkg.filter(x=>x.name!==name);
        showToast('✅ «'+nm+'» eliminato definitivamente da GitHub');
        if(_isPkgTab()) _ghStoreRender();
      }catch(e){ showToast('⚠️ Errore eliminazione GitHub: '+(e.message||e)); }
    },
    'Elimina da GitHub', 'Annulla'
  );
}

function _ghSchedule(){
  clearInterval(_ghTimer);
  const g=_ghCfg();
  if(g.owner&&g.repo&&g.auto!==false){
    _ghTimer=setInterval(()=>{ if(!document.hidden) _ghCheck(false); }, 5*60*1000);
  }
}



/* ═══ WEBSOCKET ═══ */
let covTimer=null;
/* ── Connessione al backend dell'add-on ──
   Un solo target: il proxy dell'add-on (stessa origine + prefisso ingress), gated da licenza. */
let _connTargets=[], _connIdx=0, _connBusy=false, _connOk=false, _lastTriedHost='', _everConnected=false, _dashBuilt=false;
function _buildConnTargets(){
  return [{host:location.host, base:location.origin+INGRESS_BASE}];
}
function connect(){
  clearTimeout(covTimer); clearTimeout(reconn);
  if(_connIdx===0) _connTargets=_buildConnTargets();
  if(_connIdx>=_connTargets.length) _connIdx=0;
  _connBusy=true; _connOk=false;
  const tgt=_connTargets[_connIdx]; HA_HOST=tgt.host; BASE=tgt.base; _lastTriedHost=tgt.host;
  const cm=document.getElementById('cmsg'); if(cm) cm.textContent='Connessione…';
  covTimer=setTimeout(_connFail,12000);
  try{
    // URL WS sul proxy dell'add-on: prefisso ingress + chiave licenza (?lic=)
    const wsUrl = `${BASE.replace(/^http/,'ws')}/api/websocket?lic=${encodeURIComponent(localStorage.getItem(LIC_KEY)||'')}`;
    ws=new WebSocket(wsUrl);
    ws.onopen=()=>setC('wait');
    ws.onmessage=e=>onMsg(JSON.parse(e.data));
    ws.onclose=()=>{
      if(_connOk){ _connOk=false; setC('off'); clearTimeout(covTimer); Object.keys(_fcSubMap).forEach(k=>delete _fcSubMap[k]); reconn=setTimeout(connect,5000); }
      else _connFail();
    };
    ws.onerror=()=>{ try{ws.close();}catch(e){} };
  }catch(e){ _connFail(); }
}
function _connFail(){
  if(!_connBusy) return; _connBusy=false;
  clearTimeout(covTimer); setC('off');
  try{ ws.close(); }catch(e){}
  if(_connIdx<_connTargets.length-1){ _connIdx++; reconn=setTimeout(connect,300); return; }
  // tutti i target falliti
  _connIdx=0;
  if(_everConnected){
    // già connesso almeno una volta → riconnessione SILENZIOSA in background (solo pallino),
    // NON copriamo la plancia/header con l'overlay (così il tasto ☰ resta sempre visibile)
    reconn=setTimeout(connect,3000);
    return;
  }
  // Se manca la licenza valida → overlay licenza; altrimenti il backend (proxy) è
  // momentaneamente non pronto → ritenta in silenzio.
  const cm0=document.getElementById('cmsg');
  if(!localStorage.getItem(LIC_KEY)){
    const ov=document.getElementById('lic-overlay'); if(ov) ov.style.cssText+=';display:flex!important';
  } else if(cm0){
    cm0.innerHTML='⚠️ Backend non pronto<br><span style="font-size:10px;opacity:.6">riprovo…</span>';
  }
  reconn=setTimeout(connect,5000);
}
function send(p){ p.id=mid++; ws.send(JSON.stringify(p)); }
/* Promise-based WS request — usato per lovelace/resources, entity_registry, ecc. */
const _wsCbs={};
const _wsSubs={};   // id sottoscrizione → callback (per le card Lovelace: subscribeMessage)
function sendAndWait(p,timeout=10000){
  return new Promise(resolve=>{
    const id=mid++; const msg=Object.assign({},p,{id});
    _wsCbs[id]=resolve;
    try{ ws.send(JSON.stringify(msg)); }catch(e){ delete _wsCbs[id]; resolve(null); return; }
    setTimeout(()=>{ if(_wsCbs[id]){ delete _wsCbs[id]; resolve(null); } },timeout);
  });
}

/* ═══ FORECAST SUBSCRIPTION (HA 2023.9+) ═══ */
const _fcData={}; // entityId → forecast array
const _fcSubMap={}; // subscriptionId → entityId

function _subscribeForecast(entityId){
  if(!entityId||!ws||ws.readyState!==1) return;
  if(Object.values(_fcSubMap).includes(entityId)) return; // already subscribed
  const id=mid++;
  _fcSubMap[id]=entityId;
  ws.send(JSON.stringify({id,type:'weather/subscribe_forecast',forecast_type:'daily',entity_id:entityId}));
}
function _subscribeAllForecasts(){
  if(!cfg) return;
  cfg.pages.forEach(p=>(p.cards||[]).forEach(c=>{
    if((c.type==='weather'||c.type==='weather-forecast'||c.type==='weather-hero')&&c.entity)
      _subscribeForecast(c.entity);
  }));
}
function _refreshWeatherCards(entityId){
  curPage()?.cards?.filter(c=>c.entity===entityId&&(c.type==='weather'||c.type==='weather-forecast')).forEach(c=>{
    const w=document.getElementById('v-'+c.id); if(!w) return;
    if(_wtTimers[c.id]){ clearTimeout(_wtTimers[c.id]); delete _wtTimers[c.id]; }
    w.innerHTML=c.type==='weather-forecast'?weatherForecastInner(c):weatherCompactInner(c);
    _initWeatherBG(c.id, hs[entityId]||'unknown');
  });
}

function onMsg(m){
  if(m.type==='auth_required') ws.send(JSON.stringify({type:'auth',access_token:TOKEN}));
  else if(m.type==='auth_ok'){
    clearTimeout(covTimer);
    _connBusy=false; _connOk=true; _everConnected=true;   // connessione attiva → riconnessioni future in background
    setC('on');
    document.getElementById('cov').classList.add('off');
    const rbox=document.getElementById('cov-remote-box'); if(rbox) rbox.style.display='none';
    send({type:'get_states'});
    send({type:'subscribe_events',event_type:'state_changed'});
    _haLoadCfg(true);   // sincronizza la configurazione dai dati utente di HA
  }
  else if(m.type==='auth_invalid'){
    // In modalità add-on l'auth la fa il backend col Supervisor: qui non dovrebbe arrivare.
    // Se arriva, è un problema lato proxy → riprova in silenzio.
    _connBusy=false; _connOk=false;
    clearTimeout(covTimer); clearTimeout(reconn);
    setC('off');
    const cm=document.getElementById('cmsg'); if(cm) cm.textContent='Autenticazione non riuscita — riprovo…';
    reconn=setTimeout(connect,3000);
  }
  // (la sincronizzazione della plancia ora passa dagli endpoint HTTP dell'add-on,
  //  non più da frontend/set_user_data/get_user_data via WebSocket)
  else if(m.type==='result'&&Array.isArray(m.result)){
    m.result.forEach(e=>{ if(e&&e.entity_id){ hs[e.entity_id]=e.state; ha[e.entity_id]=e.attributes||{}; }});
    allE=m.result.filter(e=>e&&e.entity_id).sort((a,b)=>a.entity_id.localeCompare(b.entity_id));
    if(!_dashBuilt){
      // PRIMA costruzione della dashboard
      _dashBuilt=true;
      renderDash();
      try{ renderHdrChips(); }catch(e){}
      _restoreUIState();
      try{ _histInit(); }catch(e){}   // inizializza la cronologia Annulla/Ripeti
      try{ _ghSchedule(); setTimeout(()=>{ try{ _ghCheck(false); }catch(e){} }, 1000); }catch(e){}  // controllo aggiornamenti card GitHub
      try{ _haCompatInit(); }catch(e){}  // patch createElement per auto-mirror elementi HA
      setTimeout(()=>{ try{ _loadLovelaceResources(); }catch(e){} }, 500);  // carica risorse HACS (prima possibile)
      try{ _ntfUpdateBell(); }catch(e){}
    } else {
      // RICONNESSIONE: la dashboard è già costruita → aggiorna i VALORI in posto, niente rebuild (niente "scatto")
      try{ (curPage().cards||[]).forEach(c=>{ try{ updateCardEl(c); }catch(e){} }); }catch(e){}
      try{ renderBadgesAll(); }catch(e){}
    }
    _subscribeAllForecasts(); // subscribe after cfg+entities are loaded
  }
  // Forecast subscription event (HA 2023.9+)
  else if(m.type==='event'&&_fcSubMap[m.id]){
    const eid=_fcSubMap[m.id];
    const fc=m.event?.forecast;
    if(Array.isArray(fc)){ _fcData[eid]=fc; _refreshWeatherCards(eid); }
  }
  // eventi di sottoscrizione delle card Lovelace (connection.subscribeMessage)
  else if(m.type==='event'&&_wsSubs[m.id]){ try{ _wsSubs[m.id](m.event); }catch(e){} }
  else if(m.type==='event'&&m.event?.event_type==='state_changed'){
    const d=m.event.data;
    const prevState=hs[d.entity_id];
    hs[d.entity_id]=d.new_state?.state;
    ha[d.entity_id]=d.new_state?.attributes||{};
    liveUpdate(d.entity_id);
    _notifCheck(d.entity_id, prevState, d.new_state?.state);
  }
  // Risposta generica per sendAndWait()
  else if(m.id!=null && _wsCbs[m.id]){ const cb=_wsCbs[m.id]; delete _wsCbs[m.id]; cb(m); }
}
function setC(s){
  const dot=document.getElementById('conn-dot');
  const lbl=document.getElementById('conn-lbl');
  if(dot) dot.className='';
  if(s==='on'){dot?.classList.add('ok');if(lbl){lbl.textContent='Connesso';lbl.style.color='#4ade80';}}
  else if(s==='wait'){dot?.classList.add('wait');if(lbl){lbl.textContent='…';lbl.style.color='#fbbf24';}}
  else{if(lbl){lbl.textContent='Disconnesso';lbl.style.color='#f87171';}}
  // aggiorna chip conn nell'header bar
  document.querySelectorAll('.hbar-inner[data-id]').forEach(el=>{
    const card=curPage()?.cards?.find(c=>c.id===el.dataset.id);
    if(card&&(card.left||[]).concat(card.center||[],card.right||[]).some(ch=>ch?.type==='conn'))
      el.innerHTML=hbarInner(card);
  });
}
function callSvc(domain,svc,entityId,data={}){
  send({type:'call_service',domain,service:svc,service_data:{entity_id:entityId,...data}});
}

/* ═══ HISTORY API ═══ */
async function fetchHistory(entityId,hours=24){
  try{
    const start=new Date(Date.now()-hours*3600000).toISOString();
    const r=await fetch(`${BASE}/api/history/period/${start}?filter_entity_id=${entityId}&minimal_response=true&significant_changes_only=false`,
      {headers:{Authorization:`Bearer ${TOKEN}`}});
    const data=await r.json();
    return (data[0]||[]).map(p=>({t:new Date(p.last_changed),v:parseFloat(p.state)})).filter(p=>!isNaN(p.v));
  }catch(e){return[];}
}

/* ═══ CAMERA ═══ */
async function refreshCamera(cardId,entityId){
  try{
    const r=await fetch(`${BASE}/api/camera_proxy/${entityId}?_=${Date.now()}`,{headers:{Authorization:`Bearer ${TOKEN}`}});
    if(!r.ok) return;
    const blob=await r.blob();
    const img=document.getElementById('cam-'+cardId);
    if(!img) return;
    if(img._burl) URL.revokeObjectURL(img._burl);
    img._burl=URL.createObjectURL(blob);
    img.src=img._burl;
    img.style.display='block';
    const err=document.getElementById('camer-'+cardId);
    if(err) err.style.display='none';
  }catch(e){
    const err=document.getElementById('camer-'+cardId);
    if(err) err.style.display='flex';
  }
}
function startCamTimer(card){
  stopCamTimer(card.id);
  refreshCamera(card.id,card.entity);
  camTimers[card.id]=setInterval(()=>refreshCamera(card.id,card.entity),(card.refresh||5)*1000);
}
function stopCamTimer(id){ if(camTimers[id]){ clearInterval(camTimers[id]); delete camTimers[id]; } }

/* ═══ GAUGE SVG ═══ */
function gaugeSVG(value,min,max,color,unit){
  const pct=Math.min(1,Math.max(0,(parseFloat(value)-min)/(max-min)));
  const R=42,cx=60,cy=64;
  const startA=135,sweepA=270;
  function pt(a){ const r=a*Math.PI/180; return [cx+R*Math.cos(r),cy+R*Math.sin(r)]; }
  function arc(a1,a2,col,sw=8){
    const [x1,y1]=pt(a1),[x2,y2]=pt(a2);
    const large=(a2-a1)>180?1:0;
    return `<path d="M${x1},${y1} A${R},${R} 0 ${large} 1 ${x2},${y2}" fill="none" stroke="${col}" stroke-width="${sw}" stroke-linecap="round"/>`;
  }
  const endA=startA+sweepA*pct;
  const dispV=isNaN(parseFloat(value))?'—':(parseFloat(value)%1===0?parseFloat(value):parseFloat(value).toFixed(1));
  const isLight=cfg.theme==='light';
  const arcBg=isLight?'rgba(15,23,42,0.1)':'rgba(255,255,255,0.07)';
  const fillMain=isLight?'#0f172a':'white';
  const fillSub=isLight?'rgba(15,23,42,0.35)':'rgba(255,255,255,0.3)';
  const fillMin=isLight?'rgba(15,23,42,0.2)':'rgba(255,255,255,0.18)';
  const ff=`'${cfg.font||'Inter'}',sans-serif`;
  return `<svg viewBox="0 0 120 100" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:100%">
    ${arc(startA,startA+sweepA,arcBg)}
    ${pct>0?arc(startA,endA,color):''}
    <text x="${cx}" y="${cy-4}" text-anchor="middle" dominant-baseline="middle" fill="${fillMain}" font-size="19" font-weight="900" font-family="${ff}">${dispV}</text>
    <text x="${cx}" y="${cy+13}" text-anchor="middle" fill="${fillSub}" font-size="9" font-family="${ff}">${unit}</text>
    <text x="${cx}" y="94" text-anchor="middle" fill="${fillMin}" font-size="7" font-family="${ff}">${min} — ${max}</text>
  </svg>`;
}

/* ═══ FLOW BARS (stile app screenshot) ═══ */
function buildFlowBarsRows(card){
  const sVal=parseFloat(hs[card.solar]||0);
  const lVal=parseFloat(hs[card.load]||0);
  const gVal=parseFloat(hs[card.grid]||0);
  const bVal=card.battery?parseFloat(hs[card.battery]||0):null;
  const mx=card.max||6000;

  const rows=[];
  if(card.solar){
    const v=Math.max(0,sVal);
    rows.push({ico:'☀️',lbl:'Solare',sub:'',val:v,color:'#fbbf24',pct:Math.min(100,(v/mx)*100)});
  }
  if(card.grid){
    // positive = esportazione (inverter convention), negative = prelievo
    const isExp=gVal>=0;
    const v=Math.abs(gVal);
    rows.push({ico:isExp?'↑':'↓',lbl:isExp?'Immissione':'Prelievo',sub:isExp?'In rete':'Dalla rete',val:v,color:isExp?'#4ade80':'#f87171',pct:Math.min(100,(v/mx)*100)});
  }
  if(card.battery&&bVal!==null){
    const isCh=bVal>=0;
    const v=Math.abs(bVal);
    rows.push({ico:'🔋',lbl:'Batteria',sub:isCh?'In carica':'In scarica',val:v,color:isCh?'#60a5fa':'#fb923c',pct:Math.min(100,(v/mx)*100)});
  }
  if(card.load){
    const v=Math.max(0,lVal);
    rows.push({ico:'🏠',lbl:'Consumo',sub:'',val:v,color:'#818cf8',pct:Math.min(100,(v/mx)*100)});
  }

  return rows.map(r=>`
    <div class="fb-row">
      <div class="fb-top">
        <span class="fb-ico">${r.ico}</span>
        <span class="fb-lbl">${eh(r.lbl)}</span>
        ${r.sub?`<span class="fb-sub">${r.sub}</span>`:''}
        <span class="fb-val" style="color:${r.color}">${Math.round(r.val)}<span class="fb-u">W</span></span>
      </div>
      <div class="fb-track">
        <div class="fb-fill" style="width:${r.pct.toFixed(1)}%;background:${r.color}">
          <div class="fb-shim"></div>
        </div>
      </div>
    </div>`).join('');
}

/* ═══ FLOW MAP SVG (nodi animati) ═══ */
function flowMapSVG(card){
  const solar=Math.max(0,parseFloat(hs[card.solar]||0));
  const load=Math.max(0,parseFloat(hs[card.load]||0));
  const grid=parseFloat(hs[card.grid]||0);
  const bat=card.battery?parseFloat(hs[card.battery]||0):null;
  const fid='f'+card.id.slice(1,5);

  // Positions: solar(150,28) house(150,108) grid(38,108) bat(150,180)
  const nd={
    solar:{x:150,y:28,r:22,ico:'☀️',col:'#fbbf24',val:solar>0?Math.round(solar)+'W':''},
    house:{x:150,y:108,r:26,ico:'🏠',col:'#818cf8',val:load>0?Math.round(load)+'W':''},
    grid: {x:38,y:108,r:22,ico:'⚡',col:grid>=0?'#4ade80':'#f87171',val:Math.abs(grid)>5?Math.round(Math.abs(grid))+'W':''},
    ...(bat!==null?{bat:{x:150,y:180,r:22,ico:'🔋',col:bat>=0?'#60a5fa':'#fb923c',val:Math.round(Math.abs(bat))+'W'}}:{})
  };

  const makeDur=p=>Math.max(0.45,2.4-p/2000).toFixed(2);

  // Flows
  const flows=[];
  if(solar>0) flows.push({x1:150,y1:50,dx:0,dy:32,p:solar,col:'#fbbf24'});
  if(Math.abs(grid)>5){
    if(grid>=0) flows.push({x1:124,y1:108,dx:-64,dy:0,p:grid,col:'#4ade80'});   // export
    else        flows.push({x1:60,y1:108,dx:64,dy:0,p:-grid,col:'#f87171'});     // import
  }
  if(bat!==null&&Math.abs(bat)>5){
    if(bat>=0) flows.push({x1:150,y1:134,dx:0,dy:22,p:bat,col:'#60a5fa'});
    else       flows.push({x1:150,y1:158,dx:0,dy:-24,p:-bat,col:'#fb923c'});
  }

  let s=`<svg viewBox="0 0 300 210" xmlns="http://www.w3.org/2000/svg" style="width:100%;height:100%">`;
  s+=`<defs><filter id="${fid}"><feGaussianBlur stdDeviation="2.5" result="b"/><feMerge><feMergeNode in="b"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>`;

  // Background connection lines
  const _fmLine=cfg.theme==='light'?'rgba(15,23,42,0.1)':'rgba(255,255,255,0.06)';
  s+=`<line x1="150" y1="50" x2="150" y2="82" stroke="${_fmLine}" stroke-width="8" stroke-linecap="round"/>`;
  s+=`<line x1="60" y1="108" x2="124" y2="108" stroke="${_fmLine}" stroke-width="8" stroke-linecap="round"/>`;
  if(bat!==null) s+=`<line x1="150" y1="134" x2="150" y2="158" stroke="${_fmLine}" stroke-width="8" stroke-linecap="round"/>`;

  // Animated dots
  flows.forEach(f=>{
    const dur=makeDur(f.p);
    for(let i=0;i<3;i++){
      const del=(i*parseFloat(dur)/3).toFixed(2);
      s+=`<circle cx="${f.x1}" cy="${f.y1}" r="4.5" fill="${f.col}" opacity="0" filter="url(#${fid})">
        <animateMotion dur="${dur}s" begin="${del}s" repeatCount="indefinite" path="M0,0 L${f.dx},${f.dy}"/>
        <animate attributeName="opacity" values="0;0.95;0.95;0" keyTimes="0;0.08;0.88;1" dur="${dur}s" begin="${del}s" repeatCount="indefinite"/>
      </circle>`;
    }
  });

  // Node circles + icons + values
  Object.values(nd).forEach(n=>{
    s+=`<circle cx="${n.x}" cy="${n.y}" r="${n.r}" fill="${n.col}1c" stroke="${n.col}" stroke-width="1.5"/>`;
    s+=`<text x="${n.x}" y="${n.y+1}" text-anchor="middle" dominant-baseline="middle" font-size="${n.r>22?16:14}">${n.ico}</text>`;
    if(n.val) s+=`<text x="${n.x}" y="${n.y+n.r+9}" text-anchor="middle" fill="${n.col}" font-size="8.5" font-weight="700" font-family="Inter,sans-serif">${n.val}</text>`;
  });

  s+=`</svg>`;
  return s;
}

/* ═══ WEATHER HTML ═══ */
function weatherInner(entityId,color){
  const st=hs[entityId]||'unknown';
  const at=ha[entityId]||{};
  const ico=WI[st]||'🌡️';
  const temp=at.temperature!==undefined?at.temperature+'°':'?°';
  const hum=at.humidity!==undefined?at.humidity+'%':'';
  const wind=at.wind_speed!==undefined?Math.round(at.wind_speed)+' km/h':'';
  const cond=_stateIt(st);
  return `<div class="wth-ico" style="color:${color}">${ico}</div>
    <div class="wth-temp" style="color:${color}">${temp}</div>
    <div class="wth-cond">${cond}</div>
    <div class="wth-row">
      ${hum?`<span class="wth-chip">💧 ${hum}</span>`:''}
      ${wind?`<span class="wth-chip">💨 ${wind}</span>`:''}
      ${at.pressure?`<span class="wth-chip">🌡 ${at.pressure} hPa</span>`:''}
    </div>`;
}

/* ═══ WEATHER-HERO HTML ═══ */
function weatherHeroInner(card){
  const eid=card.entity;
  const st=hs[eid]||'unknown';
  const at=ha[eid]||{};
  const color=card.color||wColor(st);
  const ico=WI[st]||'🌡️';
  const temp=card.entity2&&hs[card.entity2]!==undefined?hs[card.entity2]+'°':(at.temperature!==undefined?at.temperature+'°':'?°');
  const hum=card.entity3&&hs[card.entity3]!==undefined?hs[card.entity3]+'%':(at.humidity!==undefined?at.humidity+'%':'');
  const wind=at.wind_speed!==undefined?Math.round(at.wind_speed)+' km/h':'';
  const cond=_stateIt(st);
  const wc=wClass(st);
  return `<div class="wth-hero-inner mp-wico ${wc}" style="color:${color}">
    <span class="wth-hero-ico">${ico}</span>
    <div class="wth-hero-temp" style="color:${color}">${temp}</div>
    <div class="wth-hero-cond">${cond}</div>
    <div class="wth-row">
      ${hum?`<span class="wth-chip">💧 ${hum}</span>`:''}
      ${wind?`<span class="wth-chip">💨 ${wind}</span>`:''}
      ${at.pressure?`<span class="wth-chip">🌡 ${Math.round(at.pressure)} hPa</span>`:''}
    </div>
  </div>`;
}

/* ═══ WEATHER-COMPACT HTML ═══ */
function weatherCompactInner(card){
  const eid=card.entity;
  const st=hs[eid]||'unknown';
  const at=ha[eid]||{};
  const rawFc=_fcData[eid]||at.forecast||[];
  const maxDays=Math.min(parseInt(card.wfDays)||7, rawFc.length||7);
  const fc=rawFc.slice(0,maxDays);
  const cond=_stateIt(st);
  const city=(card.label||'Meteo').toUpperCase();
  const grad=_wtGrad(st);
  const dayNames=['dom','lun','mar','mer','gio','ven','sab'];
  function _fmtT(v){ const n=parseFloat(v); return isNaN(n)?null:n.toFixed(1).replace('.',',')+'°C'; }
  const temp = card.wfTemp&&hs[card.wfTemp]!==undefined ? _fmtT(hs[card.wfTemp])
              : at.temperature!==undefined ? _fmtT(at.temperature) : null;
  const hum  = card.wfHum&&hs[card.wfHum]!==undefined  ? Math.round(parseFloat(hs[card.wfHum]))+'%'
              : at.humidity!==undefined ? Math.round(at.humidity)+'%' : null;
  const wind = card.wfWind&&hs[card.wfWind]!==undefined ? Math.round(parseFloat(hs[card.wfWind]))+' km/h'
              : at.wind_speed!==undefined ? Math.round(at.wind_speed)+' km/h' : null;
  const fcHTML=fc.length?fc.map(d=>{
    const dt=new Date(d.datetime);
    const ico=WI[d.condition||'unknown']||'🌡️';
    const hi=d.temperature!==undefined?Math.round(d.temperature)+'°C':'';
    const lo=d.templow!==undefined?Math.round(d.templow)+'°C':'';
    return `<div class="wtc-fc-day">
      <div class="wtc-fc-dname">${dayNames[dt.getDay()]}</div>
      <div class="wtc-fc-ico">${ico}</div>
      <div class="wtc-fc-hi">${hi}</div>
      <div class="wtc-fc-lo">${lo}</div>
    </div>`;
  }).join(''):'';
  return `<div class="wtc-inner" id="wtci-${card.id}" style="background:${grad}">
    <div class="wtc-bg" id="wtcbg-${card.id}"></div>
    <div class="wtc-content">
      <div class="wtc-hdr">
        <div class="wtc-title-block">
          <div class="wtc-city">${eh(city)}</div>
          <div class="wtc-cond-lbl">${eh(cond)}</div>
        </div>
        <div class="wtc-stats-row">
          ${temp?`<span class="wtc-stat-chip">🌡️ ${temp}</span>`:''}
          ${hum ?`<span class="wtc-stat-chip">💧 ${hum}</span>`:''}
          ${wind?`<span class="wtc-stat-chip">💨 ${wind}</span>`:''}
        </div>
      </div>
      ${fcHTML?`<div class="wtc-sep"></div><div class="wtc-forecast">${fcHTML}</div>`:''}
    </div>
  </div>`;
}

/* ═══ WEATHER-FORECAST HTML ═══ */
function weatherForecastInner(card){
  const eid=card.entity;
  const st=hs[eid]||'unknown';
  const at=ha[eid]||{};
  const rawFc=_fcData[eid]||at.forecast||[];
  const maxDays=Math.min(parseInt(card.wfDays)||7,rawFc.length||7);
  const fc=rawFc.slice(0,maxDays);
  if(!fc.length) return `<div style="display:flex;align-items:center;justify-content:center;height:100%;opacity:.35;font-size:12px;gap:6px;color:#fff">📅 Previsioni non disponibili</div>`;
  const dayNames=['dom','lun','mar','mer','gio','ven','sab'];
  const city=(card.label||'Meteo').toUpperCase();
  const cond=_stateIt(st);
  function _fmtTemp(v){ const n=parseFloat(v); return isNaN(n)?null:n.toFixed(1).replace('.',',')+'°C'; }
  const temp= card.wfTemp&&hs[card.wfTemp]!==undefined ? _fmtTemp(hs[card.wfTemp])
             : at.temperature!==undefined ? _fmtTemp(at.temperature) : null;
  const hum = card.wfHum&&hs[card.wfHum]!==undefined  ? Math.round(parseFloat(hs[card.wfHum]))+'%'
             : at.humidity!==undefined ? Math.round(at.humidity)+'%' : null;
  const wind= card.wfWind&&hs[card.wfWind]!==undefined ? Math.round(parseFloat(hs[card.wfWind]))+' km/h'
             : at.wind_speed!==undefined ? Math.round(at.wind_speed)+' km/h' : null;
  return `<div class="wfc-wrap">
    <div class="wfc-header">
      <div>
        <div class="wfc-city">${eh(city)}</div>
        <div class="wfc-sub">${eh(cond)}</div>
      </div>
      <div class="wfc-hstats">
        ${temp?`<span class="wfc-hstat"><span class="wfc-hstat-ico">🌡️</span>${temp}</span>`:''}
        ${hum ?`<span class="wfc-hstat"><span class="wfc-hstat-ico">💧</span>${hum}</span>`:''}
        ${wind?`<span class="wfc-hstat"><span class="wfc-hstat-ico">💨</span>${wind}</span>`:''}
      </div>
    </div>
    <div class="wfc-sep"></div>
    <div class="wfc-days">`+fc.map(d=>{
      const dt=new Date(d.datetime);
      const ico=WI[d.condition||'unknown']||'🌡️';
      const hi=d.temperature!==undefined?Math.round(d.temperature)+'°C':'';
      const lo=d.templow!==undefined?Math.round(d.templow)+'°C':'';
      return `<div class="wfc-day">
        <div class="wfc-dname">${dayNames[dt.getDay()]}</div>
        <div class="wfc-ico">${ico}</div>
        <div class="wfc-hi">${hi}</div>
        <div class="wfc-lo">${lo}</div>
      </div>`;
    }).join('')+`</div>
  </div>`;
}

