/* ── Error feedback visibile all'utente ─────────────────────────────────── */
(function _initErrorFeedback(){
  let _errBusy=false, _errCount=0, _errReset=0;
  function _pushErr(title, msg){
    if(_errBusy) return;
    const now=Date.now();
    if(now-_errReset>10000){ _errCount=0; _errReset=now; }
    if(_errCount++>3) return; // max 3 errori ogni 10s
    _errBusy=true;
    try{ _ntfPushLog(title, msg, '🔴', null, {}); }catch(_){}
    _errBusy=false;
  }
  // Ignora errori da script esterni (HACS cards, HA components, ecc.)
  function isExternal(src){
    const f=(src||'').toLowerCase();
    // Solo errori dal bundle Frarik (index-*.js) o senza sorgente
    return f && !f.includes('index-') && !f.includes('frarik');
  }
  // Errori noti da card con pattern ES5 o da browser interni — da ignorare
  const _KNOWN_CARD_ERRS = /Failed to construct.*HTMLElement|Please use the 'new' operator|CustomElementRegistry|already been used with this registry|exitFullscreen|exitfullscreen|ResizeObserver/i;
  window.onerror = function(msg, src, line, col, err){
    if(isExternal(src)) return false; // errore da script terzo — ignora
    const fullMsg=err instanceof Error?(err.message||msg):String(msg||'');
    if(_KNOWN_CARD_ERRS.test(fullMsg)) return false; // errore noto da card/browser — ignora
    const file=(src||'').split('/').pop();
    const detail=file?file+':'+line+(col?':'+col:'')+'  '+fullMsg:fullMsg;
    _pushErr('⚠️ Errore JS', detail);
    return false;
  };
  window.addEventListener('unhandledrejection', function(e){
    const msg=e.reason instanceof Error?e.reason.message:String(e.reason||'Promise rejection');
    if(_KNOWN_CARD_ERRS.test(msg)) return; // usa lo stesso filtro di onerror
    _pushErr('⚠️ Errore asincrono', msg);
  });
})();

/* ── Delegation input/change (ex oninput/onchange nei template) ────────────── */
(function(){
  function _inputDelegate(e){
    const el = e.target;
    const fn  = el.dataset.input;   if(!fn) return;
    const arg = el.dataset.inputArgs;
    const num = el.dataset.inputNum;
    const val = el.type==='checkbox' ? el.checked : (num ? +el.value : el.value);
    if(typeof window[fn]==='function'){
      arg ? window[fn](...JSON.parse(arg), val) : window[fn](val);
    }
  }
  document.addEventListener('input',  _inputDelegate);
  document.addEventListener('change', _inputDelegate);

  // Layout resize from js-custom cards (e.g. Meteo) — salvato in localStorage device-locale
  // NON sincronizzato su HA: ogni dispositivo mantiene le proprie dimensioni
  document.addEventListener('frarik-card-layout', e=>{
    const {cardId,cardScale,cardW}=e.detail||{};
    if(!cardId) return;
    const cardEl=document.getElementById('card-'+cardId);
    const ll=JSON.parse(localStorage.getItem('_frk_layout_'+cardId)||'{}');
    if(cardScale!=null){ ll.cardScale=cardScale; if(cardEl) cardEl.style.zoom=cardScale<100?cardScale+'%':''; }
    if(cardW!=null){ ll.cardW=cardW; if(cardEl){ cardEl.style.width=cardW<100?cardW+'%':''; cardEl.style.maxWidth=cardW<100?cardW+'%':''; } }
    localStorage.setItem('_frk_layout_'+cardId, JSON.stringify(ll));
  });
})();

