function _epToggleLicense(){
  const box   = document.getElementById('ep-lic-box');
  const arrow = document.getElementById('ep-lic-arrow');
  if(!box) return;
  const open = box.style.display === 'none';
  box.style.display   = open ? 'block' : 'none';
  if(arrow) arrow.className = 'mdi mdi-chevron-' + (open ? 'up' : 'down');
  if(open) _epLicFill();
}

function _epLicFill(){
  const key = localStorage.getItem('frarik_license') || '';
  if(!key) return;
  const masked = key.slice(0,5) + '****-****-' + key.slice(-4);
  const el = id => document.getElementById(id);
  if(el('ep-lic-key')) el('ep-lic-key').textContent = masked;

  // Fetch live per dati sempre aggiornati
  fetch(LICENSE_API, {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify({key})})
    .then(r => r.json())
    .then(d => {
      if(!d.valid){ if(el('ep-lic-status')){ el('ep-lic-status').textContent='● REVOCATO'; el('ep-lic-status').style.cssText='font-size:11px;font-weight:700;padding:3px 10px;border-radius:10px;background:rgba(248,113,113,.1);color:#f87171'; } return; }
      // Salva dati aggiornati
      localStorage.setItem('frarik_lic_name', d.name||'');
      localStorage.setItem('frarik_lic_note', d.note||'');
      localStorage.setItem('frarik_lic_expires', d.expires||'');
      const note    = d.note || '';
      const expires = d.expires;
      const expFmt  = expires ? new Date(expires).toLocaleDateString('it-IT',{day:'numeric',month:'long',year:'numeric'}) : 'Nessuna scadenza';
      const level   = note ? ('👑 ' + note.charAt(0).toUpperCase() + note.slice(1)) : '⭐ Standard';
      if(el('ep-lic-name'))    el('ep-lic-name').textContent    = d.name || '—';
      if(el('ep-lic-expires')) el('ep-lic-expires').textContent = expFmt;
      if(el('ep-lic-level'))   el('ep-lic-level').textContent   = level;
    })
    .catch(() => {
      // Offline: usa dati salvati
      const name    = localStorage.getItem('frarik_lic_name') || '—';
      const note    = localStorage.getItem('frarik_lic_note') || '';
      const expires = localStorage.getItem('frarik_lic_expires');
      const expFmt  = expires && expires !== 'null' ? new Date(parseInt(expires)).toLocaleDateString('it-IT',{day:'numeric',month:'long',year:'numeric'}) : 'Nessuna scadenza';
      const level   = note ? ('👑 ' + note.charAt(0).toUpperCase() + note.slice(1)) : '⭐ Standard';
      if(el('ep-lic-name'))    el('ep-lic-name').textContent    = name;
      if(el('ep-lic-expires')) el('ep-lic-expires').textContent = expFmt;
      if(el('ep-lic-level'))   el('ep-lic-level').textContent   = level;
    });
}

function _epLicLogout(){
  if(!confirm('Vuoi cambiare la chiave di licenza?\nDovrai reinserirla al prossimo accesso.')) return;
  localStorage.removeItem('frarik_license');
  localStorage.removeItem('frarik_license_ts');
  localStorage.removeItem('frarik_lic_name');
  localStorage.removeItem('frarik_lic_expires');
  location.reload();
}

/* ── Badge Licenza con dinosauro ─────────────────────────────────────────── */
const LIC_DINOS=[
  {n:'T-Rex',        e:'🦖',c:'#ef4444',g1:'#450a0a',g2:'#7f1d1d',d:'Feroce e leggendario'},
  {n:'Brontosauro',  e:'🦕',c:'#22c55e',g1:'#052e16',g2:'#14532d',d:'Gentile e maestoso'},
  {n:'Velociraptor', e:'🦖',c:'#f97316',g1:'#431407',g2:'#7c2d12',d:'Veloce e astuto'},
  {n:'Triceratopo',  e:'🦕',c:'#a855f7',g1:'#2e1065',g2:'#4c1d95',d:'Coraggioso e fiero'},
  {n:'Stegosauro',   e:'🦕',c:'#3b82f6',g1:'#172554',g2:'#1e3a8a',d:'Curioso e affidabile'},
  {n:'Pterodattilo', e:'🦖',c:'#06b6d4',g1:'#083344',g2:'#0e4f6c',d:'Libero e intuitivo'},
  {n:'Ankilosauro',  e:'🦕',c:'#eab308',g1:'#422006',g2:'#713f12',d:'Solido e protettivo'},
  {n:'Spinosauro',   e:'🦖',c:'#ec4899',g1:'#4a044e',g2:'#701a75',d:'Elegante e audace'},
];
function _licDinoFor(name, noteOverride){
  const n=(noteOverride!==undefined?noteOverride:(localStorage.getItem('frarik_lic_note')||'')).toLowerCase();
  if(n.includes('admin')||n.includes('amministratore')) return LIC_DINOS[0]; // T-Rex sempre per Admin
  let h=0; for(let i=0;i<(name||'').length;i++) h=(h*31+name.charCodeAt(i))&0xffffffff;
  return LIC_DINOS[Math.abs(h)%LIC_DINOS.length];
}
function _licBadgeHtml({name,note,expires,key,dino,isPrem,isAdm}){
  const c=dino.c;
  const alpha=(a)=>{
    const r=parseInt(c.slice(1,3),16),g=parseInt(c.slice(3,5),16),b=parseInt(c.slice(5,7),16);
    return `rgba(${r},${g},${b},${a})`;
  };
  const masked=key?(key.slice(0,5)+'****-****-'+key.slice(-4)):'—';
  const expFmt=expires&&expires!=='null'?new Date(isNaN(expires)?expires:parseInt(expires)).toLocaleDateString('it-IT',{day:'numeric',month:'short',year:'numeric'}):'Nessuna scadenza';
  const level=isAdm?'🛡️ Admin + Premium':isPrem?'💎 Premium':'⭐ Standard';
  const upgBtn=(!isPrem&&!isAdm)?`<button data-action="openPremiumPage" style="width:100%;padding:12px;border-radius:12px;background:linear-gradient(135deg,rgba(251,191,36,.2),rgba(251,191,36,.06));border:1px solid rgba(251,191,36,.4);color:#fbbf24;font-size:13px;font-weight:800;cursor:pointer;letter-spacing:.3px;margin-bottom:10px">💎 Passa a Premium</button>`:'';
  return `<div style="width:100%;border-radius:24px;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,.6);background:linear-gradient(135deg,${dino.g1} 0%,${dino.g2} 100%);border:1px solid ${alpha(.3)};position:relative">
  <!-- decorazioni sfondo -->
  <div style="position:absolute;top:-30px;right:-30px;width:180px;height:180px;border-radius:50%;background:${alpha(.07)};pointer-events:none"></div>
  <div style="position:absolute;bottom:-20px;left:-20px;width:120px;height:120px;border-radius:50%;background:${alpha(.05)};pointer-events:none"></div>
  <!-- Header: nome utente + dinosauro + livello -->
  <div style="padding:28px 28px 18px;display:flex;align-items:center;gap:20px;position:relative">
    <!-- Dino come elemento decorativo laterale -->
    <div style="font-size:90px;line-height:1;filter:drop-shadow(0 6px 18px rgba(0,0,0,.6));flex-shrink:0">${dino.e}</div>
    <div style="flex:1;min-width:0">
      <!-- NOME UTENTE come testo principale -->
      <div style="font-size:11px;font-weight:800;letter-spacing:2px;color:${alpha(.6)};text-transform:uppercase;margin-bottom:4px">Abbonato</div>
      <div style="font-size:26px;font-weight:900;color:#fff;letter-spacing:-.5px;line-height:1.1;word-break:break-word">${eh(name||'—')}</div>
      <!-- Dino name come soprannome secondario -->
      <div style="font-size:12px;color:${alpha(.5)};margin-top:5px;font-style:italic">${eh(dino.e)} ${eh(dino.n)} — ${eh(dino.d)}</div>
    </div>
    <!-- Badge livello -->
    <div style="padding:6px 14px;border-radius:22px;background:${alpha(.22)};border:1px solid ${alpha(.45)};font-size:12px;font-weight:800;color:${c};letter-spacing:.5px;white-space:nowrap;flex-shrink:0;align-self:flex-start">${level}</div>
  </div>
  <div style="height:1px;background:${alpha(.18)};margin:0 28px"></div>
  <!-- Info scadenza + chiave -->
  <div style="padding:18px 28px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px">
      <div style="font-size:11px;color:${alpha(.5)};font-weight:700;letter-spacing:.8px;text-transform:uppercase">Scadenza</div>
      <div style="font-size:14px;font-weight:800;color:${c}">${eh(expFmt)}</div>
    </div>
    <div style="height:1px;background:${alpha(.1)};margin:12px 0"></div>
    ${upgBtn}
    <button data-action="_epLicLogout" style="width:100%;padding:11px;border-radius:12px;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.13);color:#fff;font-size:12px;font-weight:700;cursor:pointer">🔄 Cambia licenza</button>
  </div>
  <!-- Footer -->
  <div style="padding:12px 28px 18px;display:flex;align-items:center;gap:10px;border-top:1px solid ${alpha(.1)}">
    <img src="./logo-v2.png?v=1.1.93" style="height:22px;width:auto;opacity:.5">
    <span style="font-size:11px;color:${alpha(.4)};font-weight:700;letter-spacing:1.2px">FRARIK DASHBOARD</span>
    <span style="margin-left:auto;font-size:10px;color:${alpha(.3)};font-family:monospace">${masked}</span>
  </div>
</div>`;
}
function _epLicBadgeLoad(){
  const wrap=document.getElementById('lic-badge-wrap'); if(!wrap) return;
  const key=localStorage.getItem('frarik_license')||'';
  const name=localStorage.getItem('frarik_lic_name')||'Utente Frarik';
  const note=(localStorage.getItem('frarik_lic_note')||'').toLowerCase();
  const expires=localStorage.getItem('frarik_lic_expires')||'';
  const isPrem=_isPremiumLic(); const isAdm=_isAdmin();
  const dino=_licDinoFor(name);
  wrap.innerHTML=_licBadgeHtml({name,note,expires,key,dino,isPrem,isAdm});
  // Fetch live per aggiornare
  if(!key) return;
  fetch(LICENSE_API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({key})})
    .then(r=>r.json()).then(d=>{
      if(!d.valid) return;
      localStorage.setItem('frarik_lic_name',d.name||'');
      localStorage.setItem('frarik_lic_note',d.note||'');
      localStorage.setItem('frarik_lic_expires',d.expires||'');
      const n2=d.name||name; const note2=(d.note||'').toLowerCase();
      const dino2=_licDinoFor(n2, note2);
      const isPrem2=note2.includes('premium')||note2.includes('admin')||note2.includes('amministratore');
      const isAdm2=note2.includes('admin')||note2.includes('amministratore');
      wrap.innerHTML=_licBadgeHtml({name:n2,note:note2,expires:d.expires||expires,key,dino:dino2,isPrem:isPrem2,isAdm:isAdm2});
    }).catch(()=>{});
}

