        <textarea id="vnss-sensors" rows="4" style="${inpB};resize:vertical" placeholder="Un entity_id per riga&#10;es: sensor.temperatura_casa&#10;sensor.consumo_kw">${(v.extraSensors||[]).join('\n')}</textarea>
